    /**
     * Detect and validate URL parameter mode (customerid, estimateid, salesorderid, taskid)
     */
    function detectURLParameterMode(requestParameters) {
        try {
            const customerId = requestParameters.customerid;
            const estimateId = requestParameters.estimateid;
            const salesOrderId = requestParameters.salesorderid;
            const taskId = requestParameters.taskid;

            // Check for multiple parameters (invalid state)
            const parameterCount = [customerId, estimateId, salesOrderId, taskId].filter((param) => param).length;
            if (parameterCount > 1) {
                log.error('Multiple record type parameters detected', {
                    customerId: customerId,
                    estimateId: estimateId,
                    salesOrderId: salesOrderId,
                    taskId: taskId
                });
                return {
                    detected: false,
                    error: 'Multiple record type parameters are not allowed'
                };
            }

            // No special parameters detected
            if (parameterCount === 0) {
                return {
                    detected: false
                };
            }

            // Validate and return the detected mode
            if (customerId) {
                return {
                    detected: true,
                    mode: 'customer',
                    recordId: customerId,
                    recordType: 'customer'
                };
            }

            if (estimateId) {
                return {
                    detected: true,
                    mode: 'estimate',
                    recordId: estimateId,
                    recordType: 'estimate'
                };
            }

            if (salesOrderId) {
                return {
                    detected: true,
                    mode: 'salesorder',
                    recordId: salesOrderId,
                    recordType: 'salesorder'
                };
            }

            if (taskId) {
                return {
                    detected: true,
                    mode: 'task',
                    recordId: taskId,
                    recordType: 'task'
                };
            }

            return {
                detected: false
            };
        } catch (error) {
            log.error('Error detecting URL parameter mode', {
                error: error.message,
                stack: error.stack,
                parameters: requestParameters
            });
            return {
                detected: false,
                error: error.message
            };
        }
    }

