    /**
     * Load record data by mode - factory function that calls appropriate loader
     */
    function loadRecordByMode(modeResult) {
        try {
            if (!modeResult.detected) {
                return {
                    success: false,
                    error: 'No valid mode detected'
                };
            }

            /* 
            log.audit('Loading record by mode', {
                mode: modeResult.mode,
                recordType: modeResult.recordType,
                recordId: modeResult.recordId
            }); */

            switch (modeResult.mode) {
                case 'customer':
                    return getCustomerRecord(modeResult.recordId);

                case 'estimate':
                    return getEstimateRecord(modeResult.recordId);

                case 'salesorder':
                    return getSalesOrderRecord(modeResult.recordId);

                case 'task':
                    return getTaskRecord(modeResult.recordId);

                default:
                    log.error('Unknown mode type', { mode: modeResult.mode });
                    return {
                        success: false,
                        error: 'Unknown mode type: ' + modeResult.mode
                    };
            }
        } catch (error) {
            log.error('Error in loadRecordByMode', {
                error: error.message,
                stack: error.stack,
                modeResult: modeResult
            });
            return {
                success: false,
                error: error.message || 'Failed to load record by mode'
            };
        }
    }

