    /**
     * Get all active employees filtered by specific roles and sales rep status
     * Filters for employees with roles: .cabinetdirect, .cabinetdirect Manager, .KB Store Manager, .KB sales-team member
     * Additionally filters for employees with salesrep field checked
     * Uses fallback pattern matching if exact role names don't match
     * Prevents duplicate employees using internal ID deduplication
     */
    function getActiveEmployees() {
        try {
            // Define the target roles to filter by
            const targetRoles = ['.cabinetdirect', '.cabinetdirect Manager', '.KB Store Manager', '.KB sales-team member'];

            // Debug: Log the role filter being applied
            /*             log.debug('getActiveEmployees', {
                message: 'Filtering employees by roles and sales rep status',
                roles: targetRoles,
                isSalesRepFilter: true
            }); */

            // Create search without role filter since we need to filter by role names, not IDs
            let employeeSearch = search.create({
                type: search.Type.EMPLOYEE,
                filters: [['isinactive', 'is', 'F'], 'AND', ['releasedate', 'isempty', ''], 'AND', ['salesrep', 'is', 'T']],
                columns: ['internalid', 'entityid', 'altname', 'title', 'location', 'locationnohierarchy', 'custentity_preferred_first_name', 'custentity_preferred_last_name', 'custentity_preferred_name', 'role']
            });

            // We'll filter by role names in the result processing instead
            let resultCount = 1; // Force processing to always happen

            /* 
            log.debug('Role Search Results', {
                message: 'Initial role search results',
                resultCount: resultCount
            }); */

            const employees = [];
            const employeeIds = new Set(); // Track unique employee IDs to prevent duplicates

            employeeSearch.run().each(function (result) {
                const preferredFirstName = result.getValue('custentity_preferred_first_name') || '';
                const preferredLastName = result.getValue('custentity_preferred_last_name') || '';
                const preferredName = result.getValue('custentity_preferred_name') || '';
                const altName = result.getText('altname') || '';
                const entityId = result.getValue('entityid') || '';
                const roleName = result.getText('role') || '';
                const roleId = result.getValue('role') || '';
                const employeeId = result.getValue('internalid');

                // Check for duplicates based on internal ID
                if (employeeIds.has(employeeId)) {
                    /*                     log.debug('Duplicate Employee Skipped', {
                        employeeId: employeeId,
                        entityId: entityId,
                        roleName: roleName
                    }); */
                    return true; // Skip this duplicate employee
                }

                // Debug: Log role information for verification
                /*                 log.debug('Employee Role Debug', {
                    employee: entityId,
                    employeeId: employeeId,
                    roleName: roleName,
                    roleId: roleId
                }); */

                // Filter by role name patterns since we're doing client-side filtering
                const roleNameLower = roleName.toLowerCase();
                const isTargetRole = targetRoles.some((role) => {
                    const roleLower = role.toLowerCase();
                    return roleNameLower.includes('cabinetdirect') || roleNameLower.includes('kb store manager') || roleNameLower.includes('kb sales') || roleNameLower.includes('sales-team') || roleLower === roleNameLower;
                });

                if (!isTargetRole) {
                    return true; // Skip this employee
                }

                /*
                log.debug('Employee Role Match', {
                    employee: entityId,
                    roleName: roleName,
                    matched: 'pattern'
                }); */

                let displayName = '';
                if (preferredName) {
                    // Use the single preferred name field if available
                    displayName = preferredName;
                } else if (preferredFirstName && preferredLastName) {
                    // Fall back to combining first and last preferred names
                    displayName = preferredFirstName + ' ' + preferredLastName;
                } else if (preferredFirstName) {
                    displayName = preferredFirstName;
                } else if (preferredLastName) {
                    displayName = preferredLastName;
                } else if (altName) {
                    displayName = altName;
                } else {
                    displayName = entityId;
                }

                employees.push({
                    id: employeeId,
                    entityId: entityId,
                    name: displayName,
                    preferredName: preferredName,
                    preferredFirstName: preferredFirstName,
                    preferredLastName: preferredLastName,
                    altName: altName,
                    title: result.getText('title') || '',
                    location: result.getText('location') || '',
                    locationId: result.getValue('locationnohierarchy') || '',
                    roleName: roleName,
                    roleId: roleId
                });

                // Add employee ID to the set to prevent future duplicates
                employeeIds.add(employeeId);

                return true;
            });

            // Debug: Log the final count of employees after role filtering and deduplication
            /*             log.debug('getActiveEmployees Result', {
                message: 'Employees loaded after role filtering and deduplication',
                totalEmployees: employees.length,
                uniqueEmployeeIds: employeeIds.size,
                employeeNames: employees.map((emp) => emp.name + ' (' + emp.roleName + ')').join(', ')
            }); */

            return employees;
        } catch (error) {
            log.error('Error in getActiveEmployees', {
                error: error.message,
                stack: error.stack
            });
            return [];
        }
    }

    /**
     * Search customers by name and additional filters
     */
    function searchCustomers(searchTerm, additionalFilters) {
        try {
            // Build filter array starting with base filters
            let filters = [['isinactive', 'is', 'F']];

            // Add name search filter if provided (flexible partial matching)
            if (searchTerm && searchTerm.trim()) {
                const term = searchTerm.trim();
                filters.push('AND');
                // Use OR logic to search for different case variations
                filters.push([['altname', 'startswith', term], 'OR', ['altname', 'startswith', term.toLowerCase()], 'OR', ['altname', 'startswith', term.toUpperCase()], 'OR', ['altname', 'startswith', term.charAt(0).toUpperCase() + term.slice(1).toLowerCase()]]);
            }

            // Add additional filters if provided
            if (additionalFilters) {
                // Zipcode search enabled using verified field name
                if (additionalFilters.zipcode && additionalFilters.zipcode.trim()) {
                    filters.push('AND');
                    filters.push(['zipcode', 'startswith', additionalFilters.zipcode.trim()]);
                }

                // Address search enabled - uses 'contains' to match street address without requiring addressee
                if (additionalFilters.address && additionalFilters.address.trim()) {
                    filters.push('AND');
                    filters.push(['billaddress', 'contains', additionalFilters.address.trim()]);
                }

                if (additionalFilters.phone && additionalFilters.phone.trim()) {
                    // Remove non-numeric characters for phone search
                    const cleanPhone = additionalFilters.phone.replace(/\D/g, '');
                    if (cleanPhone) {
                        filters.push('AND');
                        filters.push(['phone', 'startswith', cleanPhone]);
                    }
                }

                if (additionalFilters.email && additionalFilters.email.trim()) {
                    const emailTerm = additionalFilters.email.trim();
                    filters.push('AND');
                    // Use OR logic for flexible email matching
                    filters.push([['email', 'startswith', emailTerm], 'OR', ['email', 'startswith', emailTerm.toLowerCase()], 'OR', ['email', 'startswith', emailTerm.toUpperCase()]]);
                }

                if (additionalFilters.entityid && additionalFilters.entityid.trim()) {
                    const entityTerm = additionalFilters.entityid.trim();
                    filters.push('AND');
                    // Use OR logic for flexible entity ID matching
                    filters.push([['entityid', 'startswith', entityTerm], 'OR', ['entityid', 'startswith', entityTerm.toLowerCase()], 'OR', ['entityid', 'startswith', entityTerm.toUpperCase()]]);
                }
            }

            // Debug logging for search parameters
            /*             log.debug('Customer search parameters', {
                searchTerm: searchTerm,
                additionalFilters: additionalFilters,
                filters: filters,
                searchType: 'customer'
            }); */

            const customerSearchObj = search.create({
                type: 'customer',
                filters: filters,
                columns: [search.createColumn({ name: 'internalid', label: 'Internal ID' }), search.createColumn({ name: 'entityid', label: 'ID' }), search.createColumn({ name: 'altname', label: 'Name' }), search.createColumn({ name: 'companyname', label: 'Company Name' }), search.createColumn({ name: 'email', label: 'Email' }), search.createColumn({ name: 'phone', label: 'Phone' }), search.createColumn({ name: 'billaddress', label: 'Address' }), search.createColumn({ name: 'zipcode', label: 'Zip Code' }), search.createColumn({ name: 'custentity_customerstatus', label: 'Customer Status' })]
            });

            const customers = [];
            let resultCount = 0;
            const maxResults = 20; // Limit results for performance
            const seenEntityIds = new Set(); // Track seen entityIds to prevent duplicates

            customerSearchObj.run().each(function (result) {
                if (resultCount >= maxResults) {
                    return false; // Stop after max results
                }

                const customerId = result.getValue('internalid');
                const entityId = result.getValue('entityid') || '';
                const altName = result.getValue('altname') || '';
                const companyName = result.getValue('companyname') || '';
                const email = result.getValue('email') || '';
                const phone = result.getValue('phone') || '';
                const address = result.getValue('billaddress') || '';
                const zipcode = result.getValue('zipcode') || '';
                const customerStatus = result.getValue('custentity_customerstatus') || '';

                // Skip if we've already seen this entityId (deduplication)
                if (entityId && seenEntityIds.has(entityId)) {
                    /*                     log.debug('Skipping duplicate customer', {
                        entityId: entityId,
                        customerId: customerId,
                        displayName: altName || companyName
                    }); */
                    return true; // Continue to next result
                }

                // Debug logging to see what we're getting
                /*                 log.debug('Customer search result', {
                    customerId: customerId,
                    entityId: entityId,
                    altName: altName,
                    companyName: companyName,
                    email: email,
                    phone: phone
                }); */

                // Create display name - use altname first, then companyname, then entityid as fallback
                let displayName = altName || companyName || entityId || 'Customer ' + customerId;

                // Clean address field to remove addressee (customer name) from first line
                let cleanedAddress = address;
                if (address) {
                    // Split address into lines
                    const addressLines = address
                        .split('\n')
                        .map((line) => line.trim())
                        .filter((line) => line);

                    // Remove the first line if it matches the customer name (case insensitive)
                    if (addressLines.length > 1) {
                        const firstLine = addressLines[0].toUpperCase();
                        const customerNameUpper = displayName.toUpperCase();
                        const altNameUpper = (altName || '').toUpperCase();
                        const companyNameUpper = (companyName || '').toUpperCase();

                        // If first line matches any variation of the customer name, remove it
                        if (firstLine === customerNameUpper || firstLine === altNameUpper || firstLine === companyNameUpper || (firstLine.includes(customerNameUpper) && customerNameUpper.length > 3) || (altNameUpper && firstLine.includes(altNameUpper) && altNameUpper.length > 3) || (companyNameUpper && firstLine.includes(companyNameUpper) && companyNameUpper.length > 3)) {
                            // Remove the first line (addressee) and join the rest
                            cleanedAddress = addressLines.slice(1).join('\n');
                        }
                    }
                }

                // Add entityId to seen set before adding customer
                if (entityId) {
                    seenEntityIds.add(entityId);
                }

                customers.push({
                    id: customerId,
                    entityId: entityId,
                    displayName: displayName,
                    altName: altName,
                    companyName: companyName,
                    phone: phone,
                    email: email,
                    address: cleanedAddress,
                    zipcode: zipcode,
                    customerStatus: customerStatus
                });

                resultCount++;
                return true;
            });

            // Debug logging for final results
            /*             log.debug('Customer search final results', {
                searchTerm: searchTerm,
                resultCount: customers.length,
                customers: customers.map((c) => ({ id: c.id, displayName: c.displayName, altName: c.altName }))
            }); */

            return customers;
        } catch (error) {
            log.error('Error in searchCustomers', {
                error: error.message,
                stack: error.stack,
                searchTerm: searchTerm
            });
            return [];
        }
    }

    /**
     * Search for customers by phone number only
     */
    function searchCustomersByPhone(phoneNumber) {
        try {
            // Clean the phone number - remove all non-numeric characters
            const cleanPhone = phoneNumber.replace(/\D/g, '');

            if (!cleanPhone || cleanPhone.length < 10) {
                return [];
            }

            // Build filter for phone search - search across phone and mobile phone fields (note: 'altphone' is not searchable in NetSuite)
            const filters = [['isinactive', 'is', 'F'], 'AND', [['phone', 'startswith', cleanPhone], 'OR', ['custentity_mobile_phone', 'startswith', cleanPhone]]];

            // Search for customers
            const customerSearch = search.create({
                type: search.Type.CUSTOMER,
                filters: filters,
                columns: ['internalid', 'entityid', 'altname', 'phone', 'altphone', 'custentity_mobile_phone', 'email', 'billaddress', 'city', 'state', 'zipcode']
            });

            const results = [];
            customerSearch.run().each(function (result) {
                results.push({
                    id: result.getValue('internalid'),
                    entityId: result.getValue('entityid'),
                    name: result.getValue('altname'),
                    phone: result.getValue('phone'),
                    altphone: result.getValue('altphone'),
                    mobilephone: result.getValue('custentity_mobile_phone'),
                    email: result.getValue('email'),
                    address: result.getValue('billaddress'),
                    city: result.getValue('city'),
                    state: result.getValue('state'),
                    zipcode: result.getValue('zipcode')
                });
                return true;
            });

            return results;
        } catch (error) {
            log.error('Error searching customers by phone', {
                phoneNumber: phoneNumber,
                error: error.message,
                stack: error.stack
            });
            return [];
        }
    }

    /**
     * Call Google Address Validation API
     */
    function callGoogleAddressValidation(addressString) {
        try {
            // Use the same API key that works for Google Places
            // First try to get it from the secret, fallback to hardcoded key
            let apiKey = null;

            try {
                const secureApiKey = https.createSecureString({
                    input: 'custsecret_googlemapsapi'
                });
                // Try to extract the key value
                apiKey = secureApiKey.toString().replace('https.SecureString', '').trim();
            } catch (secretError) {
                /*                 log.debug('Could not get API key from secret, using fallback'); */
            }

            // Fallback to the working API key if secret fails
            if (!apiKey || apiKey.length < 10) {
                apiKey = 'AIzaSyCqvB1BQkckNIQhuUgEHRZu1QFrcZENxDw';
            }

            // Google Address Validation API endpoint
            const url = 'https://addressvalidation.googleapis.com/v1:validateAddress';

            // Prepare the request body
            const requestBody = {
                address: {
                    addressLines: [addressString],
                    regionCode: 'US'
                }
            };

            /* 
            log.debug('Google Address Validation Request', {
                url: url,
                body: requestBody
            }); */

            // Make the API call with the API key
            const response = https.post({
                url: url + '?key=' + apiKey,
                body: JSON.stringify(requestBody),
                headers: {
                    'Content-Type': 'application/json'
                }
            });

            /* 
            log.debug('Google Address Validation Response', {
                code: response.code,
                body: response.body
            }); */

            if (response.code === 200) {
                const result = JSON.parse(response.body);
                return {
                    success: true,
                    result: result.result
                };
            } else {
                log.error('Google Address Validation API Error', {
                    code: response.code,
                    body: response.body
                });

                // Parse error response to provide more specific error information
                let errorMessage = 'API returned status code: ' + response.code;
                try {
                    const errorBody = JSON.parse(response.body);
                    if (errorBody.error && errorBody.error.message) {
                        errorMessage = errorBody.error.message;
                    }
                } catch (parseError) {
                    // Use default error message if parsing fails
                }

                return {
                    success: false,
                    error: errorMessage
                };
            }
        } catch (error) {
            log.error('Google Address Validation Error', error);
            return {
                success: false,
                error: error.message || 'Unknown error occurred'
            };
        }
    }

    /**
     * Extract street address from Google's full address format
     * Google format: "95 Horseblock Road, Yaphank, NY, USA"
     * NetSuite format: "95 Horseblock Rd"
     */
    function extractStreetAddress(fullAddress) {
        if (!fullAddress || typeof fullAddress !== 'string') {
            return '';
        }

        // Split by comma to separate street address from city/state/country
        const parts = fullAddress.split(',');

        // Return the first part (street address) trimmed
        return parts[0] ? parts[0].trim() : '';
    }

    /**
     * Normalize address for comparison by handling common street suffix variations
     */
    function normalizeAddressForComparison(address) {
        if (!address || typeof address !== 'string') {
            return '';
        }

        // First extract just the street address portion if it's a full Google format
        const streetAddress = extractStreetAddress(address);

        // Create a mapping of common street suffixes to their abbreviated forms
        const streetSuffixMap = {
            road: 'rd',
            street: 'st',
            avenue: 'ave',
            boulevard: 'blvd',
            drive: 'dr',
            lane: 'ln',
            court: 'ct',
            place: 'pl',
            circle: 'cir',
            way: 'way',
            parkway: 'pkwy',
            highway: 'hwy',
            trail: 'trl'
        };

        // Clean and normalize the street address
        let normalized = streetAddress.trim().toLowerCase();

        // Split into words
        const words = normalized.split(/\s+/);

        if (words.length > 1) {
            const lastWord = words[words.length - 1];

            // Check if the last word is a street suffix that needs normalization
            for (const [fullForm, abbrev] of Object.entries(streetSuffixMap)) {
                if (lastWord === fullForm || lastWord === abbrev) {
                    // Replace with abbreviated form for consistent comparison
                    words[words.length - 1] = abbrev;
                    break;
                }
            }
        }

        return words.join(' ');
    }

    /**
     * Check for duplicate customers based on phone, email, or address
     */
    function checkForDuplicateCustomers(phone, email, address, customerName) {
        try {
            /*             log.debug('Checking for duplicate customers', { phone, email, address }); */

            const duplicates = {
                phone: [],
                email: [],
                address: []
            };

            // Check for phone duplicates
            if (phone && phone.trim().length >= 10) {
                const cleanPhone = phone.replace(/\D/g, ''); // Remove non-digits
                const phoneSearchObj = search.create({
                    type: search.Type.CUSTOMER,
                    filters: [
                        ['phone', 'contains', cleanPhone.slice(-10)] // Last 10 digits
                    ],
                    columns: ['internalid', 'entityid', 'altname', 'companyname', 'phone', 'email']
                });

                phoneSearchObj.run().each(function (result) {
                    const customerPhone = result.getValue('phone') || '';
                    const customerCleanPhone = customerPhone.replace(/\D/g, '');

                    // Match last 10 digits
                    if (customerCleanPhone.slice(-10) === cleanPhone.slice(-10)) {
                        duplicates.phone.push({
                            id: result.getValue('internalid'),
                            entityId: result.getValue('entityid'),
                            name: result.getValue('altname') || result.getValue('companyname') || result.getValue('entityid'),
                            phone: customerPhone,
                            email: result.getValue('email') || ''
                        });
                    }
                    return true;
                });
            }

            // Check for email duplicates
            if (email && email.trim().length > 0) {
                const emailSearchObj = search.create({
                    type: search.Type.CUSTOMER,
                    filters: [['email', 'is', email.trim().toLowerCase()]],
                    columns: ['internalid', 'entityid', 'altname', 'companyname', 'phone', 'email']
                });

                emailSearchObj.run().each(function (result) {
                    duplicates.email.push({
                        id: result.getValue('internalid'),
                        entityId: result.getValue('entityid'),
                        name: result.getValue('altname') || result.getValue('companyname') || result.getValue('entityid'),
                        phone: result.getValue('phone') || '',
                        email: result.getValue('email') || ''
                    });
                    return true;
                });
            }

            // Check for address duplicates with customer name consideration
            if (address && address.trim().length > 0 && customerName && customerName.trim().length > 0) {
                // Extract just the street address portion for searching (removes city, state, country)
                const streetAddress = extractStreetAddress(address);

                /* 
                log.debug('Searching for address duplicates', {
                    customerName: customerName,
                    fullAddress: address,
                    streetAddress: streetAddress,
                    customerName: customerName,
                    shortenedAddress: streetAddress.trim().substring(0, streetAddress.trim().lastIndexOf(' ') + 2)
                }); */

                const addressSearchObj = search.create({
                    type: search.Type.CUSTOMER,
                    filters: [['address', 'contains', streetAddress.trim().substring(0, streetAddress.trim().lastIndexOf(' ') + 2)], 'AND', ['isinactive', 'is', 'F']],
                    columns: ['internalid', 'entityid', 'altname', 'companyname', 'phone', 'email', 'address', 'zipcode']
                });

                addressSearchObj.run().each(function (result) {
                    const customerAddress = result.getValue('address') || '';
                    const customerZip = result.getValue('zipcode') || '';
                    const fullAddress = customerAddress + (customerZip ? ' ' + customerZip : '');

                    const existingCustomerName = result.getValue('altname') || result.getValue('companyname') || result.getValue('entityid') || '';

                    /* 
                    log.debug('Found potential address match', {
                        existingCustomer: existingCustomerName,
                        existingAddress: customerAddress,
                        fullSearchAddress: address,
                        streetSearchAddress: streetAddress,
                        searchCustomer: customerName
                    }); */

                    // Check if both address and customer name match
                    // Normalize addresses for better comparison (handles Road vs Rd, Street vs St, etc.)
                    const normalizedExistingAddress = normalizeAddressForComparison(customerAddress);
                    const normalizedSearchAddress = normalizeAddressForComparison(streetAddress);

                    const addressMatches = normalizedExistingAddress.includes(normalizedSearchAddress) || normalizedSearchAddress.includes(normalizedExistingAddress);
                    const nameMatches = existingCustomerName.toLowerCase().includes(customerName.trim().toLowerCase()) || customerName.trim().toLowerCase().includes(existingCustomerName.toLowerCase());

                    /* 
                    log.debug('Address match check', {
                        originalExistingAddress: customerAddress,
                        originalFullSearchAddress: address,
                        originalStreetSearchAddress: streetAddress,
                        normalizedExistingAddress: normalizedExistingAddress,
                        normalizedSearchAddress: normalizedSearchAddress,
                        addressMatches: addressMatches,
                        nameMatches: nameMatches,
                        willAdd: addressMatches && nameMatches
                    }); */

                    if (addressMatches && nameMatches) {
                        duplicates.address.push({
                            id: result.getValue('internalid'),
                            entityId: result.getValue('entityid'),
                            name: existingCustomerName,
                            phone: result.getValue('phone') || '',
                            email: result.getValue('email') || '',
                            address: fullAddress.trim()
                        });
                    }
                    return true;
                });
            }

            /* 
            log.debug('Duplicate check results', duplicates); */
            return duplicates;
        } catch (error) {
            log.error('Error in checkForDuplicateCustomers', error);
            throw error;
        }
    }

    /**
     * Convert a string to proper case (capitalize first letter of each word)
     */
    function toProperCase(str) {
        if (!str) return str;
        return str
            .trim()
            .split(' ')
            .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
            .join(' ');
    }

    /**
     * Create a new lead record in NetSuite
     */
    function createLeadRecord(customerData) {
        try {
            /*             log.debug('Creating new lead record', customerData); */

            // Create a new lead record
            const leadRecord = record.create({
                type: 'lead'
            });

            // Set required Customer Name field - NetSuite's "Customer Name" is often the companyname field
            if (customerData.name) {
                const customerName = customerData.name.trim();
                const nameParts = customerName.split(' ');

                // Set individual name fields for person details (with proper case)
                if (nameParts.length > 1) {
                    leadRecord.setValue('firstname', toProperCase(nameParts[0]));
                    leadRecord.setValue('lastname', toProperCase(nameParts.slice(1).join(' ')));
                } else {
                    leadRecord.setValue('firstname', toProperCase(customerName));
                }

                // Set companyname field - this is likely what NetSuite calls "Customer Name"
                if (customerData.company && customerData.company.trim()) {
                    // If company is provided, use company as the "Customer Name"
                    leadRecord.setValue('companyname', customerData.company.trim());
                } else {
                    // If no company, use the customer name as the "Customer Name" (B2C scenario)
                    leadRecord.setValue('companyname', customerName);
                }

                // Also try setting other name fields as backup
                try {
                    leadRecord.setValue('entityname', customerName);
                } catch (entityNameError) {
                    try {
                        leadRecord.setValue('altname', customerName);
                    } catch (altNameError) {
                        /*                         log.debug('Could not set entityname or altname', {
                            entityNameError: entityNameError.message,
                            altNameError: altNameError.message
                        }); */
                    }
                }

                /* 
                log.debug('Lead name fields set', {
                    firstname: nameParts[0] || customerName,
                    lastname: nameParts.slice(1).join(' ') || '',
                    companyname: customerData.company || customerName,
                    customerName: customerName
                }); */
            }

            // Set phone number fields based on verification results
            if (customerData.phone) {
                const phoneNumber = customerData.phone.trim();
                const phoneVerification = customerData.phoneVerification;

                /* 
                log.debug('Phone verification data', phoneVerification); */

                // Always set the main phone field
                leadRecord.setValue('phone', phoneNumber);

                // Set additional phone fields based on verification type
                if (phoneVerification && phoneVerification.verified && phoneVerification.type) {
                    const phoneType = phoneVerification.type.toLowerCase();

                    if (phoneType === 'mobile') {
                        // For mobile phones, set the mobile phone field
                        try {
                            leadRecord.setValue('custentity_mobile_phone', phoneNumber);
                            /*                             log.debug('Set mobile phone field', phoneNumber); */
                        } catch (mobilePhoneError) {
                            /*                             log.debug('Could not set mobile phone field', mobilePhoneError.message); */
                        }
                    } else {
                        // For landline/other phones, set the alternate phone field
                        try {
                            leadRecord.setValue('altphone', phoneNumber);
                            /*                             log.debug('Set alternate phone field for ' + phoneType, phoneNumber); */
                        } catch (altPhoneError) {
                            /*                             log.debug('Could not set alternate phone field', altPhoneError.message); */
                        }
                    }
                } else {
                    // No verification data or unverified phone - default to alternate phone
                    try {
                        leadRecord.setValue('altphone', phoneNumber);
                        /*                         log.debug('Set alternate phone field (no verification)', phoneNumber); */
                    } catch (altPhoneError) {
                        /*                         log.debug('Could not set alternate phone field (fallback)', altPhoneError.message); */
                    }
                }
            }

            // Set email if provided
            if (customerData.email && customerData.email.trim()) {
                leadRecord.setValue('email', customerData.email.trim());
            }

            // Set address fields if provided - create address subrecord
            if (customerData.address1 && customerData.address1.trim()) {
                try {
                    /*                     log.debug('Creating address subrecord', {
                        address1: customerData.address1,
                        address2: customerData.address2,
                        city: customerData.city,
                        state: customerData.state,
                        zip: customerData.zip
                    }); */

                    // Insert new line in addressbook sublist (SuiteScript 2.0 method)
                    leadRecord.insertLine({
                        sublistId: 'addressbook',
                        line: 0
                    });

                    // Set sublist fields
                    leadRecord.setSublistValue({
                        sublistId: 'addressbook',
                        fieldId: 'label',
                        line: 0,
                        value: 'Primary Address'
                    });

                    leadRecord.setSublistValue({
                        sublistId: 'addressbook',
                        fieldId: 'defaultbilling',
                        line: 0,
                        value: true
                    });

                    leadRecord.setSublistValue({
                        sublistId: 'addressbook',
                        fieldId: 'defaultshipping',
                        line: 0,
                        value: true
                    });

                    // Create the address subrecord
                    const addressSubrecord = leadRecord.getSublistSubrecord({
                        sublistId: 'addressbook',
                        fieldId: 'addressbookaddress',
                        line: 0
                    });

                    // Set country first (required for address format)
                    addressSubrecord.setValue({
                        fieldId: 'country',
                        value: 'US'
                    });

                    // Set address fields
                    addressSubrecord.setValue({
                        fieldId: 'addr1',
                        value: customerData.address1.trim()
                    });

                    if (customerData.address2 && customerData.address2.trim()) {
                        addressSubrecord.setValue({
                            fieldId: 'addr2',
                            value: customerData.address2.trim()
                        });
                    }

                    if (customerData.city && customerData.city.trim()) {
                        addressSubrecord.setValue({
                            fieldId: 'city',
                            value: customerData.city.trim()
                        });
                    }

                    if (customerData.state && customerData.state.trim()) {
                        addressSubrecord.setValue({
                            fieldId: 'state',
                            value: customerData.state.trim()
                        });
                    }

                    if (customerData.zip && customerData.zip.trim()) {
                        addressSubrecord.setValue({
                            fieldId: 'zip',
                            value: customerData.zip.trim()
                        });
                    }
                    //Zip4 lookup can be added here if needed
                    // Set addressee field with proper case
                    log.audit('Calculating Zip4 for address', {
                        address1: customerData.address1,
                        address2: customerData.address2,
                        city: customerData.city,
                        state: customerData.state,
                        zip: customerData.zip
                    });

                    let custZip4 = '0000';
                    const custAddressLine1 = customerData.address1.trim();
                    const custAddressLine2 = customerData.address2 && customerData.address2.trim() ? customerData.address2.trim() : '';
                    const custCity = customerData.city && customerData.city.trim() ? customerData.city.trim() : '';
                    const custState = customerData.state && customerData.state.trim() ? customerData.state.trim() : '';
                    const custZip = customerData.zip && customerData.zip.trim() ? customerData.zip.trim() : '';
                    custZip4 = getZip4(custAddressLine1, custAddressLine2, custCity, custState, custZip);
                    if (custZip4) {
                        addressSubrecord.setValue({
                            fieldId: 'custrecordzip4',
                            value: toProperCase(custZip4)
                        });
                    }

                    if (customerData.name) {
                        addressSubrecord.setValue({
                            fieldId: 'addressee',
                            value: toProperCase(customerData.name.trim())
                        });
                    }

                    /*
                    log.debug('Address subrecord created successfully'); */
                } catch (addressError) {
                    log.error('Failed to create address subrecord', {
                        error: addressError.message,
                        stack: addressError.stack,
                        customerData: customerData
                    });
                    // Continue with record creation even if address fails
                }
            }

            // Handle separate billing address (if checkbox was unchecked)
            // When billing checkbox is unchecked: Primary address (line 0) becomes Shipping Address, Billing goes to line 1
            if (customerData.sameAsBilling === false && customerData.billingAddress1 && customerData.billingAddress1.trim()) {
                try {
                    // Update primary address (line 0) to be shipping-only
                    leadRecord.setSublistValue({
                        sublistId: 'addressbook',
                        fieldId: 'defaultbilling',
                        line: 0,
                        value: false
                    });

                    leadRecord.setSublistValue({
                        sublistId: 'addressbook',
                        fieldId: 'defaultshipping',
                        line: 0,
                        value: true
                    });

                    // Insert billing address line
                    leadRecord.insertLine({
                        sublistId: 'addressbook',
                        line: 1
                    });

                    // Set billing address sublist fields
                    leadRecord.setSublistValue({
                        sublistId: 'addressbook',
                        fieldId: 'label',
                        line: 1,
                        value: 'Billing Address'
                    });

                    leadRecord.setSublistValue({
                        sublistId: 'addressbook',
                        fieldId: 'defaultbilling',
                        line: 1,
                        value: true
                    });

                    leadRecord.setSublistValue({
                        sublistId: 'addressbook',
                        fieldId: 'defaultshipping',
                        line: 1,
                        value: false
                    });

                    // Create the billing address subrecord
                    const billingAddressSubrecord = leadRecord.getSublistSubrecord({
                        sublistId: 'addressbook',
                        fieldId: 'addressbookaddress',
                        line: 1
                    });

                    // Set billing address fields
                    billingAddressSubrecord.setValue({
                        fieldId: 'country',
                        value: 'US'
                    });

                    billingAddressSubrecord.setValue({
                        fieldId: 'addr1',
                        value: customerData.billingAddress1.trim()
                    });

                    if (customerData.billingAddress2 && customerData.billingAddress2.trim()) {
                        billingAddressSubrecord.setValue({
                            fieldId: 'addr2',
                            value: customerData.billingAddress2.trim()
                        });
                    }

                    if (customerData.billingCity && customerData.billingCity.trim()) {
                        billingAddressSubrecord.setValue({
                            fieldId: 'city',
                            value: customerData.billingCity.trim()
                        });
                    }

                    if (customerData.billingState && customerData.billingState.trim()) {
                        billingAddressSubrecord.setValue({
                            fieldId: 'state',
                            value: customerData.billingState.trim()
                        });
                    }

                    if (customerData.billingZip && customerData.billingZip.trim()) {
                        billingAddressSubrecord.setValue({
                            fieldId: 'zip',
                            value: customerData.billingZip.trim()
                        });
                    }

                    // Set addressee field with proper case
                    if (customerData.name) {
                        billingAddressSubrecord.setValue({
                            fieldId: 'addressee',
                            value: toProperCase(customerData.name.trim())
                        });
                    }
                } catch (billingAddressError) {
                    log.error('Failed to create billing address subrecord', {
                        error: billingAddressError.message,
                        customerData: customerData
                    });
                }
            }

            // Handle CRD vs Retail customer creation
            if (customerData.isCRD) {
                // CRD Customer Mode
                try {
                    // Set required Customer Type to Company (ID: 2) for CRD customers
                    leadRecord.setValue('category', 2);
                    log.debug('Set Customer Type to Company for CRD', { category: 2 });

                    // Set customer category to CRD (ID: 2)
                    leadRecord.setValue('custentity_customer_category', '2');
                    log.debug('Set CRD customer category', { category: '2' });

                    // Set customer status for CRD (ID: 5)
                    leadRecord.setValue('custentity_customerstatus', '5');
                    log.debug('Set CRD customer status', { status: '5' });

                    // Set business type if provided
                    if (customerData.businessType && customerData.businessType.trim()) {
                        leadRecord.setValue('custentity_custbustype', customerData.businessType.trim());
                        log.debug('Set business type', { businessType: customerData.businessType });
                    }

                    // Note: Contacts will be created separately after customer record is saved
                    // Cannot add contacts to contactroles sublist during customer creation
                    log.debug('CRD customer - contacts will be created separately', {
                        contactCount: customerData.contacts ? customerData.contacts.length : 0
                    });
                } catch (crdError) {
                    log.error('Failed to set CRD-specific fields', {
                        error: crdError.message,
                        customerData: customerData
                    });
                    // Continue with record creation
                }
            } else {
                // Retail Customer Mode - Set relationship fields
                try {
                    if (customerData.firstName1 && customerData.firstName1.trim()) {
                        leadRecord.setValue('custentity_first_name_1', customerData.firstName1.trim());
                    }

                    if (customerData.firstName2 && customerData.firstName2.trim()) {
                        leadRecord.setValue('custentity_first_name_2', customerData.firstName2.trim());
                    }

                    if (customerData.phone1 && customerData.phone1.trim()) {
                        leadRecord.setValue('custentity_phone_one', customerData.phone1.trim());
                    }

                    if (customerData.phone2 && customerData.phone2.trim()) {
                        leadRecord.setValue('custentity_phone_two', customerData.phone2.trim());
                    }

                    if (customerData.email1 && customerData.email1.trim()) {
                        leadRecord.setValue('custentity_email_one', customerData.email1.trim());
                    }

                    if (customerData.email2 && customerData.email2.trim()) {
                        leadRecord.setValue('custentity_email_two', customerData.email2.trim());
                    }

                    if (customerData.children && customerData.children.trim()) {
                        leadRecord.setValue('custentity_children', customerData.children.trim());
                    }
                } catch (relationshipError) {
                    log.error('Failed to set relationship fields', {
                        error: relationshipError.message,
                        customerData: customerData
                    });
                    // Continue with record creation even if relationship fields fail
                }

                // Set required Customer Type - typically for leads this would be individual
                // Common values might be: 1 = Individual, 2 = Company, etc.
                try {
                    leadRecord.setValue('category', 1); // Try ID 1 (Individual)
                } catch (categoryError) {
                    /*                 log.debug('Category field error, trying alternative', categoryError.message); */
                    try {
                        leadRecord.setValue('custentity_customer_type', 'Individual');
                    } catch (custTypeError) {
                        /*                     log.debug('Could not set customer type', custTypeError.message); */
                    }
                }
            }

            // Set required Lead Source using the selected value
            if (customerData.leadSource) {
                try {
                    // Use the selected lead source ID
                    leadRecord.setValue('leadsource', customerData.leadSource);
                    /*                     log.debug('Lead source set successfully', {
                        leadSourceId: customerData.leadSource
                    }); */
                } catch (leadSourceError) {
                    log.error('Failed to set selected lead source', {
                        leadSourceId: customerData.leadSource,
                        error: leadSourceError.message
                    });
                    // Don't proceed if we can't set the lead source, as it's required
                    throw new Error('Invalid lead source selected: ' + customerData.leadSource);
                }
            } else {
                throw new Error('Lead source is required but not provided');
            }

            // Set stage to "LEAD"
            leadRecord.setValue('stage', 'LEAD');

            // Save the record
            const leadId = leadRecord.save();

            /* 
            log.audit('Lead created successfully', {
                leadId: leadId,
                customerName: customerData.name,
                phone: customerData.phone,
                email: customerData.email
            }); */

            return {
                success: true,
                customerId: leadId
            };
        } catch (error) {
            log.error('Error creating lead record', {
                error: error.message,
                stack: error.stack,
                customerData: customerData
            });

            // Return specific error messages for common issues
            let errorMessage = 'Failed to create customer record';
            if (error.message.includes('Customer Name')) {
                errorMessage = 'Customer name field configuration issue - please check NetSuite setup';
            } else if (error.message.includes('Customer Type')) {
                errorMessage = 'Customer type field configuration issue - please check NetSuite setup';
            } else if (error.message.includes('Lead Source')) {
                errorMessage = 'Lead source field configuration issue - please check NetSuite setup';
            } else if (error.message.includes('REQUIRED')) {
                errorMessage = 'Missing required fields';
            } else if (error.message.includes('UNIQUE')) {
                errorMessage = 'A customer with this information already exists';
            } else if (error.message.includes('INVALID')) {
                errorMessage = 'Invalid data provided';
            }

            return {
                success: false,
                error: errorMessage + ': ' + error.message
            };
        }
    }

    /**
     * Perform Twilio phone lookup to determine phone type (mobile vs landline)
     * @param {string} phoneNumber - The phone number to lookup
     * @returns {Object} Object with type, formatted, and carrier properties
     */
    function twilioPhoneLookupServer(phoneNumber) {
        try {
            // Strip non-numeric characters
            const cleanPhone = phoneNumber.replace(/[^0-9]/g, '');

            if (!cleanPhone || cleanPhone.length < 10) {
                return { type: 'unknown', formatted: phoneNumber, carrier: '' };
            }

            // Twilio API credentials (base64 encoded)
            const twilioAuth = 'QUNkMGU1ZGJjZGYxMjhjOTdmMmQ2OGMzMDMwNWIwMzMxZDpkMzhiNTE3ZWU2ZWY0YTQ1MGVlNDU3MDBkZWFjOWRmZg==';
            const url = 'https://lookups.twilio.com/v2/PhoneNumbers/' + cleanPhone + '?Fields=line_type_intelligence';

            const response = https.get({
                url: url,
                headers: {
                    Authorization: 'Basic ' + twilioAuth,
                    Accept: 'application/json'
                }
            });

            if (response.code !== 200 && response.code !== 201) {
                log.debug('Twilio lookup failed', {
                    phone: cleanPhone,
                    code: response.code,
                    body: response.body
                });
                return { type: 'unknown', formatted: phoneNumber, carrier: '' };
            }

            const result = JSON.parse(response.body);

            if (result.valid === false) {
                log.debug('Invalid phone number from Twilio', { phone: cleanPhone });
                return { type: 'unknown', formatted: phoneNumber, carrier: '' };
            }

            const phoneType = result.line_type_intelligence && result.line_type_intelligence.type ? result.line_type_intelligence.type : 'unknown';
            const formatted = result.national_format || phoneNumber;
            const carrier = result.line_type_intelligence && result.line_type_intelligence.carrier_name ? result.line_type_intelligence.carrier_name : '';

            log.debug('Twilio phone lookup result', {
                phone: cleanPhone,
                type: phoneType,
                formatted: formatted,
                carrier: carrier
            });

            return {
                type: phoneType,
                formatted: formatted,
                carrier: carrier
            };
        } catch (error) {
            log.error('Error in Twilio phone lookup', {
                error: error.message,
                phone: phoneNumber
            });
            return { type: 'unknown', formatted: phoneNumber, carrier: '' };
        }
    }

    /**
     * Create Contact records for CRD customers and link them to the customer
     * @param {string} customerId - The NetSuite internal ID of the customer
     * @param {Array} contacts - Array of contact objects with name, phone, fax, role, crdPin fields
     * @returns {Object} Result object with success status and created contact IDs or errors
     */
    function createCRDContacts(customerId, contacts) {
        const results = {
            success: true,
            contactIds: [],
            errors: []
        };

        if (!contacts || !Array.isArray(contacts) || contacts.length === 0) {
            return {
                success: true,
                message: 'No contacts to create'
            };
        }

        contacts.forEach(function (contactData, index) {
            try {
                if (!contactData.name || !contactData.name.trim()) {
                    log.debug('Skipping contact without name', { index: index });
                    return; // Skip contacts without names
                }

                // Create a new Contact record
                const contactRecord = record.create({
                    type: record.Type.CONTACT
                });

                // Parse contact name into first/last name
                const nameParts = contactData.name.trim().split(' ');
                const firstName = nameParts[0] || '';
                const lastName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : '';

                // Set name fields with proper case
                if (firstName) {
                    contactRecord.setValue({
                        fieldId: 'firstname',
                        value: toProperCase(firstName)
                    });
                }
                if (lastName) {
                    contactRecord.setValue({
                        fieldId: 'lastname',
                        value: toProperCase(lastName)
                    });
                }

                // Link to customer (company field)
                contactRecord.setValue({
                    fieldId: 'company',
                    value: customerId
                });

                // Set contact email
                if (contactData.email && contactData.email.trim()) {
                    try {
                        contactRecord.setValue({
                            fieldId: 'email',
                            value: contactData.email.trim()
                        });
                    } catch (emailError) {
                        log.debug('Email field error', emailError.message);
                    }
                }

                // Set contact phone using Twilio lookup to determine mobile vs home phone
                if (contactData.phone && contactData.phone.trim()) {
                    // Perform Twilio lookup to determine phone type
                    const phoneInfo = twilioPhoneLookupServer(contactData.phone.trim());

                    // Always set custentity_best_phone
                    try {
                        contactRecord.setValue({
                            fieldId: 'custentity_best_phone',
                            value: phoneInfo.formatted || contactData.phone.trim()
                        });
                    } catch (bestPhoneError) {
                        log.debug('Best phone field error', bestPhoneError.message);
                    }

                    // Set mobilephone or homephone based on phone type
                    if (phoneInfo.type === 'mobile') {
                        try {
                            contactRecord.setValue({
                                fieldId: 'mobilephone',
                                value: phoneInfo.formatted || contactData.phone.trim()
                            });
                            log.debug('Set mobile phone', { phone: phoneInfo.formatted, carrier: phoneInfo.carrier });
                        } catch (mobileError) {
                            log.debug('Mobile phone field error', mobileError.message);
                        }
                    } else {
                        // If not mobile (landline, voip, unknown, etc.), set as home phone
                        try {
                            contactRecord.setValue({
                                fieldId: 'homephone',
                                value: phoneInfo.formatted || contactData.phone.trim()
                            });
                            log.debug('Set home phone', { phone: phoneInfo.formatted, type: phoneInfo.type });
                        } catch (homeError) {
                            log.debug('Home phone field error', homeError.message);
                        }
                    }

                    // Fallback to standard phone field if custom fields don't exist
                    try {
                        contactRecord.setValue({
                            fieldId: 'phone',
                            value: phoneInfo.formatted || contactData.phone.trim()
                        });
                    } catch (phoneError) {
                        log.debug('Standard phone field error', phoneError.message);
                    }
                }

                // Set contact role directly on the contact record
                if (contactData.role && contactData.role.trim()) {
                    try {
                        contactRecord.setValue({
                            fieldId: 'contactrole',
                            value: contactData.role.trim()
                        });
                        log.debug('Set contact role', { role: contactData.role });
                    } catch (roleError) {
                        log.debug('Contact role field error', roleError.message);
                    }
                }

                // Set custom CRD PIN fields if available
                if (contactData.crdPin && contactData.crdPin.trim()) {
                    try {
                        contactRecord.setValue({
                            fieldId: 'custentity_crd_pin',
                            value: contactData.crdPin.trim()
                        });
                    } catch (pinError) {
                        log.debug('CRD PIN field not available', pinError.message);
                    }
                }

                // Set CRD Contact Approval Date for Primary Contacts (role -10)
                if (contactData.role && contactData.role.trim() === '-10') {
                    try {
                        const todayDate = new Date();
                        contactRecord.setValue({
                            fieldId: 'custentity_crd_contact_approval_date',
                            value: todayDate
                        });
                        log.debug('Set CRD Contact Approval Date for Primary Contact', { date: todayDate });
                    } catch (approvalDateError) {
                        log.debug('CRD Contact Approval Date field error', approvalDateError.message);
                    }
                }

                // Save the contact record
                const contactId = contactRecord.save();

                log.audit('Contact created successfully', {
                    contactId: contactId,
                    name: contactData.name,
                    customerId: customerId,
                    index: index
                });

                results.contactIds.push(contactId);
            } catch (contactError) {
                log.error('Failed to create contact', {
                    index: index,
                    error: contactError.message,
                    stack: contactError.stack,
                    contactData: contactData
                });

                results.errors.push({
                    index: index,
                    name: contactData.name,
                    error: contactError.message
                });

                results.success = false;
            }
        });

        return results;
    }

    /**
     * Give CRD customer the $500 signing bonus rebate
     * Replicates logic from GiveSigningBonus_Suitelet in customerUserEvents.js
     * @param {string} customerId - The NetSuite internal ID of the customer
     * @returns {Object} Result object with success status and rebate ID
     */
    function giveCRDSigningBonus(customerId) {
        try {
            // Check if customer already received signing bonus
            const customerLookup = search.lookupFields({
                type: 'customer',
                id: customerId,
                columns: ['custentity_received_crd_signing_bonus']
            });

            if (customerLookup.custentity_received_crd_signing_bonus === true) {
                log.debug('CRD signing bonus already received', { customerId: customerId });
                return {
                    success: true,
                    message: 'Signing bonus already received',
                    alreadyReceived: true
                };
            }

            // Create the rebate record
            const today = new Date();
            const expirationDate = new Date(today);
            expirationDate.setFullYear(expirationDate.getFullYear() + 1); // Expires in 1 year

            const rebateRecord = record.create({
                type: 'customrecord_crdrebate'
            });

            rebateRecord.setValue({ fieldId: 'custrecord_crdrebate_date', value: today });
            rebateRecord.setValue({ fieldId: 'custrecord_crdrebate_customer', value: customerId });
            rebateRecord.setValue({ fieldId: 'custrecord_crdrebate_amount', value: 500 });
            rebateRecord.setValue({ fieldId: 'custrecord_crdrebate_type', value: 1 }); // 1 = EARNED
            rebateRecord.setValue({ fieldId: 'custrecord_crdrebate_expiration_date', value: expirationDate });
            rebateRecord.setValue({ fieldId: 'custrecord_crdrebate_category', value: 2 }); // 2 = Signing Bonus

            const rebateId = rebateRecord.save();

            // Set redeemed_from to self (matches original behavior)
            record.submitFields({
                type: 'customrecord_crdrebate',
                id: rebateId,
                values: {
                    custrecord_crdrebate_redeemed_from: rebateId
                }
            });

            // Mark customer as having received the signing bonus
            record.submitFields({
                type: 'customer',
                id: customerId,
                values: {
                    custentity_received_crd_signing_bonus: true
                }
            });

            log.audit('CRD signing bonus applied', {
                customerId: customerId,
                rebateId: rebateId,
                amount: 500
            });

            return {
                success: true,
                rebateId: rebateId,
                amount: 500
            };
        } catch (error) {
            log.error('Failed to apply CRD signing bonus', {
                customerId: customerId,
                error: error.message,
                stack: error.stack
            });

            return {
                success: false,
                error: error.message
            };
        }
    }

    /**
     * Get available lead sources from NetSuite
     */
    function getLeadSources() {
        try {
            // Search for campaigns that can be used as lead sources
            const campaignSearch = search.create({
                type: 'campaign',
                filters: [
                    ['isinactive', 'is', 'F'] // Only active campaigns
                ],
                columns: [search.createColumn({ name: 'internalid', label: 'Internal ID' }), search.createColumn({ name: 'title', label: 'Campaign Name' }), search.createColumn({ name: 'campaignid', label: 'Campaign ID' })]
            });

            const leadSources = [];

            // Add a default "Other" option
            leadSources.push({
                id: '-1',
                name: 'Other/Unspecified'
            });

            campaignSearch.run().each(function (result) {
                const campaignId = result.getValue('internalid');
                const campaignTitle = result.getValue('title') || result.getValue('campaignid') || 'Campaign ' + campaignId;

                leadSources.push({
                    id: campaignId,
                    name: campaignTitle
                });

                return true; // Continue to next result
            });

            /* 
            log.debug('Lead sources retrieved', {
                count: leadSources.length,
                sources: leadSources.slice(0, 5) // Log first 5 for debugging
            }); */

            return leadSources;
        } catch (error) {
            log.error('Error getting lead sources', {
                error: error.message,
                stack: error.stack
            });

            // Return default options if campaign search fails
            return [
                { id: '-1', name: 'Other/Unspecified' },
                { id: '', name: 'No Lead Source' }
            ];
        }
    }

