                // Include CANCELLED status to show rescheduled/cancelled appointments (they will be styled differently)
                searchFilters = [['status', 'anyof', 'CONFIRMED', 'CANCELLED'], 'AND', ['completeddate', 'isempty', ''], 'AND', ['custevent_etype', 'noneof', '@NONE@'], 'AND', ['organizer', 'anyof', '@ALL@']];
