                <div class="modal-body" style="max-height: none; overflow: visible; padding: 1.5rem;">
                    <p class="instruction-text">Choose the salesperson for this appointment.</p>
                    
                    <div class="customer-section">
                        <div class="employee-dropdown-content" style="border: 1px solid #d1d5db; border-radius: 6px; background: white; max-height: none; overflow: visible; margin-top: 0.5rem;">
                            <div class="employee-column">
                                ${(() => {
                                    // Filter out blocked users and locations (same as main filter)
                                    const blockedUsers = ['Admin 1', 'Salesrep Cirrus', 'Scott Shelko', 'X0002', 'X4392'];
                                    const blockedLocations = ['Yaphank'];
                                    const filteredEmployees = employees.filter((emp) => {
                                        return !blockedUsers.includes(emp.name) && !blockedUsers.includes(emp.entityId) && !blockedLocations.includes(emp.location);
                                    });

                                    // Group employees by location
                                    const employeesByLocation = {};
                                    filteredEmployees.forEach((emp) => {
                                        const location = emp.location || 'No Location';
                                        if (!employeesByLocation[location]) {
                                            employeesByLocation[location] = [];
                                        }
                                        employeesByLocation[location].push(emp);
                                    });

                                    // Sort locations alphabetically (case-insensitive)
                                    const sortedLocations = Object.keys(employeesByLocation).sort((a, b) => {
                                        return a.toLowerCase().localeCompare(b.toLowerCase());
                                    });

                                    let html = '';

                                    // Split locations into two columns
                                    const leftColumnLocations = sortedLocations.slice(0, Math.ceil(sortedLocations.length / 2));
                                    const rightColumnLocations = sortedLocations.slice(Math.ceil(sortedLocations.length / 2));

                                    // Build left column
                                    leftColumnLocations.forEach((location) => {
                                        const locationEmployees = employeesByLocation[location].sort((a, b) => {
                                            return (a.name || '').toLowerCase().localeCompare((b.name || '').toLowerCase());
                                        });

                                        html += '<div class="multiselect-location-header">' + location + '</div>';
                                        locationEmployees.forEach((emp) => {
                                            html += '<div class="multiselect-option-emp employee-option"><label><input type="radio" name="salespersonSelect" value="' + emp.id + '" onchange="updateSalespersonSelection()"><span>' + emp.name + '</span></label></div>';
                                        });
                                    });

                                    html += '</div><div class="employee-column">';

                                    // Build right column
                                    rightColumnLocations.forEach((location) => {
                                        const locationEmployees = employeesByLocation[location].sort((a, b) => {
                                            return (a.name || '').toLowerCase().localeCompare((b.name || '').toLowerCase());
                                        });

                                        html += '<div class="multiselect-location-header">' + location + '</div>';
                                        locationEmployees.forEach((emp) => {
                                            html += '<div class="multiselect-option-emp employee-option"><label><input type="radio" name="salespersonSelect" value="' + emp.id + '" onchange="updateSalespersonSelection()"><span>' + emp.name + '</span></label></div>';
                                        });
                                    });

                                    return html;
                                })()}
                            </div>
                        </div>
                    </div>
                </div>
                
