            function handleUnableToCollectPrimaryAddress(event) {
                const isChecked = event.target.checked;
                const address1Field = document.getElementById('newCustomerAddress1');
                const cityField = document.getElementById('newCustomerCity');
                const stateField = document.getElementById('newCustomerState');
                const zipField = document.getElementById('newCustomerZip');

                if (isChecked) {
                    // Fill with placeholder address
                    address1Field.value = 'GET STREET ADDRESS';
                    cityField.value = 'Yaphank';
                    stateField.value = 'NY';
                    zipField.value = '11980';

                    // Disable all address fields
                    address1Field.disabled = true;
                    cityField.disabled = true;
                    stateField.disabled = true;
                    zipField.disabled = true;

                    // Update styling for disabled state
                    address1Field.style.backgroundColor = '#e5e7eb';
                    address1Field.style.cursor = 'not-allowed';
                    cityField.style.backgroundColor = '#e5e7eb';
                    stateField.style.backgroundColor = '#e5e7eb';
                    zipField.style.backgroundColor = '#e5e7eb';

                    // Set verification flag
                    window.primaryAddressPlaceholder = true;
                    window.primaryAddressVerified = false;

                    // Clear any error messages
                    const errorElements = ['newCustomerAddress1-error', 'newCustomerCity-error', 'newCustomerState-error', 'newCustomerZip-error'];
                    errorElements.forEach(id => {
                        const element = document.getElementById(id);
                        if (element) {
                            element.style.display = 'none';
                        }
                    });

                    // Clear success messages and duplicate warnings
                    const successElement = document.getElementById('newCustomerAddress1-success');
                    if (successElement) {
                        successElement.style.display = 'none';
                    }
                    const duplicateContainer = document.getElementById('newCustomerAddress1-duplicate');
                    if (duplicateContainer) {
                        duplicateContainer.innerHTML = '';
                        duplicateContainer.style.display = 'none';
                    }

                } else {
                    // Clear fields
                    address1Field.value = '';
                    cityField.value = '';
                    stateField.value = '';
                    zipField.value = '';

                    // Re-enable address1, keep city/state/zip readonly
                    address1Field.disabled = false;
                    address1Field.style.backgroundColor = '';
                    address1Field.style.cursor = '';

                    // City/State/ZIP remain readonly (unless in fallback mode)
                    if (!window.googleAPIFallbackMode) {
                        cityField.style.backgroundColor = '#f9fafb';
                        stateField.style.backgroundColor = '#f9fafb';
                        zipField.style.backgroundColor = '#f9fafb';
                    }

                    // Reset flag
                    window.primaryAddressPlaceholder = false;
                }
            }

