            function initializeInlineNonCustomerEventTypeButtons() {
                var inlineButtons = document.querySelectorAll('.inline-non-customer-btn');

                inlineButtons.forEach(function(button) {
                    button.addEventListener('click', function() {
                        // Visual feedback: remove selected from all, add to clicked
                        inlineButtons.forEach(function(btn) {
                            btn.classList.remove('selected');
                        });
                        this.classList.add('selected');

                        // Set the selected event type
                        var eventTypeId = this.dataset.eventType;
                        selectedEventType = eventTypeId;
                        window.selectedEventType = eventTypeId;
                        console.log('Inline non-customer event type selected:', eventTypeId);

                        // Handle Scheduled Day Off - mark all time slots as occupied
                        if (eventTypeId === '10') {
                            markAllTimeSlotsOccupied();
                        } else {
                            // For other event types, restore normal time slot availability
                            restoreTimeSlotsAvailability();
                        }

                        // Validate form to enable/disable create button
                        validateAppointmentForm();
                    });
                });
            }

