            // Parse a full address string into individual components using Google Geocoding
            function parseAddressIntoComponents(fullAddress) {
                if (!fullAddress || !google || !google.maps || !google.maps.Geocoder) {
                    console.warn('Cannot parse address: Google Maps not available or no address provided');
                    return;
                }
                
                console.log('Parsing address into components:', fullAddress);
                
                const geocoder = new google.maps.Geocoder();
                
                geocoder.geocode({ address: fullAddress }, function(results, status) {
                    if (status === 'OK' && results && results.length > 0) {
                        const result = results[0];
                        const addressComponents = result.address_components;
                        
                        console.log('Address parsing successful:', addressComponents);
                        
                        // Extract components
                        let streetNumber = '';
                        let streetName = '';
                        let city = '';
                        let state = '';
                        let zipCode = '';
                        
                        addressComponents.forEach(component => {
                            const types = component.types;
                            
                            if (types.includes('street_number')) {
                                streetNumber = component.long_name;
                            } else if (types.includes('route')) {
                                streetName = component.long_name;
                            } else if (types.includes('locality')) {
                                city = component.long_name;
                            } else if (types.includes('administrative_area_level_1')) {
                                state = component.short_name;
                            } else if (types.includes('postal_code')) {
                                zipCode = component.long_name;
                            }
                        });
                        
                        // Populate the form fields
                        const address1Field = document.getElementById('newCustomerAddress1');
                        const cityField = document.getElementById('newCustomerCity');
                        const stateField = document.getElementById('newCustomerState');
                        const zipField = document.getElementById('newCustomerZip');
                        
                        // Update address field with street number + street name only
                        if (address1Field && (streetNumber || streetName)) {
                            const streetAddress = [streetNumber, streetName].filter(x => x).join(' ');
                            if (streetAddress) {
                                address1Field.value = streetAddress;
                            }
                        }
                        
                        // Populate other fields
                        if (cityField && city) {
                            cityField.value = city;
                        }
                        
                        if (stateField && state) {
                            stateField.value = state;
                        }
                        
                        if (zipField && zipCode) {
                            zipField.value = zipCode;
                        }
                        
                        // Show success indicator
                        const addressField = document.getElementById('newCustomerAddress1');
                        if (addressField) {
                            // Show success message in the dedicated success div
                        const successElement = document.getElementById('newCustomerAddress1-success');
                        if (successElement) {
                            successElement.textContent = '✓ Address verified';
                            successElement.style.display = 'block';
                        }
                        // Also set the border color
                        addressField.style.borderColor = '#059669';
                        }
                        
                        console.log('Address components populated:', {
                            street: streetNumber + ' ' + streetName,
                            city,
                            state,
                            zip: zipCode
                        });
                        
                    } else {
                        console.warn('Address parsing failed:', status, results);
                        
                        // Try simple parsing as fallback
                        parseAddressSimple(fullAddress);
                    }
                });
            }
            
            // Simple fallback address parsing for when Google Geocoding fails
            function parseAddressSimple(fullAddress) {
                console.log('Using simple address parsing for:', fullAddress);
                
                // Split by comma and try to extract components
                const parts = fullAddress.split(',').map(part => part.trim());
                
                if (parts.length >= 3) {
                    // Assume format: "Street, City, State ZIP"
                    const cityField = document.getElementById('newCustomerCity');
                    const stateZipPart = parts[parts.length - 1]; // Last part should be "State ZIP"
                    
                    // Extract city (second to last part)
                    if (cityField && parts.length > 2) {
                        cityField.value = parts[parts.length - 2];
                    }
                    
                    // Parse state and zip from last part
                    const stateZipMatch = stateZipPart.match(/^([A-Z]{2})\s+(\d{5}(?:-\d{4})?)$/);
                    if (stateZipMatch) {
                        const stateField = document.getElementById('newCustomerState');
                        const zipField = document.getElementById('newCustomerZip');
                        
                        if (stateField) stateField.value = stateZipMatch[1];
                        if (zipField) zipField.value = stateZipMatch[2];
                    }
                    
                    // Update address field to just the street part
                    const addressField = document.getElementById('newCustomerAddress1');
                    if (addressField && parts.length > 0) {
                        addressField.value = parts[0]; // First part should be street address
                    }
                }
            }
            
            function loadLeadSources() {
                const leadSourceSelect = document.getElementById('newCustomerLeadSource');
                if (!leadSourceSelect) return;
                
                // Show loading state
                leadSourceSelect.innerHTML = '<option value="">Loading lead sources...</option>';
                leadSourceSelect.disabled = true;
                
                // Fetch lead sources from server
                const currentUrl = new URL(window.location.href);
                currentUrl.searchParams.set('action', 'getLeadSources');
                
                fetch(currentUrl.toString(), {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    }
                })
                .then(response => response.json())
                .then(data => {
                    if (data.success && data.leadSources) {
                        // Clear loading state
                        leadSourceSelect.innerHTML = '';
                        
                        // Add default option
                        const defaultOption = document.createElement('option');
                        defaultOption.value = '';
                        defaultOption.textContent = 'Select a lead source...';
                        leadSourceSelect.appendChild(defaultOption);
                        
                        // Add lead source options
                        data.leadSources.forEach(source => {
                            const option = document.createElement('option');
                            option.value = source.id;
                            option.textContent = source.name;
                            leadSourceSelect.appendChild(option);
                        });
                        
                        // Set default selection based on user location
                        // If user's location is Cabinet Direct (ID 14), set to "KIK-PHONE" (ID 11)
                        // Otherwise, set to "SHOWROOM-GENERAL" (ID 1146)
                        let defaultLeadSourceId = '';
                        if (userLocation === '14') {
                            defaultLeadSourceId = '804443'; // CabinetDirect - Phone In
                        } else {
                            defaultLeadSourceId = '1146'; // SHOWROOM-GENERAL
                        }
                        
                        // Set the default selection if the option exists
                        const selectedOption = leadSourceSelect.querySelector('option[value="' + defaultLeadSourceId + '"]');
                        if (selectedOption) {
                            leadSourceSelect.value = defaultLeadSourceId;
                            console.log('Default lead source set:', selectedOption.textContent, 'for user location:', userLocation);
                        } else {
                            console.warn('Default lead source not found:', defaultLeadSourceId, 'for user location:', userLocation);
                        }
                        
                        leadSourceSelect.disabled = false;
                    } else {
                        // Error loading lead sources - provide fallback options with defaults
                        leadSourceSelect.innerHTML = '';
                        
                        // Add fallback options
                        const fallbackOptions = [
                            { id: '-1', name: 'Other/Unspecified' },
                            { id: '11', name: 'KIK-PHONE' },
                            { id: '1146', name: 'SHOWROOM-GENERAL' }
                        ];
                        
                        fallbackOptions.forEach(source => {
                            const option = document.createElement('option');
                            option.value = source.id;
                            option.textContent = source.name;
                            leadSourceSelect.appendChild(option);
                        });
                        
                        // Set default selection based on user location even in error case
                        let defaultLeadSourceId = '';
                        if (userLocation === '14') {
                            defaultLeadSourceId = '11'; // KIK-PHONE
                        } else {
                            defaultLeadSourceId = '1146'; // SHOWROOM-GENERAL
                        }
                        
                        leadSourceSelect.value = defaultLeadSourceId;
                        leadSourceSelect.disabled = false;
                        console.error('Failed to load lead sources:', data.message);
                        console.log('Using fallback lead sources with default:', defaultLeadSourceId);
                    }
                })
                .catch(error => {
                    console.error('Error loading lead sources:', error);
                    
                    // Provide fallback options with defaults even in catch case
                    leadSourceSelect.innerHTML = '';
                    
                    const fallbackOptions = [
                        { id: '-1', name: 'Other/Unspecified' },
                        { id: '11', name: 'KIK-PHONE' },
                        { id: '1146', name: 'SHOWROOM-GENERAL' }
                    ];
                    
                    fallbackOptions.forEach(source => {
                        const option = document.createElement('option');
                        option.value = source.id;
                        option.textContent = source.name;
                        leadSourceSelect.appendChild(option);
                    });
                    
                    // Set default selection based on user location
                    let defaultLeadSourceId = '';
                    if (userLocation === '14') {
                        defaultLeadSourceId = '11'; // KIK-PHONE
                    } else {
                        defaultLeadSourceId = '1146'; // SHOWROOM-GENERAL
                    }
                    
                    leadSourceSelect.value = defaultLeadSourceId;
                    leadSourceSelect.disabled = false;
                    console.log('Using fallback lead sources with default:', defaultLeadSourceId);
                });
            }
            
