            function validateNewCustomerForm() {
                clearFieldErrors();
                let isValid = true;
                
                const name = document.getElementById('newCustomerName').value.trim();
                const phone = document.getElementById('newCustomerPhone').value.trim();
                const email = document.getElementById('newCustomerEmail').value.trim();
                const leadSource = document.getElementById('newCustomerLeadSource').value.trim();
                const address1 = document.getElementById('newCustomerAddress1').value.trim();
                const city = document.getElementById('newCustomerCity').value.trim();
                const state = document.getElementById('newCustomerState').value.trim();
                const zip = document.getElementById('newCustomerZip').value.trim();
                
                // Validate name (required)
                if (!name) {
                    showFieldError('newCustomerName', 'Customer name is required');
                    isValid = false;
                } else if (name.length < 2) {
                    showFieldError('newCustomerName', 'Customer name must be at least 2 characters');
                    isValid = false;
                }
                
                // Validate phone (required)
                if (!phone) {
                    showFieldError('newCustomerPhone', 'Phone number is required');
                    isValid = false;
                } else if (phone.length < 10) {
                    showFieldError('newCustomerPhone', 'Phone number must be at least 10 digits');
                    isValid = false;
                }
                
                // Lead source validation removed - field is hidden and automatically set based on user location
                
                // Validate email (required)
                if (!email) {
                    showFieldError('newCustomerEmail', 'Email address is required');
                    isValid = false;
                } else if (!isValidEmail(email)) {
                    showFieldError('newCustomerEmail', 'Please enter a valid email address');
                    isValid = false;
                }
                
                // Validate address fields (required based on user changes)
                if (!address1) {
                    showFieldError('newCustomerAddress1', 'Street address is required');
                    isValid = false;
                }
                
                if (!city) {
                    showFieldError('newCustomerCity', 'City is required');
                    isValid = false;
                }
                
                if (!state) {
                    showFieldError('newCustomerState', 'State is required');
                    isValid = false;
                }
                
                if (!zip) {
                    showFieldError('newCustomerZip', 'ZIP code is required');
                    isValid = false;
                } else if (zip.length < 5) {
                    showFieldError('newCustomerZip', 'ZIP code must be at least 5 digits');
                    isValid = false;
                }

                // Google Places verification check
                // Address must be verified via Google Places OR placeholder checkbox OR API fallback mode
                if (address1 && city && state && zip) {
                    const isPrimaryVerified = window.primaryAddressVerified || window.primaryAddressPlaceholder || window.googleAPIFallbackMode;
                    if (!isPrimaryVerified) {
                        showFieldError('newCustomerAddress1', 'You must select an address from the Google Places dropdown or check "Unable to collect address"');
                        isValid = false;
                    }
                }

                // Billing address validation (if billing address section is shown)
                const sameAsBilling = document.getElementById('sameAsBilling').checked;
                if (!sameAsBilling) {
                    const billingAddress1 = document.getElementById('newCustomerBillingAddress1').value.trim();
                    const billingCity = document.getElementById('newCustomerBillingCity').value.trim();
                    const billingState = document.getElementById('newCustomerBillingState').value.trim();
                    const billingZip = document.getElementById('newCustomerBillingZip').value.trim();

                    // If any billing field is filled, all billing fields are required
                    if (billingAddress1 || billingCity || billingState || billingZip) {
                        if (!billingAddress1) {
                            showFieldError('newCustomerBillingAddress1', 'Billing street address is required');
                            isValid = false;
                        }
                        if (!billingCity) {
                            showFieldError('newCustomerBillingCity', 'Billing city is required');
                            isValid = false;
                        }
                        if (!billingState) {
                            showFieldError('newCustomerBillingState', 'Billing state is required');
                            isValid = false;
                        }
                        if (!billingZip) {
                            showFieldError('newCustomerBillingZip', 'Billing ZIP code is required');
                            isValid = false;
                        } else if (billingZip.length < 5) {
                            showFieldError('newCustomerBillingZip', 'Billing ZIP code must be at least 5 digits');
                            isValid = false;
                        }

                        // Google Places verification check for billing address
                        if (billingAddress1 && billingCity && billingState && billingZip) {
                            const isBillingVerified = window.billingAddressVerified || window.billingAddressPlaceholder || window.googleAPIFallbackMode;
                            if (!isBillingVerified) {
                                showFieldError('newCustomerBillingAddress1', 'You must select a billing address from the Google Places dropdown or check "Unable to collect billing address"');
                                isValid = false;
                            }
                        }
                    }
                }

                // CRD-specific validation
                if (isCRDMode) {
                    // Validate business type (required for CRD)
                    const businessType = document.getElementById('newCustomerBusinessType').value.trim();
                    if (!businessType) {
                        showFieldError('newCustomerBusinessType', 'Business type is required for CRD customers');
                        isValid = false;
                    }

                    // Validate that at least one contact is added
                    const contactRows = document.querySelectorAll('#crdContactsContainer .contact-row');
                    if (contactRows.length === 0) {
                        alert('Please add at least one contact for the CRD customer.');
                        isValid = false;
                    } else {
                        // Validate each contact
                        let contactValid = true;
                        contactRows.forEach(function(row, index) {
                            const contactName = row.querySelector('.contact-name').value.trim();
                            const contactPhone = row.querySelector('.contact-phone').value.trim();
                            const contactEmail = row.querySelector('.contact-email').value.trim();
                            const crdPin = row.querySelector('.contact-crd-pin').value.trim();
                            const crdPinConfirm = row.querySelector('.contact-crd-pin-confirm').value.trim();
                            const phoneErrorDiv = row.querySelector('.contact-phone-error');
                            const emailErrorDiv = row.querySelector('.contact-email-error');
                            const pinErrorDiv = row.querySelector('.contact-pin-error');

                            // Clear all errors first
                            if (phoneErrorDiv) phoneErrorDiv.style.display = 'none';
                            if (emailErrorDiv) emailErrorDiv.style.display = 'none';
                            if (pinErrorDiv) pinErrorDiv.style.display = 'none';

                            // Validate contact name (required)
                            if (!contactName) {
                                alert('Contact name is required for all contacts');
                                contactValid = false;
                                isValid = false;
                            }

                            // Validate contact phone (if provided, must be at least 10 digits)
                            if (contactPhone && contactPhone.replace(/\D/g, '').length < 10) {
                                if (phoneErrorDiv) {
                                    phoneErrorDiv.textContent = 'Phone number must be at least 10 digits';
                                    phoneErrorDiv.style.display = 'block';
                                    phoneErrorDiv.style.color = '#991b1b';
                                }
                                contactValid = false;
                                isValid = false;
                            }

                            // Validate contact email (if provided, must be valid format)
                            if (contactEmail && !isValidEmail(contactEmail)) {
                                if (emailErrorDiv) {
                                    emailErrorDiv.textContent = 'Please enter a valid email address';
                                    emailErrorDiv.style.display = 'block';
                                    emailErrorDiv.style.color = '#991b1b';
                                }
                                contactValid = false;
                                isValid = false;
                            }

                            // Validate CRD Password (required for all contacts)
                            if (!crdPin) {
                                if (pinErrorDiv) {
                                    pinErrorDiv.textContent = 'CRD password is required';
                                    pinErrorDiv.style.display = 'block';
                                    pinErrorDiv.style.color = '#991b1b';
                                }
                                contactValid = false;
                                isValid = false;
                            } else if (!crdPinConfirm) {
                                if (pinErrorDiv) {
                                    pinErrorDiv.textContent = 'Please confirm CRD password';
                                    pinErrorDiv.style.display = 'block';
                                    pinErrorDiv.style.color = '#991b1b';
                                }
                                contactValid = false;
                                isValid = false;
                            } else if (crdPin !== crdPinConfirm) {
                                if (pinErrorDiv) {
                                    pinErrorDiv.textContent = 'CRD passwords do not match';
                                    pinErrorDiv.style.display = 'block';
                                    pinErrorDiv.style.color = '#991b1b';
                                }
                                contactValid = false;
                                isValid = false;
                            }
                        });

                        if (!contactValid) {
                            alert('Please fix the contact validation errors before submitting.');
                        }
                    }
                }

                return isValid;
            }
            
            function isValidEmail(email) {
                // Try RegExp constructor instead of literal (fallback for NetSuite environment)
                try {
                    const regexConstructor = new RegExp("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
                    const constructorResult = regexConstructor.test(email);
                    
                    if (constructorResult) {
                        return true;
                    }
                } catch (e) {
                    // Fallback to manual validation if RegExp fails
                }
                
                // Fallback: manual validation
                const atIndex = email.indexOf('@');
                const lastDotIndex = email.lastIndexOf('.');
                
                const hasAt = atIndex > 0; // @ should not be first character
                const hasDot = lastDotIndex > atIndex + 1; // dot should be after @ with at least 1 char between
                const hasEndPart = lastDotIndex < email.length - 1; // should have characters after the last dot
                const noSpaces = email.indexOf(' ') === -1; // no spaces allowed
                
                return hasAt && hasDot && hasEndPart && noSpaces;
            }

            // Utility function to strip non-numeric characters from phone numbers
            function stripAlphaChars(str) {
                return str.replace(/[^0-9]/g, '');
            }

            // Phone verification using Twilio
            async function twilioPhoneLookup(twiliophone) {
                const twilioHeader = {
                    "Authorization": "Basic QUNkMGU1ZGJjZGYxMjhjOTdmMmQ2OGMzMDMwNWIwMzMxZDpkMzhiNTE3ZWU2ZWY0YTQ1MGVlNDU3MDBkZWFjOWRmZg==",
                    "Content-Type": "application/x-www-form-urlencoded",
                    "Accept": "application/json"
                };
                
                twiliophone = stripAlphaChars(twiliophone);
                console.log("Verifying phone:", twiliophone);
                
                const urltwilio = 'https://lookups.twilio.com/v2/PhoneNumbers/' + twiliophone + '?Fields=line_type_intelligence';
                console.log("Twilio URL:", urltwilio);

                try {
                    const response = await fetch(urltwilio, {
                        method: 'GET',
                        headers: twilioHeader
                    });
                    
                    const result = response.status;
                    const responseBody = await response.json();
                    console.log("Phone verification response code:", result);
                    console.log("Phone verification response body:", responseBody);

                    // Confirm valid API call
                    if (result !== 200 && result !== 201 && result !== 406) {
                        console.error("Phone verification error:", responseBody);
                        return ['error', ''];
                    }

                    // Check for error code
                    if (responseBody.valid === false) {
                        console.error("Invalid phone number:", responseBody);
                        return ['error', ''];
                    }

                    // Get Phone type
                    if (result !== 406) {
                        if (responseBody.line_type_intelligence && responseBody.line_type_intelligence.type) {
                            return [
                                responseBody.line_type_intelligence.type, 
                                responseBody.national_format, 
                                responseBody.line_type_intelligence.carrier_name
                            ];
                        } else {
                            console.error("Missing line type intelligence:", responseBody);
                            return ['error', ''];
                        }
                    } else {
                        return ['unknown', ''];
                    }
                } catch (error) {
                    console.error("Phone verification network error:", error);
                    return ['error', ''];
                }
            }

            // Email verification using Emailable
            async function verifyEmail(email) {
                const key = 'live_785fd7f6a91a7d9514e2';
                const urlEmailable = 'https://api.emailable.com/v1/verify?email=' + encodeURIComponent(email) + '&api_key=' + key;

                let attempts = 0;
                let responsecode, responseBody;

                try {
                    do {
                        const emailableResponse = await fetch(urlEmailable, {
                            method: 'POST'
                        });
                        
                        responsecode = emailableResponse.status;
                        responseBody = await emailableResponse.json();
                        console.log("Email verification response code:", responsecode);
                        ++attempts;
                    } while (responsecode === 249 && attempts < 5);

                    console.log("Email verification response body:", responseBody);

                    if (responsecode === 200 || responsecode === 201) {
                        return [responseBody.state, responseBody.reason];
                    } else {
                        return false;
                    }
                } catch (error) {
                    console.error("Email verification network error:", error);
                    return false;
                }
            }

            // Global variable to store phone verification results
            window.phoneVerificationData = null;

            // Search for customers by phone number
            async function searchCustomersByPhone(phoneNumber) {
                try {
                    const currentUrl = new URL(window.location.href);
                    currentUrl.searchParams.set('action', 'searchCustomersByPhone');
                    currentUrl.searchParams.set('phoneNumber', phoneNumber);
                    
                    const response = await fetch(currentUrl.toString(), {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                        }
                    });
                    
                    const data = await response.json();
                    return data;
                } catch (error) {
                    console.error('Error searching customers by phone:', error);
                    return { success: false, error: error.message };
                }
            }

