            // Show verification status for phone
            function showPhoneVerificationStatus(status, formatted, carrier) {
                const errorElement = document.getElementById('newCustomerPhone-error');
                const fieldElement = document.getElementById('newCustomerPhone');
                
                if (!errorElement || !fieldElement) return;

                // Store verification data globally for later use
                window.phoneVerificationData = {
                    type: status,
                    formatted: formatted,
                    carrier: carrier,
                    verified: status !== 'error'
                };

                // Check if there's already a customer exists alert - don't override it
                if (window.existingCustomersWithPhone && window.existingCustomersWithPhone.length > 0) {
                    // Don't override customer exists alert, just update the field with formatted number
                    if (formatted && status !== 'error') {
                        fieldElement.value = formatted;
                    }
                    return;
                }

                if (status === 'error') {
                    errorElement.textContent = 'Unable to verify phone number. Please check the number is valid.';
                    errorElement.style.display = 'block';
                    errorElement.style.color = '#991b1b';
                    errorElement.style.background = '#fee2e2';
                    errorElement.style.padding = '0.25rem 0.5rem';
                    errorElement.style.borderRadius = '4px';
                    errorElement.style.border = '1px solid #f87171';
                    fieldElement.style.borderColor = '#dc2626';
                } else if (status === 'unknown') {
                    errorElement.textContent = 'Phone number verification unavailable for this number.';
                    errorElement.style.display = 'block';
                    errorElement.style.color = '#92400e';
                    errorElement.style.background = '#fef3c7';
                    errorElement.style.padding = '0.25rem 0.5rem';
                    errorElement.style.borderRadius = '4px';
                    errorElement.style.border = '1px solid #f59e0b';
                    fieldElement.style.borderColor = '#f59e0b';
                } else {
                    // Success - show success message
                    errorElement.style.display = 'none';
                    fieldElement.style.borderColor = '#059669';

                    // Hide success message (removed per user request)
                    const successElement = document.getElementById('newCustomerPhone-success');
                    if (successElement) {
                        successElement.style.display = 'none';
                    }

                    // Show detailed verification information
                    showPhoneVerificationInfo(status, carrier);

                    // Update the field with formatted number if available
                    if (formatted) {
                        fieldElement.value = formatted;
                    }
                }
            }

