             /**
              * Helper function to parse time string to decimal hour
              * Handles formats: "9:30 AM", "2:00 PM", "9:30 am", "10:00am", etc.
              */
             function parseTimeToHour(timeStr) {
                 if (!timeStr || timeStr === 'N/A') return null;

                 // Trim and normalize the input
                 const normalized = timeStr.trim().toLowerCase();
                 console.log('    parseTimeToHour input:', JSON.stringify(timeStr), '->', JSON.stringify(normalized));

                 // More flexible regex - allow optional whitespace before am/pm
                 const match = normalized.match(/(\\d{1,2}):(\\d{2})\\s*(am|pm)?/);
                 console.log('    parseTimeToHour match result:', match);

                 if (!match) {
                     console.log('    parseTimeToHour FAILED: no regex match');
                     return null;
                 }

                 let hour = parseInt(match[1]);
                 const minute = parseInt(match[2]);
                 const ampm = match[3] ? match[3].toUpperCase() : null;

                 console.log('    parseTimeToHour parsed:', {hour: hour, minute: minute, ampm: ampm});

                 // Convert to 24-hour format
                 if (ampm === 'PM' && hour !== 12) {
                     hour += 12;
                 } else if (ampm === 'AM' && hour === 12) {
                     hour = 0;
                 }

                 const result = hour + (minute / 60);
                 console.log('    parseTimeToHour result:', result);
                 return result;
             }

             /**
              * Helper function to check if two dates are the same day
              */
             function isSameDay(date1, date2) {
                 return date1.getFullYear() === date2.getFullYear() &&
                        date1.getMonth() === date2.getMonth() &&
                        date1.getDate() === date2.getDate();
             }

