            function formatTime(timeValue) {
                if (!timeValue || timeValue === undefined || timeValue === null) return 'N/A';
                try {
                    // Handle string times like "9:30 am" or "2:00 pm"
                    if (typeof timeValue === 'string') {
                        const timeStr = String(timeValue).trim();
                        
                        // Check if it already has AM/PM
                        if (/am|pm/i.test(timeStr)) {
                            // Just clean up the formatting
                            return timeStr
                                .toLowerCase()
                                .replace(/\s*am\s*/i, ' AM')
                                .replace(/\s*pm\s*/i, ' PM')
                                .trim();
                        }
                        
                        // Try to parse as HH:MM format
                        const timeMatch = timeStr.match(/^(\d{1,2}):(\d{2})$/);
                        if (timeMatch) {
                            const hours = parseInt(timeMatch[1]);
                            const minutes = parseInt(timeMatch[2]);
                            
                            if (!isNaN(hours) && !isNaN(minutes)) {
                                let displayHours = hours;
                                let ampm = 'AM';
                                
                                if (hours === 0) {
                                    displayHours = 12;
                                } else if (hours === 12) {
                                    ampm = 'PM';
                                } else if (hours > 12) {
                                    displayHours = hours - 12;
                                    ampm = 'PM';
                                }
                                
                                const displayMinutes = minutes < 10 ? '0' + minutes : minutes;
                                return displayHours + ':' + displayMinutes + ' ' + ampm;
                            }
                        }
                    }
                    
                    // Try Date parsing as fallback
                    if (timeValue instanceof Date) {
                        return timeValue.toLocaleTimeString('en-US', { 
                            hour: 'numeric', 
                            minute: '2-digit',
                            hour12: true 
                        });
                    }
                    
                    return 'N/A';
                } catch (error) {
                    return 'N/A';
                }
            }
            
            function formatDateForDisplay(dateString) {
                if (!dateString) return 'N/A';
                try {
                    const date = new Date(dateString);
                    if (!isNaN(date.getTime())) {
                        return date.toLocaleDateString('en-US', { 
                            weekday: 'short', 
                            month: 'short', 
                            day: 'numeric' 
                        });
                    }
                    return dateString;
                } catch (error) {
                    return dateString;
                }
            }
            
                         function parseNetSuiteDate(dateValue) {
                 if (!dateValue) return null;
                 
                 try {
                     // If it's already a Date object
                     if (dateValue instanceof Date) {
                         return dateValue;
                     }
                     
                     // If it's a string, try to parse it
                     if (typeof dateValue === 'string') {
                         // Handle MM/DD/YYYY format
                         if (dateValue.includes('/')) {
                             const parts = dateValue.split('/');
                             if (parts.length === 3) {
                                 const month = parseInt(parts[0]) - 1; // Month is 0-indexed
                                 const day = parseInt(parts[1]);
                                 const year = parseInt(parts[2]);
                                 const result = new Date(year, month, day);
                                 return result;
                             }
                         }
                         
                         // Handle YYYY-MM-DD format
                         if (dateValue.includes('-')) {
                             const parts = dateValue.split('-');
                             if (parts.length === 3) {
                                 const year = parseInt(parts[0]);
                                 const month = parseInt(parts[1]) - 1; // Month is 0-indexed
                                 const day = parseInt(parts[2]);
                                 const result = new Date(year, month, day);
                                 return result;
                             }
                         }
                         
                         // Try standard date parsing
                         const date = new Date(dateValue);
                         if (!isNaN(date.getTime())) {
                             return date;
                         }
                     }
                     
                     return null;
                 } catch (error) {
                     return null;
                 }
             }
            
            function formatDateForTable(dateString) {
                try {
                    const date = new Date(dateString);
                    if (!isNaN(date.getTime())) {
                        return date.toLocaleDateString('en-US', {
                            month: 'short',
                            day: 'numeric',
                            year: 'numeric'
                        });
                    }
                    return dateString;
                } catch (error) {
                    return dateString;
                }
            }
            
            // Helper function to decode HTML entities and render HTML
            function decodeHtmlEntities(text) {
                if (!text) return text;
                const textarea = document.createElement('textarea');
                textarea.innerHTML = text;
                return textarea.value;
            }
            
