             // Date Range Picker Functions (for main appointment filtering)
             let currentCalendarDate = new Date();
             let selectedStartDate = null;
             let selectedEndDate = null;
             let isSelectingRange = false;

             // View Mode State Management
             let currentViewMode = 'daily';  // 'daily', 'weekly-test', or 'monthly'
             let viewReferenceDate = new Date();  // The "anchor" date for the current view
             let appointmentsByDate = {};  // Global store for appointments grouped by date (used by monthly view)

             // Daily Appointment Panel State Management
             let selectedPanelDate = null;  // Currently selected date in the panel
             let isPanelOpen = false;  // Track if panel is currently visible
             let allAppointmentsData = [];  // Store all loaded appointments for filtering

             /**
              * Format date as YYYY-MM-DD for NetSuite
              */
             function formatDateYYYYMMDD(date) {
                 const year = date.getFullYear();
                 const month = String(date.getMonth() + 1).padStart(2, '0');
                 const day = String(date.getDate()).padStart(2, '0');
                 return year + '-' + month + '-' + day;
             }

             /**
              * Calculate date range for a given view mode
              */
             function calculateDateRangeForView(viewMode, referenceDate) {
                 const ref = new Date(referenceDate);
                 let startDate, endDate;

                 switch(viewMode) {
                     case 'daily':
                         // Same day
                         startDate = new Date(ref);
                         startDate.setHours(0, 0, 0, 0);
                         endDate = new Date(ref);
                         endDate.setHours(23, 59, 59, 999);
                         break;

                     case 'weekly-test':
                         // Week starts on Sunday (US convention)
                         const dayOfWeek = ref.getDay(); // 0 = Sunday, 6 = Saturday
                         startDate = new Date(ref);
                         startDate.setDate(ref.getDate() - dayOfWeek); // Go to Sunday
                         startDate.setHours(0, 0, 0, 0);

                         endDate = new Date(startDate);
                         endDate.setDate(startDate.getDate() + 6); // Saturday
                         endDate.setHours(23, 59, 59, 999);
                         break;

                     case 'monthly':
                         // First day to last day of month
                         startDate = new Date(ref.getFullYear(), ref.getMonth(), 1);
                         startDate.setHours(0, 0, 0, 0);
                         endDate = new Date(ref.getFullYear(), ref.getMonth() + 1, 0); // Last day
                         endDate.setHours(23, 59, 59, 999);
                         break;

                     default:
                         // Fallback to daily
                         startDate = new Date(ref);
                         startDate.setHours(0, 0, 0, 0);
                         endDate = new Date(ref);
                         endDate.setHours(23, 59, 59, 999);
                 }

                 return { startDate: startDate, endDate: endDate };
             }

             /**
              * Update visual state of view mode buttons
              */
             function updateViewButtonStates(activeMode) {
                 ['daily', 'weekly-test', 'monthly'].forEach(function(mode) {
                     const btnId = mode === 'weekly-test' ? 'weeklyTestViewBtn' : mode + 'ViewBtn';
                     const btn = document.getElementById(btnId);
                     if (btn) {
                         if (mode === activeMode) {
                             btn.classList.add('active');
                         } else {
                             btn.classList.remove('active');
                         }
                     }
                 });
             }

             /**
              * Apply a view mode and update the UI
              */
             function applyViewMode(mode) {
                 // Update state
                 currentViewMode = mode;

                 // Calculate new date range
                 const dateRange = calculateDateRangeForView(mode, viewReferenceDate);

                 // Update global date variables
                 selectedStartDate = new Date(dateRange.startDate);
                 selectedEndDate = new Date(dateRange.endDate);

                 // Update hidden inputs (YYYY-MM-DD format)
                 document.getElementById('startDateFilter').value = formatDateYYYYMMDD(dateRange.startDate);
                 document.getElementById('endDateFilter').value = formatDateYYYYMMDD(dateRange.endDate);

                 // Update visible date range display
                 updateDateRangeInput(); // Existing function

                 // Update button visual states
                 updateViewButtonStates(mode);

                 // Handle panel visibility based on view mode
                 const panel = document.getElementById('dailyAppointmentPanel');
                 if (panel) {
                     if (mode === 'daily') {
                         // Hide panel in daily/table view
                         closeDailyAppointmentPanel();
                     }
                     // For weekly/monthly views, panel remains in current state (open/closed)
                 }

                 // Fetch appointments with new date range
                 filterAppointments(); // Existing function - triggers AJAX POST
             }

             /**
              * Set view mode (called when clicking view buttons)
              */
             function setViewMode(mode) {
                 // Reset reference date to today when switching modes
                 viewReferenceDate = new Date();
                 // Set flag to update panel to first date in range
                 pendingPanelUpdate = true;
                 applyViewMode(mode);
             }

             /**
              * Get the visible date range for the current view mode
              * @returns {Object} Object with startDate and endDate properties
              */
             function getVisibleDateRange() {
                 let startDate, endDate;

                 // First check if there's a manually selected date range in the filters
                 const startDateFilter = document.getElementById('startDateFilter');
                 const endDateFilter = document.getElementById('endDateFilter');

                 if (startDateFilter && endDateFilter && startDateFilter.value && endDateFilter.value) {
                     // Use the manually selected date range
                     startDate = parseDateLocal(startDateFilter.value);
                     endDate = parseDateLocal(endDateFilter.value);

                     if (startDate && endDate) {
                         return { startDate: startDate, endDate: endDate };
                     }
                 }

                 // Fall back to calculating from viewReferenceDate and currentViewMode
                 switch(currentViewMode) {
                     case 'monthly':
                         startDate = new Date(viewReferenceDate.getFullYear(), viewReferenceDate.getMonth(), 1);
                         endDate = new Date(viewReferenceDate.getFullYear(), viewReferenceDate.getMonth() + 1, 0);
                         break;

                     case 'weekly-test':
                         // Week starts on Sunday (US convention)
                         const dayOfWeek = viewReferenceDate.getDay(); // 0 = Sunday, 6 = Saturday
                         startDate = new Date(viewReferenceDate);
                         startDate.setDate(viewReferenceDate.getDate() - dayOfWeek); // Go to Sunday
                         startDate.setHours(0, 0, 0, 0);

                         endDate = new Date(startDate);
                         endDate.setDate(startDate.getDate() + 6); // Saturday
                         endDate.setHours(23, 59, 59, 999);
                         break;

                     case 'daily':
                         startDate = new Date(viewReferenceDate);
                         endDate = new Date(viewReferenceDate);
                         break;

                     default:
                         startDate = new Date(viewReferenceDate);
                         endDate = new Date(viewReferenceDate);
                 }

                 return { startDate: startDate, endDate: endDate };
             }

             /**
              * Check if a date falls within a specified range (inclusive)
              * @param {Date} date - The date to check
              * @param {Date} startDate - Start of range
              * @param {Date} endDate - End of range
              * @returns {boolean} True if date is within range
              */
             function isDateInRange(date, startDate, endDate) {
                 if (!date) return false;

                 const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
                 const start = new Date(startDate.getFullYear(), startDate.getMonth(), startDate.getDate());
                 const end = new Date(endDate.getFullYear(), endDate.getMonth(), endDate.getDate());

                 return d >= start && d <= end;
             }

             /**
              * Update panel after navigation to show the first date in the visible range
              * This function is called after appointments are loaded to ensure data is available
              */
             function updatePanelAfterNavigation() {
                 // Only update panel for non-daily views
                 if (currentViewMode === 'daily') {
                     console.log('Skipping panel update - in daily view');
                     return;
                 }
                 const visibleRange = getVisibleDateRange();
                 // Always open the panel for the first date in the visible range
                 openDailyAppointmentPanel(visibleRange.startDate);
             }

             // Flag to track if panel update is pending after navigation
             let pendingPanelUpdate = false;

             /**
              * Navigate view forward or backward
              */
             function navigateView(direction) {
                 const amount = direction; // 1 or -1

                 switch(currentViewMode) {
                     case 'daily':
                         // Move by 1 day
                         viewReferenceDate.setDate(viewReferenceDate.getDate() + amount);
                         break;

                     case 'weekly-test':
                         // Move by 7 days (one week)
                         viewReferenceDate.setDate(viewReferenceDate.getDate() + (amount * 7));
                         break;

                     case 'monthly':
                         // Move by 1 month
                         viewReferenceDate.setDate(1);  // Normalize to first day to prevent rollover
                         viewReferenceDate.setMonth(viewReferenceDate.getMonth() + amount);
                         break;
                 }

                 // Recalculate range and refresh
                 applyViewMode(currentViewMode);

                 // Set flag to update panel after appointments are loaded
                 pendingPanelUpdate = true;
             }

             /**
              * ============================================================
              * DAILY APPOINTMENT PANEL FUNCTIONS
              * ============================================================
              */

             /**
              * Open the daily appointment panel for a specific date
              * @param {Date} date - The date to display appointments for
              */
             function openDailyAppointmentPanel(date) {
                 console.log('Opening panel for date:', date);

                 // Don't open panel in daily view
                 if (currentViewMode === 'daily') {
                     console.log('Skipping panel open - in daily view');
                     return;
                 }

                 selectedPanelDate = new Date(date);
                 isPanelOpen = true;

                 const panel = document.getElementById('dailyAppointmentPanel');
                 if (panel) {
                     panel.style.display = 'flex';
                     renderDailyAppointmentPanel(date);
                     updateSelectedDayIndicator(date);
                 }

                 // Add class to calendar wrapper for responsive adjustments
                 const calendarWrapper = document.querySelector('.calendar-wrapper');
                 if (calendarWrapper) {
                     calendarWrapper.classList.add('panel-open');
                 }
             }

             /**
              * Close the daily appointment panel
              */
             function closeDailyAppointmentPanel() {
                 console.log('Closing panel');

                 isPanelOpen = false;
                 selectedPanelDate = null;

                 const panel = document.getElementById('dailyAppointmentPanel');
                 if (panel) {
                     panel.style.display = 'none';
                 }

                 // Remove selected indicators from calendar
                 document.querySelectorAll('.monthly-day-cell.selected, .weekly-day-header.selected').forEach(el => {
                     el.classList.remove('selected');
                 });

                 // Remove class from calendar wrapper
                 const calendarWrapper = document.querySelector('.calendar-wrapper');
                 if (calendarWrapper) {
                     calendarWrapper.classList.remove('panel-open');
                 }
             }

             /**
              * Render appointments in the panel for a specific date
              * @param {Date} date - The date to display appointments for
              */
             function renderDailyAppointmentPanel(date) {
                 const dateStr = formatDateYYYYMMDD(date);
                 const dayAppointments = filterAppointmentsByDate(dateStr);

                 // Update panel header
                 const panelDateText = document.getElementById('panelDateText');
                 const panelAppointmentCount = document.getElementById('panelAppointmentCount');

                 if (panelDateText) {
                     panelDateText.textContent = formatDateForPanel(date);
                 }

                 if (panelAppointmentCount) {
                     // Exclude cancelled appointments from count
                     console.log('[PANEL COUNT DEBUG] Total day appointments:', dayAppointments.length);
                     console.log('[PANEL COUNT DEBUG] Cancelled appointments:', dayAppointments.filter(appt => appt.rescheduled === true || appt.rescheduled === 'T').map(appt => ({
                         id: appt.id,
                         title: appt.title,
                         rescheduled: appt.rescheduled,
                         rescheduledType: typeof appt.rescheduled
                     })));
                     const activeAppointments = dayAppointments.filter(appt => appt.rescheduled !== true && appt.rescheduled !== 'T' && appt.status !== 'CANCELLED');
                     console.log('[PANEL COUNT DEBUG] Active appointments after filter:', activeAppointments.length);
                     const count = activeAppointments.length;
                     panelAppointmentCount.textContent = count === 0 ? 'No appointments' :
                                                          count === 1 ? '1 appointment' :
                                                          count + ' appointments';
                 }

                 // Render appointment cards
                 const panelBody = document.getElementById('panelAppointmentsList');
                 if (panelBody) {
                     if (dayAppointments.length === 0) {
                         panelBody.innerHTML = '<div class="panel-empty-state"><p>No appointments scheduled</p></div>';
                     } else {
                         // Sort appointments by time
                         dayAppointments.sort((a, b) => {
                             const timeA = parseTimeToHour(a.startTime) || 0;
                             const timeB = parseTimeToHour(b.startTime) || 0;
                             return timeA - timeB;
                         });

                         let html = '';
                         dayAppointments.forEach(appt => {
                             html += createPanelAppointmentCard(appt);
                         });
                         panelBody.innerHTML = html;
                     }
                 }
             }

             /**
              * Create an appointment card for the panel
              * @param {Object} appt - Appointment data
              * @returns {string} HTML string for the appointment card
              */
             function createPanelAppointmentCard(appt) {
                 // Prepare appointment data for modal (same as monthly/weekly views)
                 const appointmentDataJson = JSON.stringify({
                     id: appt.id,
                     title: appt.title || 'Untitled',
                     date: formatDateForTable(appt.startDate),
                     startTime: appt.startTime || 'N/A',
                     endTime: appt.endTime || 'N/A',
                     location: appt.storeLocation || 'N/A',
                     employee: appt.employeeName || 'N/A',
                     organizer: appt.employeeName || 'N/A',
                     eventType: appt.eventType || 'N/A',
                     status: appt.status || 'N/A',
                     response: appt.response || 'N/A',
                     outcome: '',
                     createdDate: appt.createdDate || 'N/A',
                     owner: appt.ownerName || 'N/A',
                     markDone: appt.markDone || 'N/A',
                     message: appt.message || '',
                     interimNote: appt.interimNote || '',
                     company: appt.company || '',
                     companyText: appt.companyText || '',
                     contact: appt.contact || '',
                     contactText: appt.contactText || '',
                     transaction: appt.transaction || '',
                     transactionText: appt.transactionText || '',
                     supportCase: appt.supportCase || '',
                     supportCaseText: appt.supportCaseText || '',
                     customerCategory: appt.customerCategory || '',
                     customerCategoryText: appt.customerCategoryText || '',
                     probability: appt.probability || 0,
                     rescheduled: appt.rescheduled || false
                 });
                 const appointmentData = btoa(unescape(encodeURIComponent(appointmentDataJson)));

                 // Add cancelled class if appointment is rescheduled
                 const cancelledClass = (appt.rescheduled === true || appt.rescheduled === 'T') ? ' cancelled' : '';

                 // Build the card HTML with flowing layout
                 let html = '<div class="panel-appointment-card' + cancelledClass + '" ';
                 html += 'data-appointment="' + appointmentData + '" ';
                 html += 'onclick="showAppointmentDetailsFromData(this)">';

                 // Header: Time and Event Type (remove AM/PM)
                 html += '<div class="panel-appt-header">';
                 const startTimeNoAmPm = appt.startTime ? appt.startTime.replace(/\s*(AM|PM|am|pm)\s*$/i, '').trim() : 'N/A';
                 const endTimeNoAmPm = appt.endTime ? appt.endTime.replace(/\s*(AM|PM|am|pm)\s*$/i, '').trim() : '';
                 const timeRange = startTimeNoAmPm + (endTimeNoAmPm ? ' - ' + endTimeNoAmPm : '');
                 html += '<span class="panel-appt-time">' + stripHTML(timeRange) + '</span>';
                 if (appt.eventType) {
                     html += '<span class="panel-appt-type-badge">' + stripHTML(appt.eventType) + '</span>';
                 }
                 html += '</div>';

                 // Meta: Salesperson and Location
                 html += '<div class="panel-appt-meta">';
                 html += '<span class="panel-appt-salesperson">' + stripHTML(appt.employeeName || 'N/A') + '</span>';
                 html += '<span class="panel-appt-location">' + stripHTML(appt.storeLocation || 'N/A') + '</span>';
                 html += '</div>';

                 // Customer Name
                 html += '<div class="panel-appt-customer">' + stripHTML(appt.title || 'Untitled') + '</div>';

                 html += '</div>'; // Close panel-appointment-card

                 return html;
             }

             /**
              * Filter appointments by a specific date
              * @param {string} dateStr - Date in YYYY-MM-DD format
              * @returns {Array} Array of appointments for that date
              */
             function filterAppointmentsByDate(dateStr) {
                 // Get active filter values
                 const selectedEmployee = getSelectedEmployee();
                 const selectedStores = getSelectedStores();
                 const selectedEventTypes = getSelectedEventTypes();

                 // Get appointments for this date
                 let dayAppointments = [];

                 // Use the global appointmentsByDate if available (monthly view)
                 if (appointmentsByDate && appointmentsByDate[dateStr]) {
                     dayAppointments = appointmentsByDate[dateStr];
                 }
                 // Otherwise filter from allAppointmentsData
                 else if (allAppointmentsData && allAppointmentsData.length > 0) {
                     dayAppointments = allAppointmentsData.filter(appt => {
                         const apptDate = parseDateLocal(appt.startDate);
                         const apptDateStr = formatDateYYYYMMDD(apptDate);
                         return apptDateStr === dateStr;
                     });
                 }

                 // Apply active filters to the day's appointments
                 return dayAppointments.filter(appt => {
                     // Filter by employee if selected
                     if (selectedEmployee && appt.organizer !== selectedEmployee) {
                         return false;
                     }

                     // Filter by store if any stores selected
                     if (selectedStores.length > 0) {
                         const apptStoreId = appt.storeLocationId ? appt.storeLocationId.toString() : '';
                         if (!selectedStores.includes(apptStoreId)) {
                             return false;
                         }
                     }

                     // Filter by event type if any types selected
                     if (selectedEventTypes.length > 0) {
                         const apptEventType = appt.eventTypeId ? appt.eventTypeId.toString() : '';
                         if (!selectedEventTypes.includes(apptEventType)) {
                             return false;
                         }
                     }

                     return true;  // Passes all filters
                 });
             }

             /**
              * Format date for panel header display
              * @param {Date} date - Date object
              * @returns {string} Formatted date string (e.g., "Thursday, Oct 9, 2025")
              */
             function formatDateForPanel(date) {
                 const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
                 const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

                 const dayName = days[date.getDay()];
                 const monthName = months[date.getMonth()];
                 const dayNum = date.getDate();
                 const year = date.getFullYear();

                 return dayName + ', ' + monthName + ' ' + dayNum + ', ' + year;
             }

             /**
              * Update visual indicator for selected day in calendar
              * @param {Date} date - Selected date
              */
             function updateSelectedDayIndicator(date) {
                 const dateStr = formatDateYYYYMMDD(date);

                 // Remove previous selection
                 document.querySelectorAll('.monthly-day-cell.selected, .weekly-day-header.selected').forEach(el => {
                     el.classList.remove('selected');
                 });

                 // Add selection to monthly view
                 const monthlyCell = document.querySelector('.monthly-day-cell[data-date="' + dateStr + '"]');
                 if (monthlyCell) {
                     monthlyCell.classList.add('selected');
                 }

                 // Add selection to weekly view (find the day header)
                 const weeklyHeaders = document.querySelectorAll('.weekly-day-header');
                 weeklyHeaders.forEach(header => {
                     // Check if this header corresponds to the selected date
                     // We'll need to compare based on the week structure
                     const headerIndex = Array.from(weeklyHeaders).indexOf(header);
                     const weekStart = parseDateLocal(document.getElementById('startDateFilter').value);
                     const headerDate = new Date(weekStart);
                     headerDate.setDate(weekStart.getDate() + headerIndex);

                     if (formatDateYYYYMMDD(headerDate) === dateStr) {
                         header.classList.add('selected');
                     }
                 });
             }

             function toggleDateRangePicker() {
                 console.log('Toggling date range picker...');
                 const dropdown = document.getElementById('dateRangePickerDropdown');
                 const isVisible = dropdown.style.display !== 'none';
                 
                 console.log('Current global state:', {
                     selectedStartDate: selectedStartDate,
                     selectedEndDate: selectedEndDate,
                     isSelectingRange: isSelectingRange
                 });
                 
                 if (isVisible) {
                     console.log('Closing dropdown');
                     dropdown.style.display = 'none';
                 } else {
                     console.log('Opening dropdown');
                     dropdown.style.display = 'block';
                     renderDualCalendar();
                 }
             }

             function previousMonth() {
                 currentCalendarDate.setDate(1);  // Prevent day rollover when month has fewer days
                 currentCalendarDate.setMonth(currentCalendarDate.getMonth() - 1);
                 renderDualCalendar();
             }

             function nextMonth() {
                 currentCalendarDate.setDate(1);  // Prevent day rollover when month has fewer days
                 currentCalendarDate.setMonth(currentCalendarDate.getMonth() + 1);
                 renderDualCalendar();
             }

             function renderDualCalendar() {
                 console.log('Rendering dual calendar...');
                 const monthNames = ["January", "February", "March", "April", "May", "June",
                     "July", "August", "September", "October", "November", "December"];
                 
                 // First month
                 const firstMonth = new Date(currentCalendarDate);
                 const month1Element = document.getElementById('currentMonth1');
                 if (month1Element) {
                     month1Element.textContent = monthNames[firstMonth.getMonth()] + ' ' + firstMonth.getFullYear();
                 }
                 renderMonth(firstMonth, 'calendarDays1');
                 
                 // Second month (next month)
                 const secondMonth = new Date(currentCalendarDate);
                 secondMonth.setDate(1);  // Normalize to first day before changing month to prevent rollover
                 secondMonth.setMonth(secondMonth.getMonth() + 1);
                 const month2Element = document.getElementById('currentMonth2');
                 if (month2Element) {
                     month2Element.textContent = monthNames[secondMonth.getMonth()] + ' ' + secondMonth.getFullYear();
                 }
                 renderMonth(secondMonth, 'calendarDays2');
             }

             function renderMonth(monthDate, containerId) {
                 console.log('Rendering month for container:', containerId);
                 const calendarDays = document.getElementById(containerId);
                 if (!calendarDays) {
                     console.error('Calendar container not found:', containerId);
                     return;
                 }
                 
                 calendarDays.innerHTML = '';
                 
                 const firstDay = new Date(monthDate.getFullYear(), monthDate.getMonth(), 1);
                 const startDate = new Date(firstDay);
                 startDate.setDate(startDate.getDate() - firstDay.getDay());
                 
                 const today = new Date();
                 today.setHours(0, 0, 0, 0);
                 
                 let selectedCount = 0;
                 let rangeCount = 0;
                 
                 for (let i = 0; i < 42; i++) {
                     const date = new Date(startDate);
                     date.setDate(startDate.getDate() + i);
                     
                     const dayElement = document.createElement('button');
                     dayElement.type = 'button';
                     dayElement.className = 'calendar-day';
                     dayElement.textContent = date.getDate();
                     
                     // Add classes for styling
                     if (date.getMonth() !== monthDate.getMonth()) {
                         dayElement.classList.add('other-month');
                     }
                     
                     if (date.getTime() === today.getTime()) {
                         dayElement.classList.add('today');
                     }
                     
                     // Handle range selection styling
                     if (selectedStartDate && selectedEndDate) {
                         const dateTime = date.getTime();
                         const startTime = selectedStartDate.getTime();
                         const endTime = selectedEndDate.getTime();
                         
                         if (dateTime === startTime) {
                             dayElement.classList.add('range-start');
                             selectedCount++;
                         } else if (dateTime === endTime) {
                             dayElement.classList.add('range-end');
                             selectedCount++;
                         } else if (dateTime > startTime && dateTime < endTime) {
                             dayElement.classList.add('in-range');
                             rangeCount++;
                         }
                     } else if (selectedStartDate && date.getTime() === selectedStartDate.getTime()) {
                         dayElement.classList.add('selected');
                         selectedCount++;
                     }
                     
                     // Only add click handler for current month days
                     if (date.getMonth() === monthDate.getMonth()) {
                         dayElement.onclick = function() { selectDate(date); };
                     }
                     
                     calendarDays.appendChild(dayElement);
                 }
                 
                 console.log('Month rendered - Selected days:', selectedCount, 'Range days:', rangeCount);
             }

             function selectDate(date) {
                 console.log('=== SELECT DATE START ===');
                 console.log('Selected date:', date);
                 console.log('Current state - Start:', selectedStartDate, 'End:', selectedEndDate);
                 
                 try {
                     if (!selectedStartDate || (selectedStartDate && selectedEndDate)) {
                         // Start new selection
                         console.log('Branch: Starting new selection');
                         selectedStartDate = new Date(date);
                         selectedEndDate = null;
                         isSelectingRange = true;
                         console.log('Started new selection:', selectedStartDate);
                     } else if (selectedStartDate && !selectedEndDate) {
                         // Complete the range
                         console.log('Branch: Completing range');
                         if (date.getTime() < selectedStartDate.getTime()) {
                             selectedEndDate = selectedStartDate;
                             selectedStartDate = new Date(date);
                         } else {
                             selectedEndDate = new Date(date);
                         }
                         isSelectingRange = false;
                         console.log('Completed range:', selectedStartDate, 'to', selectedEndDate);
                         updateDateRangeInput();

                         // Auto-close the date range picker dropdown
                         const dropdown = document.getElementById('dateRangePickerDropdown');
                         if (dropdown) {
                             dropdown.style.display = 'none';
                         }

                         // Trigger filtering after closing dropdown
                         setTimeout(() => {
                             console.log('Filtering appointments after date range selection...');
                             // Update viewReferenceDate to match the selected start date
                             viewReferenceDate = new Date(selectedStartDate);
                             // Set flag to update panel to first date in range
                             pendingPanelUpdate = true;
                             filterAppointments();
                         }, 100);
                     }
                     
                     console.log('About to re-render calendar...');
                     renderDualCalendar();
                     console.log('=== SELECT DATE END ===');
                 } catch (error) {
                     console.error('Error in selectDate:', error);
                 }
             }

             function updateDateRangeInput() {
                 console.log('Updating date range input...');
                 const formatDate = (date) => {
                     const month = String(date.getMonth() + 1).padStart(2, '0');
                     const day = String(date.getDate()).padStart(2, '0');
                     const year = date.getFullYear();
                     return month + '/' + day + '/' + year;
                 };

                 const formatForInput = (date) => {
                     const month = String(date.getMonth() + 1).padStart(2, '0');
                     const day = String(date.getDate()).padStart(2, '0');
                     const year = date.getFullYear();
                     return year + '-' + month + '-' + day;
                 };

                 const dateRangeFilter = document.getElementById('dateRangeFilter');
                 const startDateFilter = document.getElementById('startDateFilter');
                 const endDateFilter = document.getElementById('endDateFilter');
                 
                 if (!dateRangeFilter || !startDateFilter || !endDateFilter) {
                     console.error('Date input elements not found!');
                     return;
                 }

                 if (selectedStartDate && selectedEndDate) {
                     const displayValue = formatDate(selectedStartDate) + ' - ' + formatDate(selectedEndDate);
                     dateRangeFilter.value = displayValue;
                     startDateFilter.value = formatForInput(selectedStartDate);
                     endDateFilter.value = formatForInput(selectedEndDate);
                     console.log('Updated range input:', displayValue);
                 } else if (selectedStartDate) {
                     const displayValue = formatDate(selectedStartDate);
                     dateRangeFilter.value = displayValue;
                     startDateFilter.value = formatForInput(selectedStartDate);
                     endDateFilter.value = formatForInput(selectedStartDate);
                     console.log('Updated single date input:', displayValue);
                 }
             }

