             // Debounce function to limit rapid function calls
             function debounce(func, wait) {
                 let timeout;
                 return function executedFunction(...args) {
                     const later = () => {
                         clearTimeout(timeout);
                         func(...args);
                     };
                     clearTimeout(timeout);
                     timeout = setTimeout(later, wait);
                 };
             }
             
             // Update filter visual state
             function updateFilterVisualState() {
                 const dateRangeFilter = document.getElementById('dateRangeFilter');
                 const storeFilter = document.getElementById('storeFilter');
                 const employeeFilter = document.getElementById('employeeFilter');
                 const eventTypeFilter = document.getElementById('eventTypeFilter');
                 
                 // Handle date range filter
                 if (dateRangeFilter) {
                     if (dateRangeFilter.value && dateRangeFilter.value !== '') {
                         dateRangeFilter.style.borderColor = '#3b82f6';
                         dateRangeFilter.style.backgroundColor = '#f0f9ff';
                     } else {
                         dateRangeFilter.style.borderColor = '#d1d5db';
                         dateRangeFilter.style.backgroundColor = 'white';
                     }
                 }
                 
                 // Handle store multiselect filter
                 if (storeFilter) {
                     const storeCheckboxes = document.querySelectorAll('#storeDropdown input[type="checkbox"]:not(#selectAllStores)');
                     const hasStoreSelection = Array.from(storeCheckboxes).some(cb => cb.checked);
                     
                     if (hasStoreSelection) {
                         storeFilter.classList.add('has-selection');
                     } else {
                         storeFilter.classList.remove('has-selection');
                     }
                 }
                 
                 // Handle employee filter
                 if (employeeFilter) {
                     if (employeeFilter.value && employeeFilter.value !== '') {
                         employeeFilter.style.borderColor = '#3b82f6';
                         employeeFilter.style.backgroundColor = '#f0f9ff';
                     } else {
                         employeeFilter.style.borderColor = '#d1d5db';
                         employeeFilter.style.backgroundColor = 'white';
                     }
                 }
                 
                 // Handle event type multiselect filter
                 if (eventTypeFilter) {
                     const eventTypeCheckboxes = document.querySelectorAll('#eventTypeDropdown input[type="checkbox"]:not(#selectAllEventTypes)');
                     const hasEventTypeSelection = Array.from(eventTypeCheckboxes).some(cb => cb.checked);
                     
                     if (hasEventTypeSelection) {
                         eventTypeFilter.classList.add('has-selection');
                     } else {
                         eventTypeFilter.classList.remove('has-selection');
                     }
                 }
             }
             
