              function changeEventType() {
                  // Check if we're in non-customer workflow (no customer selected and inline buttons visible)
                  // In this case, user can just click a different inline button - no action needed
                  if (!selectedCustomer) {
                      var buttonsContainer = document.getElementById('nonCustomerEventTypeButtons');
                      if (buttonsContainer && buttonsContainer.style.display === 'flex') {
                          console.log('In non-customer workflow - user can click different inline button');
                          return; // User can just click a different button
                      }
                  }

                  // Hide non-customer buttons when going back (in case they were visible)
                  hideNonCustomerEventTypeButtons();

                  // Clear appointment modal selections when going back to event type selection
                  // But preserve the selected customer since we're just going back in the flow
                  clearAppointmentModalSelectionsPreserveCustomer();

                  // Close appointment modal
                  document.getElementById('addAppointmentModal').style.display = 'none';
                 // Open event type selection modal
                 const eventModal = document.getElementById('eventTypeSelectionModal');
                 eventModal.style.display = 'block';

                 // Check if we're in URL parameter mode and apply appropriate styling
                 const urlParams = new URLSearchParams(window.location.search);
                 const hasUrlParams = urlParams.has('customerid') || urlParams.has('estimateid') || urlParams.has('salesorderid') || urlParams.has('taskid');

                 if (hasUrlParams) {
                     eventModal.classList.add('url-parameter-mode');
                     eventModal.classList.remove('customer-search-only');
                 }

                 // Update customer info in event type modal
                 updateEventTypeModalCustomerInfo();

                 // Initialize event type buttons for this modal
                 initializeEventTypeSelectionButtons();
             }

             // Removed - using enhanced version below

            // Function to update selected customer info in appointment modal
            function updateSelectedCustomerInfo(customer) {
                const customerNameEl = document.getElementById('selectedCustomerName');
                const customerEmailEl = document.getElementById('selectedCustomerEmail');
                const customerPhoneEl = document.getElementById('selectedCustomerPhone');
                const customerAddressEl = document.getElementById('selectedCustomerAddress');

                if (customerNameEl) {
                    // Create hyperlink to customer record
                    const customerName = customer.displayName || customer.name || 'Unknown Customer';
                    const customerUrl = '${baseUrl}.app.netsuite.com/app/common/entity/custjob.nl?id=' + customer.id + '&compid=${companyId}';
                    customerNameEl.innerHTML = '<a href="' + customerUrl + '" target="_blank" style="color: #3b82f6; text-decoration: none;">' + customerName + '</a>';
                }
                if (customerEmailEl) {
                    customerEmailEl.textContent = customer.email || '';
                    customerEmailEl.style.display = customer.email ? 'block' : 'none';
                }
                if (customerPhoneEl) {
                    customerPhoneEl.textContent = customer.phone || '';
                    customerPhoneEl.style.display = customer.phone ? 'block' : 'none';
                }
                if (customerAddressEl) {
                    // Build full address display
                    let addressParts = [];
                    if (customer.defaultaddress) addressParts.push(customer.defaultaddress);
                    const fullAddress = addressParts.join(', ');

                    customerAddressEl.textContent = fullAddress;
                    customerAddressEl.style.display = fullAddress ? 'block' : 'none';
                }
            }

