             function copyCustomerInfo() {
                 const customerElement = document.getElementById('modal-customer');
                 if (!customerElement) {
                     console.error('Customer element not found');
                     return;
                 }

                 const customerId = customerElement.getAttribute('data-customer-id');
                 const customerLink = customerElement.querySelector('a');
                 const customerName = customerLink ? customerLink.textContent : customerElement.textContent;

                 if (!customerId || customerName === 'N/A' || customerName === '-') {
                     console.log('No customer information to copy');
                     return;
                 }

                 const textToCopy = customerId + ' ' + customerName;

                 navigator.clipboard.writeText(textToCopy).then(function() {
                     console.log('Customer info copied:', textToCopy);

                     const button = document.querySelector('.btn-copy-customer');
                     const originalHTML = button.innerHTML;

                     button.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>';
                     button.style.background = '#10b981';
                     button.style.borderColor = '#10b981';
                     button.querySelector('svg').style.color = 'white';

                     setTimeout(function() {
                         button.innerHTML = originalHTML;
                         button.style.background = '';
                         button.style.borderColor = '';
                     }, 1500);
                 }).catch(function(err) {
                     console.error('Failed to copy customer info:', err);
                     alert('Failed to copy customer information');
                 });
             }

