            /**
             * Cancels an appointment by setting custevent_rescheduled checkbox to true
             * and appending a cancellation message. Cancelled appointments do not block time slots.
             */
            function cancelAppointment() {
                // Validate currentAppointmentId exists
                if (!currentAppointmentId) {
                    alert('No appointment selected');
                    return;
                }

                // Confirm cancellation with user
                if (!confirm('Are you sure you want to cancel this appointment? This action cannot be undone.')) {
                    return;
                }

                // Make AJAX POST request
                const xhr = new XMLHttpRequest();
                xhr.open('POST', window.location.href, true);
                xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');

                xhr.onreadystatechange = function() {
                    if (xhr.readyState === 4) {
                        if (xhr.status === 200) {
                            try {
                                const response = JSON.parse(xhr.responseText);
                                if (response.success) {
                                    alert('Appointment cancelled successfully');
                                    closeAppointmentDetailModal();
                                    // Reload page to refresh calendar view
                                    location.reload();
                                } else {
                                    alert('Error cancelling appointment: ' + response.error);
                                }
                            } catch (e) {
                                alert('Error parsing server response');
                                console.error('Parse error:', e);
                            }
                        } else {
                            alert('Error cancelling appointment. Please try again.');
                            console.error('HTTP error:', xhr.status);
                        }
                    }
                };

                xhr.send('action=cancelAppointment&appointmentId=' + encodeURIComponent(currentAppointmentId));
            }

            /**
             * Opens the Add Appointment Modal in duplicate mode with all fields pre-populated
             * from the currently displayed appointment in the Appointment Details Modal.
             *
             * Workflow:
             * 1. Capture all appointment data from Appointment Details Modal
             * 2. Store in duplicateAppointmentData global variable
             * 3. Close Appointment Details Modal
             * 4. Open Add Appointment Modal (which will detect duplicate mode)
             * 5. Pre-populate all fields except date/time
             */
            function openDuplicateAppointmentModal() {
                console.log('Opening duplicate appointment modal for event:', currentAppointmentId);

                if (!currentAppointmentId) {
                    console.error('No current appointment ID found');
                    alert('Error: No appointment selected for duplication');
                    return;
                }

                try {
                    // Capture appointment data from the Appointment Details Modal
                    duplicateAppointmentData = {
                        appointmentId: currentAppointmentId,

                        // Customer information
                        customerId: null,  // Will be extracted from company link
                        customerName: null,
                        customerEmail: null,
                        customerPhone: null,
                        customerAddress: null,

                        // Event details
                        eventTypeId: null,  // Will be extracted from event type text or data attribute
                        eventTypeName: document.getElementById('modal-event-type')?.textContent || null,

                        // Transaction (if exists)
                        transactionId: null,  // Will be extracted from created-from-record link
                        transactionText: null,
                        transactionType: null,

                        // Salesperson (use owner, not organizer - owner is the actual assignee)
                        salespersonId: document.getElementById('modal-owner')?.getAttribute('data-owner-id') || null,
                        salespersonName: document.getElementById('modal-owner')?.textContent || null,

                        // Store and scheduling
                        storeLocation: document.getElementById('modal-store')?.textContent || null,
                        duration: null,  // Will be parsed from duration text

                        // Date and time from original appointment
                        originalDate: document.getElementById('modal-date')?.textContent?.trim() || null,
                        originalTime: document.getElementById('modal-time')?.textContent?.trim() || null,

                        // Appointment details
                        appointmentDetails: document.getElementById('modal-message')?.textContent?.trim() || null
                    };

                    // Extract customer ID from company link (if exists)
                    const customerElement = document.getElementById('modal-customer');
                    if (customerElement) {
                        const customerLink = customerElement.querySelector('a');
                        if (customerLink) {
                            const href = customerLink.getAttribute('href');
                            // Extract ID from URL like ".../custjob.nl?id=12345"
                            const idMatch = href.match(/id=(\\d+)/);
                            if (idMatch) {
                                duplicateAppointmentData.customerId = idMatch[1];
                            }
                            duplicateAppointmentData.customerName = customerLink.textContent.trim();
                        } else {
                            duplicateAppointmentData.customerName = customerElement.textContent.trim();
                        }
                    }

                    // Extract transaction ID from created-from-record link (if exists)
                    const transactionElement = document.getElementById('modal-created-from-record');
                    if (transactionElement) {
                        const transactionLink = transactionElement.querySelector('a');
                        if (transactionLink) {
                            const href = transactionLink.getAttribute('href');
                            // Extract ID from URL like ".../transaction.nl?id=12345"
                            const idMatch = href.match(/id=(\\d+)/);
                            if (idMatch) {
                                duplicateAppointmentData.transactionId = idMatch[1];
                            }
                            duplicateAppointmentData.transactionText = transactionLink.textContent.trim();

                            // Determine transaction type from created-from-type
                            const typeElement = document.getElementById('modal-created-from-type');
                            if (typeElement) {
                                const typeText = typeElement.textContent.trim().toLowerCase();
                                if (typeText.includes('estimate')) {
                                    duplicateAppointmentData.transactionType = 'estimate';
                                } else if (typeText.includes('sales order')) {
                                    duplicateAppointmentData.transactionType = 'salesorder';
                                } else if (typeText.includes('opportunity') || typeText.includes('rfq')) {
                                    duplicateAppointmentData.transactionType = 'opportunity';
                                }
                            }
                        }
                    }

                    // Parse duration from text like "60 mins" or "N/A"
                    const durationElement = document.getElementById('modal-duration');
                    if (durationElement) {
                        const durationText = durationElement.textContent.trim();
                        const durationMatch = durationText.match(/(\\d+)\\s*mins?/);
                        if (durationMatch) {
                            duplicateAppointmentData.duration = parseInt(durationMatch[1]);
                        }
                    }

                    // Extract event type ID (will need to lookup from event type name or store in data attribute)
                    // For now, we will need to find the event type ID during pre-population by matching event type name

                    console.log('Captured duplicate appointment data:', duplicateAppointmentData);
                    console.log('Date captured:', duplicateAppointmentData.originalDate);
                    console.log('Time captured:', duplicateAppointmentData.originalTime);
                    console.log('Owner/Salesperson ID captured:', duplicateAppointmentData.salespersonId);
                    console.log('Owner/Salesperson Name captured:', duplicateAppointmentData.salespersonName);
                    console.log('Appointment details captured:', duplicateAppointmentData.appointmentDetails);

                    // Close Appointment Details Modal
                    closeAppointmentDetailModal();

                    // Small delay to ensure modal close animation completes
                    setTimeout(function() {
                        // Open Add Appointment Modal (which will detect duplicate mode and pre-populate)
                        openAddAppointmentModal();
                    }, 100);

                } catch (error) {
                    console.error('Error opening duplicate appointment modal:', error);
                    alert('Error preparing duplicate appointment. Please try again.');
                    duplicateAppointmentData = null;
                }
            }

