             // Interim Note Edit Functions
             function toggleInterimNoteEdit() {
                 const displayElement = document.getElementById('modal-interim-note');
                 const editElement = document.getElementById('modal-interim-note-edit');
                 const actionsElement = document.getElementById('interim-note-actions');
                 const editButton = document.getElementById('edit-interim-note-btn');

                 // Switch to edit mode
                 displayElement.style.display = 'none';
                 editElement.style.display = 'block';
                 actionsElement.style.display = 'flex';
                 editButton.style.display = 'none';

                 // Set the current value in the textarea
                 const currentText = displayElement.textContent;
                 editElement.value = currentText === 'No interim note' || currentText === 'N/A' ? '' : currentText;
                 
                 // Focus the textarea
                 editElement.focus();
             }

             function cancelInterimNoteEdit() {
                 const displayElement = document.getElementById('modal-interim-note');
                 const editElement = document.getElementById('modal-interim-note-edit');
                 const actionsElement = document.getElementById('interim-note-actions');
                 const editButton = document.getElementById('edit-interim-note-btn');

                 // Switch back to display mode
                 displayElement.style.display = 'block';
                 editElement.style.display = 'none';
                 actionsElement.style.display = 'none';
                 editButton.style.display = 'inline-block';
             }

             function updateTableInterimNote(appointmentId, newNote) {
                 // Find all appointment rows and update the interim note display
                 const appointmentRows = document.querySelectorAll('.appointment-row');
                 appointmentRows.forEach(row => {
                     const onClickAttr = row.getAttribute('onclick');
                     if (onClickAttr && onClickAttr.includes('showAppointmentDetails(' + appointmentId + ',')) {
                         const interimNoteElement = row.querySelector('.interim-note .detail-primary');
                         if (interimNoteElement) {
                             interimNoteElement.textContent = newNote || 'N/A';
                         }
                     }
                 });
             }

             function saveInterimNote() {
                 const editElement = document.getElementById('modal-interim-note-edit');
                 const newNote = editElement.value.trim();

                 if (!currentAppointmentId) {
                     alert('No appointment selected');
                     return;
                 }

                 // Show loading state
                 const saveButton = document.querySelector('#interim-note-actions .btn-primary');
                 const originalText = saveButton.textContent;
                 saveButton.textContent = 'Saving...';
                 saveButton.disabled = true;

                 // Make AJAX call to save the note
                 const xhr = new XMLHttpRequest();
                 xhr.open('POST', window.location.href, true);
                 xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
                 
                 xhr.onreadystatechange = function() {
                     if (xhr.readyState === 4) {
                         saveButton.textContent = originalText;
                         saveButton.disabled = false;
                         
                         if (xhr.status === 200) {
                             try {
                                 const response = JSON.parse(xhr.responseText);
                                 if (response.success) {
                                     // Update the display
                                     const displayElement = document.getElementById('modal-interim-note');
                                     displayElement.textContent = newNote || 'No interim note';
                                     
                                     // Switch back to display mode
                                     cancelInterimNoteEdit();
                                     
                                     
                                     // Update the table display if visible
                                     updateTableInterimNote(currentAppointmentId, newNote);
                                     
                                     // Optionally refresh the page to show updated data
                                     // window.location.reload();
                                 } else {
                                     alert('Error saving interim note: ' + (response.error || 'Unknown error'));
                                 }
                             } catch (e) {
                                 alert('Error parsing response: ' + e.message);
                             }
                         } else {
                             alert('Error saving interim note. Please try again.');
                         }
                     }
                 };

                 const params = 'action=saveInterimNote&appointmentId=' + encodeURIComponent(currentAppointmentId) + 
                               '&interimNote=' + encodeURIComponent(newNote);
                 xhr.send(params);
             }

