            function getModeDisplayName(mode, recordData) {
                switch (mode) {
                    case 'rfq':
                        return 'RFQ Opportunity';
                    case 'estimate':
                        return 'Estimate';
                    case 'salesorder':
                        return 'Sales Order';
                    case 'customer':
                        return 'Customer Orders & Estimates';
                    default:
                        return 'Transaction';
                }
            }

            function getRecordTypeBadge(mode, recordData) {
                switch (mode) {
                    case 'rfq':
                        return '<span class="record-type-badge opportunity">RFQ ' + recordData.tranid + '</span>';
                    case 'estimate':
                        return '<span class="record-type-badge estimate">' + recordData.tranid + '</span>';
                    case 'salesorder':
                        return '<span class="record-type-badge salesorder">' + recordData.tranid + '</span>';
                    default:
                        return '<span class="record-type-badge">' + mode.toUpperCase() + '</span>';
                }
            }

            function initializeAppointmentModal() {
                // Initialize calendar when modal opens
                const modal = document.getElementById('addAppointmentModal');
                if (modal) {
                    // Enhanced modal closing logic - track mousedown and mouseup
                    let appointmentModalMouseDownTarget = null;

                    modal.addEventListener('mousedown', function(e) {
                        if (e.target === modal) {
                            appointmentModalMouseDownTarget = e.target;
                        }
                    });

                    modal.addEventListener('mouseup', function(e) {
                        // Prevent closing on backdrop click in customer search only mode
                        if (typeof customerSearchOnly !== 'undefined' && customerSearchOnly) {
                            appointmentModalMouseDownTarget = null;
                            return;
                        }

                        if (e.target === modal && appointmentModalMouseDownTarget === e.target) {
                            closeAddAppointmentModal();
                        }
                        appointmentModalMouseDownTarget = null;
                    });
                }
                
                // Initialize order details modal click-outside-to-close functionality
                const orderDetailsModal = document.getElementById('orderDetailsModal');
                if (orderDetailsModal) {
                    let orderDetailsModalMouseDownTarget = null;
                    
                    orderDetailsModal.addEventListener('mousedown', function(e) {
                        if (e.target === orderDetailsModal) {
                            orderDetailsModalMouseDownTarget = e.target;
                        }
                    });
                    
                    orderDetailsModal.addEventListener('mouseup', function(e) {
                        if (e.target === orderDetailsModal && orderDetailsModalMouseDownTarget === e.target) {
                            closeOrderDetailsModal();
                        }
                        orderDetailsModalMouseDownTarget = null;
                    });
                }

                // Initialize calendar navigation
                const prevButton = document.getElementById('prevMonth');
                const nextButton = document.getElementById('nextMonth');
                
                if (prevButton) {
                    prevButton.addEventListener('click', function() {
                        appointmentModalCurrentDate.setDate(1);  // Normalize to first day to prevent rollover
                        appointmentModalCurrentDate.setMonth(appointmentModalCurrentDate.getMonth() - 1);
                        renderCalendar();
                    });
                }

                if (nextButton) {
                    nextButton.addEventListener('click', function() {
                        appointmentModalCurrentDate.setDate(1);  // Normalize to first day to prevent rollover
                        appointmentModalCurrentDate.setMonth(appointmentModalCurrentDate.getMonth() + 1);
                        renderCalendar();
                    });
                }

                // Initialize time slot selection
                initializeTimeSlots();

                // Initialize store location selection
                initializeStoreLocations();
                initializeEventTypes();


            }

            // Store hours cache for calendar
            let calendarStoreHoursCache = {};
            
            /**
             * Fetch store hours from NetSuite for calendar display
             * @param {string} location - Store location
             * @param {Date} startDate - Start date
             * @param {Date} endDate - End date
             * @returns {Promise} Promise resolving to store hours array
             */
            function fetchStoreHoursForCalendar(location, startDate, endDate) {
                const cacheKey = location + '_' + startDate.toISOString() + '_' + endDate.toISOString();
                
                // Check cache first
                if (calendarStoreHoursCache[cacheKey]) {
                    return Promise.resolve(calendarStoreHoursCache[cacheKey]);
                }
                
                // Format dates for API
                const formatDate = (date) => {
                    return (date.getMonth() + 1) + '/' + date.getDate() + '/' + date.getFullYear();
                };
                
                return fetch(window.location.href, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        action: 'getStoreHours',
                        location: location,
                        startDate: formatDate(startDate),
                        endDate: formatDate(endDate)
                    })
                })
                .then(response => response.json())
                .then(data => {
                    if (data.success) {
                        // Cache the result
                        calendarStoreHoursCache[cacheKey] = data.storeHours;
                        return data.storeHours;
                    } else {
                        console.error('Failed to fetch store hours:', data.error);
                        return [];
                    }
                })
                .catch(error => {
                    console.error('Error fetching store hours:', error);
                    return [];
                });
            }
            
            function renderCalendar() {
                const calendarDays = document.getElementById('calendarDays');
                const monthYearElement = document.getElementById('calendarMonthYear');
                
                if (!calendarDays || !monthYearElement) return;

                // Update month/year display
                const monthNames = [
                    'January', 'February', 'March', 'April', 'May', 'June',
                    'July', 'August', 'September', 'October', 'November', 'December'
                ];
                monthYearElement.textContent = monthNames[appointmentModalCurrentDate.getMonth()] + ' ' + appointmentModalCurrentDate.getFullYear();

                // Clear existing days
                calendarDays.innerHTML = '';

                // Get first day of month and number of days
                const firstDay = new Date(appointmentModalCurrentDate.getFullYear(), appointmentModalCurrentDate.getMonth(), 1);
                const lastDay = new Date(appointmentModalCurrentDate.getFullYear(), appointmentModalCurrentDate.getMonth() + 1, 0);
                const startDate = new Date(firstDay);
                startDate.setDate(startDate.getDate() - firstDay.getDay());
                
                // Get the selected store location
                const selectedLocation = getSelectedStoreLocation();
                
                // Pre-load appointments for the entire visible month (batch optimization)
                const monthStartStr = (firstDay.getMonth() + 1) + '/' + firstDay.getDate() + '/' + firstDay.getFullYear();
                const monthEndStr = (lastDay.getMonth() + 1) + '/' + lastDay.getDate() + '/' + lastDay.getFullYear();
                
                // Pre-load appointments for the month to improve time slot loading performance
                getAppointmentsForDateRange(monthStartStr, monthEndStr, selectedSalespersonId, selectedStore ? [selectedStore] : [])
                    .then(data => {
                        console.log('Pre-loaded appointments for month:', monthStartStr, 'to', monthEndStr, data);
                    })
                    .catch(error => {
                        console.error('Error pre-loading appointments for month:', error);
                    });
                
                // Fetch store hours for the displayed month if location is selected
                if (selectedLocation) {
                    const monthStart = new Date(firstDay);
                    const monthEnd = new Date(lastDay);
                    
                    fetchStoreHoursForCalendar(selectedLocation, monthStart, monthEnd).then(storeHoursArray => {
                        // Create a map for quick lookup
                        const storeHoursMap = {};
                        storeHoursArray.forEach(hours => {
                            storeHoursMap[hours.date] = hours;
                        });
                        
                        // Update calendar days with store hours info
                        const dayButtons = calendarDays.querySelectorAll('.calendar-day');
                        dayButtons.forEach((button, index) => {
                            const day = new Date(startDate);
                            day.setDate(startDate.getDate() + index);
                            
                            const dateStr = (day.getMonth() + 1) + '/' + day.getDate() + '/' + day.getFullYear();
                            const storeHours = storeHoursMap[dateStr];
                            
                            if (storeHours) {
                                // Store is closed - check multiple variations and isClosed flag
                                if (storeHours.status === '2' || storeHours.status === 2 || storeHours.isClosed === true) { // NetSuite Custom List: Closed = ID 2
                                    button.disabled = true;
                                    button.style.backgroundColor = '#fee2e2';
                                    button.style.color = '#991b1b';
                                    button.title = storeHours.specialLabel || 'Store Closed';
                                    button.style.cursor = 'not-allowed';
                                }
                                // Special hours (holiday, etc.)
                                else if (storeHours.isSpecial) {
                                    button.style.backgroundColor = '#fef3c7';
                                    button.style.color = '#92400e';
                                    button.title = storeHours.specialLabel + ' (' + storeHours.openTime + ' - ' + storeHours.closeTime + ')';
                                }
                                // Regular hours
                                else {
                                    button.title = 'Open: ' + storeHours.openTime + ' - ' + storeHours.closeTime;
                                }
                            }
                        });
                    });
                }

                // Create 42 days (6 weeks)
                for (let i = 0; i < 42; i++) {
                    const day = new Date(startDate);
                    day.setDate(startDate.getDate() + i);
                    
                    const dayButton = document.createElement('button');
                    dayButton.type = 'button';
                    dayButton.className = 'calendar-day';
                    dayButton.textContent = day.getDate();

                    // Add classes for styling
                    if (day.getMonth() !== appointmentModalCurrentDate.getMonth()) {
                        dayButton.classList.add('other-month');
                    }

                    // Mark today
                    const today = new Date();
                    if (day.toDateString() === today.toDateString()) {
                        dayButton.classList.add('today');
                    }

                    // Mark selected date
                    if (appointmentModalSelectedDate && day.toDateString() === appointmentModalSelectedDate.toDateString()) {
                        dayButton.classList.add('selected');
                    }

                    // Disable past dates (except today)
                    if (day < today && day.toDateString() !== today.toDateString()) {
                        dayButton.disabled = true;
                    }

                    // Add click handler
                    dayButton.addEventListener('click', function() {
                        if (!this.disabled) {
                            selectAppointmentDate(day);
                        }
                    });

                    calendarDays.appendChild(dayButton);
                }
            }

            // Appointment Modal Date Selection (separate from date range filter)
            function selectAppointmentDate(date) {
                console.log('Selecting appointment date:', date);
                
                // Set the selected date for the appointment modal
                appointmentModalSelectedDate = new Date(date);
                
                // Clear previously selected time when changing dates
                selectedTime = null;
                
                // Clear any selected time slot visually
                document.querySelectorAll('.time-slot.selected').forEach(slot => {
                    slot.classList.remove('selected');
                });
                
                // Re-render the calendar to show the selection
                renderCalendar();
                
                // Update time slots based on selected date and location
                const selectedStoreName = getStoreNameById(selectedStore);
                renderTimeSlots(appointmentModalSelectedDate, selectedStoreName, selectedSalespersonId);
                
                // Validate form after date change
                validateAppointmentForm();
                
                console.log('Appointment date selected:', appointmentModalSelectedDate);
            }

            // ============================================================================
            // TIME SLOT CONFIGURATION CONSTANTS
            // ============================================================================
            //
            // This section contains all time slot configuration constants and helper functions
            // for managing appointment scheduling across different store locations.
            //
            // FEATURES:
            // - Location-based time slot configuration
            // - User-specific availability management
            // - Custom time slot support
            // - Easy expansion for new locations
            // - Dynamic time slot generation based on operating hours
            //
            // USAGE EXAMPLES:
            // 1. Add a new location:
            //    addLocationConfig('New Store', { operatingHours: {...}, ... });
            //
            // 2. Update hours for existing location:
            //    updateLocationHours('Cabinet Direct', 1, { start: 8, end: 20, ... });
            //
            // 3. Set user availability:
            //    setUserAvailability('user123', { unavailableDays: [0, 6], ... });
            //
            // 4. Add custom time slots:
            //    addCustomTimeSlot('Cabinet Direct', 1, 8, 15, true); // 8:15 AM on Monday
            //
            // 5. Get available time slots:
            //    const slots = getAvailableTimeSlots(date, 'Cabinet Direct', 'user123');
            //
            // ============================================================================
            
            /**
             * Cache for store hours to avoid excessive NetSuite searches
             */
            const STORE_HOURS_CACHE = {};
            const CACHE_DURATION_MS = 30 * 60 * 1000; // 30 minutes cache duration
            
            /**
             * Map location names to NetSuite location IDs (client-side version)
             * @param {string} locationName - The location name
             * @returns {number|null} The location ID or null if not found
             */
            function getLocationIdByName(locationName) {
                const locationMap = {
                    'Cabinet Direct': 14,
                    'East Meadow': 4,
                    'Commack': 5,
                    'Copiague': 2,
                    'Franklin Square': 3,
                    'Patchogue': 17,
                    'Yaphank': 16,
                    'Holbrook': 1
                };
                
                return locationMap[locationName] || null;
            }
            
            /**
             * Fetch store hours from NetSuite for a specific location and date
             * @param {string} locationName - The store location name
             * @param {Date} date - The date to fetch hours for
             * @returns {Object|null} Store hours object or null if not found
             */
            function fetchStoreHoursFromNetSuite(locationName, date) {
                try {
                    const dateStr = formatDateForNetSuite(date);
                    const cacheKey = locationName + '_' + dateStr;
                    
                    // Get location ID from location name
                    const locationId = getLocationIdByName(locationName);
                    
                    /*                     
                    log.debug('Store Hours Search Debug (Client-Side)', {
                        locationName: locationName,
                        locationId: locationId,
                        date: date,
                        dateStr: dateStr,
                        cacheKey: cacheKey
                    }); */
                    
                    if (!locationId) {
                        log.error('Unknown location name (Client-Side)', { locationName: locationName });
                        return null;
                    }
                    
                    // Check cache first
                    if (STORE_HOURS_CACHE[cacheKey] && 
                        STORE_HOURS_CACHE[cacheKey].timestamp > Date.now() - CACHE_DURATION_MS) {
                        /*                         log.debug('Store Hours Cache Hit (Client-Side)', cacheKey); */
                        return STORE_HOURS_CACHE[cacheKey].data;
                    }
                    
                    // Search for store hours record using location ID
                    const storeHoursSearch = search.create({
                        type: 'customrecord_store_hours',
                        filters: [
                            ['custrecord_sc_location', 'anyof', locationId],
                            'AND',
                            ['custrecord_sc_date', 'on', dateStr]
                        ],
                        columns: [
                            'custrecord_sc_location',
                            'custrecord_sc_date',
                            'custrecord_sc_open_time',
                            'custrecord_sc_close_time',
                            'custrecord_sc_notes',
                            'custrecord_sc_status',
                            'custrecord_sc_is_special',
                            'custrecord_sc_special_label',
                            'custrecord_sc_is_day'
                        ]
                    });
                    
                    let storeHours = null;
                    let resultCount = 0;
                    
                    storeHoursSearch.run().each(function(result) {
                        resultCount++;
                        const status = result.getValue('custrecord_sc_status');
                        const openTime = result.getValue('custrecord_sc_open_time');
                        const closeTime = result.getValue('custrecord_sc_close_time');
                        const isSpecial = result.getValue('custrecord_sc_is_special');
                        const specialLabel = result.getValue('custrecord_sc_special_label');
                        const locationValue = result.getValue('custrecord_sc_location');
                        const dateValue = result.getValue('custrecord_sc_date');
                        
                        /*                         
                        log.debug('Store Hours Search Result (Client-Side)', {
                            resultNumber: resultCount,
                            locationValue: locationValue,
                            dateValue: dateValue,
                            status: status,
                            openTime: openTime,
                            closeTime: closeTime,
                            isSpecial: isSpecial,
                            specialLabel: specialLabel
                        }); */
                        
                        storeHours = {
                            location: locationValue,
                            date: dateValue,
                            openTime: openTime,
                            closeTime: closeTime,
                            status: status,
                            isClosed: status === '2' || status === 2, // NetSuite Custom List: Closed = ID 2
                            isSpecial: isSpecial === 'T' || isSpecial === true,
                            specialLabel: specialLabel || '',
                            notes: result.getValue('custrecord_sc_notes') || '',
                            dayOfWeek: result.getValue('custrecord_sc_is_day') || ''
                        };
                        
                        return false; // Only need first result
                    });
                    
                    /*                     
                    log.debug('Store Hours Search Complete (Client-Side)', {
                        locationName: locationName,
                        dateStr: dateStr,
                        totalResults: resultCount,
                        foundStoreHours: storeHours !== null
                    }); */
                    
                    // If no results found, let's see what locations exist in the system
                    if (resultCount === 0) {
                        try {
                            const locationSearch = search.create({
                                type: 'customrecord_store_hours',
                                filters: [],
                                columns: [
                                    search.createColumn({
                                        name: 'custrecord_sc_location',
                                        summary: search.Summary.GROUP
                                    })
                                ]
                            });
                            
                            let availableLocations = [];
                            locationSearch.run().each(function(result) {
                                availableLocations.push(result.getValue({name: 'custrecord_sc_location', summary: search.Summary.GROUP}));
                                return availableLocations.length < 20; // Limit to prevent too many logs
                            });
                            
                            /*                             
                            log.debug('Available Store Locations in NetSuite (Client-Side)', {
                                searchedLocation: locationName,
                                availableLocations: availableLocations
                            }); */
                        } catch (locationError) {
                            log.error('Error fetching available locations (Client-Side)', locationError.toString());
                        }
                    }
                    
                    // Cache the result
                    STORE_HOURS_CACHE[cacheKey] = {
                        data: storeHours,
                        timestamp: Date.now()
                    };
                    
                    return storeHours;
                } catch (error) {
                    log.error('Error fetching store hours', {
                        error: error.toString(),
                        location: locationName,
                        date: date
                    });
                    return null;
                }
            }
            
            /**
             * Fetch store hours for a date range (useful for calendar display)
             * @param {string} locationName - The store location name
             * @param {Date} startDate - Start date of range
             * @param {Date} endDate - End date of range
             * @returns {Array} Array of store hours objects
             */
            function fetchStoreHoursRange(locationName, startDate, endDate) {
                try {
                    const startStr = formatDateForNetSuite(startDate);
                    const endStr = formatDateForNetSuite(endDate);
                    
                    // Get location ID from location name
                    const locationId = getLocationIdByName(locationName);
                    
                    if (!locationId) {
                        log.error('Unknown location name for range search (Client-Side)', { locationName: locationName });
                        return [];
                    }
                    
                    const storeHoursSearch = search.create({
                        type: 'customrecord_store_hours',
                        filters: [
                            ['custrecord_sc_location', 'anyof', locationId],
                            'AND',
                            ['custrecord_sc_date', 'within', startStr, endStr]
                        ],
                        columns: [
                            search.createColumn({
                                name: 'custrecord_sc_date',
                                sort: search.Sort.ASC
                            }),
                            'custrecord_sc_location',
                            'custrecord_sc_open_time',
                            'custrecord_sc_close_time',
                            'custrecord_sc_notes',
                            'custrecord_sc_status',
                            'custrecord_sc_is_special',
                            'custrecord_sc_special_label',
                            'custrecord_sc_is_day'
                        ]
                    });
                    
                    const hoursArray = [];
                    storeHoursSearch.run().each(function(result) {
                        const status = result.getValue('custrecord_sc_status');
                        const openTime = result.getValue('custrecord_sc_open_time');
                        const closeTime = result.getValue('custrecord_sc_close_time');
                        const isSpecial = result.getValue('custrecord_sc_is_special');
                        
                        hoursArray.push({
                            location: result.getValue('custrecord_sc_location'),
                            date: result.getValue('custrecord_sc_date'),
                            openTime: openTime,
                            closeTime: closeTime,
                            status: status,
                            isClosed: status === '2' || status === 2, // NetSuite Custom List: Closed = ID 2
                            isSpecial: isSpecial === 'T' || isSpecial === true,
                            specialLabel: result.getValue('custrecord_sc_special_label') || '',
                            notes: result.getValue('custrecord_sc_notes') || '',
                            dayOfWeek: result.getValue('custrecord_sc_is_day') || ''
                        });
                        
                        return true; // Continue to get all results
                    });
                    
                    return hoursArray;
                } catch (error) {
                    log.error('Error fetching store hours range', {
                        error: error.toString(),
                        location: locationName,
                        startDate: startDate,
                        endDate: endDate
                    });
                    return [];
                }
            }
            
            /**
             * Convert NetSuite time format to hours and minutes
             * @param {string} timeStr - Time string from NetSuite (e.g., "8:30 am", "5:00 pm")
             * @returns {Object} Object with hour and minute properties
             */
            function parseNetSuiteTime(timeStr) {
                if (!timeStr) return null;
                
                const cleanTime = timeStr.toLowerCase().trim();
                const isPM = cleanTime.includes('pm');
                const isAM = cleanTime.includes('am');
                
                // Remove am/pm and parse time
                const timePart = cleanTime.replace(/\s*(am|pm)/i, '').trim();
                const [hourStr, minuteStr] = timePart.split(':');
                
                let hour = parseInt(hourStr);
                const minute = parseInt(minuteStr || '0');
                
                // Convert to 24-hour format
                if (isPM && hour !== 12) {
                    hour += 12;
                } else if (isAM && hour === 12) {
                    hour = 0;
                }
                
                console.log('Parsed NetSuite time:', {
                    original: timeStr,
                    cleaned: cleanTime,
                    timePart: timePart,
                    hourStr: hourStr,
                    minuteStr: minuteStr,
                    finalHour: hour,
                    finalMinute: minute,
                    isPM: isPM,
                    isAM: isAM
                });
                
                return { hour, minute };
            }
            
            /**
             * Format date for NetSuite search
             * @param {Date} date - JavaScript Date object
             * @returns {string} Date string in M/D/YYYY format
             */
            function formatDateForNetSuite(date) {
                return (date.getMonth() + 1) + '/' + 
                       date.getDate() + '/' + 
                       date.getFullYear();
            }
            
            /**
             * Base time slot configuration for different store locations
             * Each location can have different operating hours and appointment availability
             * NOTE: This is now kept as a fallback for when NetSuite records are not available
             */
            const TIME_SLOT_CONFIG = {
                // Default configuration (used when no specific location config exists)
                default: {
                    operatingHours: {
                        0: { start: 11, end: 16, lastAppointment: { hour: 15, minute: 30 } }, // Sunday
                        1: { start: 9, end: 19, lastAppointment: { hour: 18, minute: 30 } },  // Monday
                        2: { start: 9, end: 19, lastAppointment: { hour: 18, minute: 30 } },  // Tuesday
                        3: { start: 9, end: 19, lastAppointment: { hour: 18, minute: 30 } },  // Wednesday
                        4: { start: 9, end: 19, lastAppointment: { hour: 18, minute: 30 } },  // Thursday
                        5: { start: 9, end: 18, lastAppointment: { hour: 17, minute: 30 } },  // Friday
                        6: { start: 9, end: 17, lastAppointment: { hour: 16, minute: 30 } }   // Saturday
                    },
                    earlySlotOffset: 30, // minutes before opening for early appointments
                    slotInterval: 30,    // minutes between appointment slots
                    includeClosingSlot: true // whether to include a closing time slot
                },
                
                // Cabinet Direct specific configuration
                'Cabinet Direct': {
                    operatingHours: {
                        0: { start: 8, startMinute: 30, end: 17, lastAppointment: { hour: 17, minute: 0 } }, // Sunday: 8:30-5:00
                        1: { start: 8, startMinute: 30, end: 17, lastAppointment: { hour: 17, minute: 0 } }, // Monday: 8:30-5:00
                        2: { start: 8, startMinute: 30, end: 19, lastAppointment: { hour: 19, minute: 0 } }, // Tuesday: 8:30-7:00
                        3: { start: 8, startMinute: 30, end: 19, lastAppointment: { hour: 19, minute: 0 } }, // Wednesday: 8:30-7:00
                        4: { start: 8, startMinute: 30, end: 19, lastAppointment: { hour: 19, minute: 0 } }, // Thursday: 8:30-7:00
                        5: { start: 8, startMinute: 30, end: 19, lastAppointment: { hour: 19, minute: 0 } }, // Friday: 8:30-7:00
                        6: { start: 8, startMinute: 30, end: 17, lastAppointment: { hour: 17, minute: 0 } }  // Saturday: 8:30-5:00
                    },
                    earlySlotOffset: 0, // Start exactly at 8:30 AM, no early slots
                    slotInterval: 30,
                    includeClosingSlot: true
                },
                
                // Showroom locations (East Meadow, Commack, Franklin Square, Copiague, Patchogue)
                // NOTE: These are fallback hours - NetSuite customrecord_store_hours should be used when available
                showrooms: {
                    operatingHours: {
                        0: { start: 11, end: 16, lastAppointment: { hour: 16, minute: 0 } }, // Sunday: 11:00-4:00
                        1: { start: 9, end: 19, lastAppointment: { hour: 19, minute: 0 } },  // Monday: 9:00-7:00
                        2: { start: 9, end: 19, lastAppointment: { hour: 19, minute: 0 } },  // Tuesday: 9:00-7:00
                        3: { start: 9, end: 19, lastAppointment: { hour: 19, minute: 0 } },  // Wednesday: 9:00-7:00
                        4: { start: 9, end: 19, lastAppointment: { hour: 19, minute: 0 } },  // Thursday: 9:00-7:00
                        5: { start: 9, end: 18, lastAppointment: { hour: 18, minute: 0 } },  // Friday: 9:00-6:00
                        6: { start: 9, end: 17, lastAppointment: { hour: 17, minute: 0 } }   // Saturday: 9:00-5:00
                    },
                    earlySlotOffset: 0, // Start exactly at scheduled time, no early slots
                    slotInterval: 30,
                    includeClosingSlot: true
                }
            };
            
            /**
             * User availability configuration
             * This can be expanded to include individual user schedules, vacation days, etc.
             */
            const USER_AVAILABILITY_CONFIG = {
                // Example: Individual user availability overrides
                // 'user123': {
                //     unavailableDays: [0, 6], // Sunday and Saturday
                //     unavailableHours: { start: 12, end: 13 }, // Lunch break
                //     customSlots: [
                //         { day: 1, hour: 8, minute: 0, available: true }, // Monday 8:00 AM
                //         { day: 1, hour: 8, minute: 30, available: false } // Monday 8:30 AM
                //     ]
                // }
            };
            
            /**
             * Get time slot configuration for a specific location and date
             * This now checks NetSuite store hours first, then falls back to hardcoded config
             * @param {string} location - The store location name
             * @param {Date} date - The date to get configuration for (optional)
             * @returns {Object} Time slot configuration object
             */
            function getTimeSlotConfig(location, date = null) {
                // Check if we're running server-side (NetSuite) or client-side (browser)
                const isServerSide = typeof search !== 'undefined';
                
                // If date is provided and we're server-side, try to fetch from NetSuite first
                if (date && location && isServerSide) {
                    const storeHours = fetchStoreHoursFromNetSuite(location, date);
                    
                    if (storeHours) {
                        // Check if store is closed - NetSuite Custom List: Closed = ID 2
                        if (storeHours.status === '2' || storeHours.status === 2 || storeHours.isClosed === true) {
                            return {
                                operatingHours: {},
                                isClosed: true,
                                isSpecial: storeHours.isSpecial,
                                specialLabel: storeHours.specialLabel || 'Store Closed',
                                notes: storeHours.notes,
                                status: storeHours.status
                            };
                        }
                        
                        // Parse opening and closing times
                        const openTime = parseNetSuiteTime(storeHours.openTime);
                        const closeTime = parseNetSuiteTime(storeHours.closeTime);
                        
                        if (openTime && closeTime) {
                            // Create dynamic configuration from NetSuite data
                            const dayOfWeek = date.getDay();
                            return {
                                operatingHours: {
                                    [dayOfWeek]: {
                                        start: openTime.hour,
                                        startMinute: openTime.minute,
                                        end: closeTime.hour,
                                        endMinute: closeTime.minute,
                                        lastAppointment: {
                                            hour: closeTime.minute === 0 ? closeTime.hour - 1 : closeTime.hour,
                                            minute: closeTime.minute === 0 ? 30 : 0
                                        }
                                    }
                                },
                                earlySlotOffset: 30,
                                slotInterval: 30,
                                includeClosingSlot: false,
                                isSpecial: storeHours.isSpecial,
                                specialLabel: storeHours.specialLabel,
                                notes: storeHours.notes
                            };
                        }
                    }
                }
                
                // Fall back to hardcoded configuration
                // Check for specific location configuration
                if (TIME_SLOT_CONFIG[location]) {
                    return TIME_SLOT_CONFIG[location];
                }
                
                // Check if it's a showroom location
                const showroomLocations = ['East Meadow', 'Commack', 'Franklin Square', 'Copiague', 'Patchogue'];
                if (showroomLocations.includes(location)) {
                    return TIME_SLOT_CONFIG.showrooms;
                }
                
                // Default configuration
                return TIME_SLOT_CONFIG.default;
            }
            
            /**
             * Check if a specific time slot is available for a user
             * @param {Date} date - The appointment date
             * @param {number} hour - The hour (24-hour format)
             * @param {number} minute - The minute
             * @param {string} userId - The user ID (optional)
             * @returns {boolean} Whether the time slot is available
             */
            function isTimeSlotAvailable(date, hour, minute, userId = null, appointmentsByEmployee = null, excludeAppointmentId = null) {
                // Check user-specific availability if userId is provided
                if (userId && USER_AVAILABILITY_CONFIG[userId]) {
                    const userConfig = USER_AVAILABILITY_CONFIG[userId];
                    const dayOfWeek = date.getDay();
                    
                    // Check if user is unavailable on this day
                    if (userConfig.unavailableDays && userConfig.unavailableDays.includes(dayOfWeek)) {
                        return false;
                    }
                    
                    // Check if user has lunch break or other unavailable hours
                    if (userConfig.unavailableHours) {
                        const timeInMinutes = hour * 60 + minute;
                        const unavailableStart = userConfig.unavailableHours.start * 60;
                        const unavailableEnd = userConfig.unavailableHours.end * 60;
                        
                        if (timeInMinutes >= unavailableStart && timeInMinutes < unavailableEnd) {
                            return false;
                        }
                    }
                    
                    // Check custom slot availability
                    if (userConfig.customSlots) {
                        const customSlot = userConfig.customSlots.find(slot => 
                            slot.day === dayOfWeek && slot.hour === hour && slot.minute === minute
                        );
                        if (customSlot !== undefined) {
                            return customSlot.available;
                        }
                    }
                }
                
                // Check for existing appointments for the selected salesperson
                if (userId && appointmentsByEmployee) {
                    
                    if (appointmentsByEmployee[userId]) {
                        const userAppointments = appointmentsByEmployee[userId];
                        // Format date as M/D/YYYY for comparison with NetSuite appointment data (no leading zeros)
                        const dateString = String(date.getMonth() + 1) + '/' + 
                            String(date.getDate()) + '/' + 
                            date.getFullYear();
                        
                        
                        // Check if there's an appointment that overlaps with this time slot
                        const conflictingAppointment = userAppointments.find(appt => {
                            // Skip the appointment being changed (if excludeAppointmentId is provided)
                            if (excludeAppointmentId && appt.id && String(appt.id) === String(excludeAppointmentId)) {
                                console.log('Excluding appointment being changed:', appt.id);
                                return false; // Don't consider this appointment for conflicts
                            }

                            // Skip appointments marked as rescheduled (they no longer block time slots)
                            console.log('Checking appointment for rescheduled flag:', {
                                id: appt.id,
                                rescheduled: appt.rescheduled,
                                rescheduledType: typeof appt.rescheduled,
                                startTime: appt.startTime
                            });
                            if (appt.rescheduled === true || appt.rescheduled === 'T') {
                                console.log('✓ Excluding rescheduled appointment from availability check:', appt.id);
                                return false; // Don't consider rescheduled appointments for conflicts
                            }

                            if (appt.startDate !== dateString) {
                                return false;
                            }
                            
                            // Parse the appointment start time
                            const apptStartTime = appt.startTime;
                            const apptEndTime = appt.endTime;
                            if (!apptStartTime) {
                                return false;
                            }
                            
                            // Helper function to parse time string to minutes since midnight
                            function parseTimeToMinutes(timeStr) {
                                if (!timeStr) return null;
                                
                                let apptHour, apptMinute;
                                
                                // Handle different time formats
                                if (timeStr.toLowerCase().includes('am') || timeStr.toLowerCase().includes('pm')) {
                                    // 12-hour format with AM/PM
                                    const isPM = timeStr.toLowerCase().includes('pm');
                                    const timeStrClean = timeStr.replace(/\s*(am|pm)/i, '').trim();
                                    const [hourStr, minuteStr] = timeStrClean.split(':');
                                    apptHour = parseInt(hourStr);
                                    apptMinute = parseInt(minuteStr || '0');
                                    
                                    // Convert to 24-hour format
                                    if (isPM && apptHour !== 12) {
                                        apptHour += 12;
                                    } else if (!isPM && apptHour === 12) {
                                        apptHour = 0;
                                    }
                                } else {
                                    // 24-hour format
                                    const [hourStr, minuteStr] = timeStr.split(':');
                                    apptHour = parseInt(hourStr);
                                    apptMinute = parseInt(minuteStr || '0');
                                }
                                
                                return apptHour * 60 + apptMinute;
                            }
                            
                            // Convert appointment start and end times to minutes since midnight
                            const apptStartMinutes = parseTimeToMinutes(apptStartTime);
                            const apptEndMinutes = parseTimeToMinutes(apptEndTime);
                            
                            // Convert the time slot being checked to minutes since midnight
                            const slotMinutes = hour * 60 + minute;
                            
                            // If we have both start and end times, check if slot falls within the appointment duration
                            if (apptStartMinutes !== null && apptEndMinutes !== null) {
                                // Check if the time slot falls within the appointment duration (inclusive of start, exclusive of end)
                                return slotMinutes >= apptStartMinutes && slotMinutes < apptEndMinutes;
                            } else if (apptStartMinutes !== null) {
                                // If we only have start time, check exact match (fallback to old behavior)
                                return slotMinutes === apptStartMinutes;
                            }
                            
                            return false;
                        });
                        
                        // If there's a conflicting appointment, mark as occupied but still selectable
                        if (conflictingAppointment) {
                            return 'occupied'; // Return 'occupied' instead of false to indicate it's selectable but greyed out
                        }
                    }
                }
                
                // Default: all slots are available
                return true;
            }
            
            // ============================================================================
            // TIME SLOT MANAGEMENT HELPER FUNCTIONS
            // ============================================================================
            
            /**
             * Add a new location configuration to the time slot system
             * @param {string} locationName - The name of the location
             * @param {Object} config - The configuration object
             * @example
             * addLocationConfig('New Store', {
             *     operatingHours: {
             *         1: { start: 8, end: 20, lastAppointment: { hour: 19, minute: 30 } }
             *     },
             *     earlySlotOffset: 30,
             *     slotInterval: 30,
             *     includeClosingSlot: true
             * });
             */
            function addLocationConfig(locationName, config) {
                TIME_SLOT_CONFIG[locationName] = config;
                console.log('Added location configuration for:', locationName);
            }
            
            /**
             * Update operating hours for a specific location and day
             * @param {string} locationName - The location name
             * @param {number} dayOfWeek - Day of week (0=Sunday, 1=Monday, etc.)
             * @param {Object} hours - Hours configuration { start, end, lastAppointment: { hour, minute } }
             * @example
             * updateLocationHours('Cabinet Direct', 1, { 
             *     start: 8, 
             *     end: 20, 
             *     lastAppointment: { hour: 19, minute: 30 } 
             * });
             */
            function updateLocationHours(locationName, dayOfWeek, hours) {
                const config = getTimeSlotConfig(locationName);
                if (!config.operatingHours) {
                    config.operatingHours = {};
                }
                config.operatingHours[dayOfWeek] = hours;
                console.log('Updated ' + locationName + ' hours for day ' + dayOfWeek + ':', hours);
            }
            
            /**
             * Set user availability configuration
             * @param {string} userId - The user ID
             * @param {Object} availability - Availability configuration
             * @example
             * setUserAvailability('user123', {
             *     unavailableDays: [0, 6], // Sunday and Saturday
             *     unavailableHours: { start: 12, end: 13 }, // Lunch break
             *     customSlots: [
             *         { day: 1, hour: 8, minute: 0, available: true }
             *     ]
             * });
             */
            function setUserAvailability(userId, availability) {
                USER_AVAILABILITY_CONFIG[userId] = availability;
                console.log('Set user availability for:', userId);
            }
            
            /**
             * Get all available time slots for a specific date and location
             * @param {Date} date - The date
             * @param {string} location - The location name
             * @param {string} userId - Optional user ID for availability filtering
             * @returns {Array} Array of available time slots
             */
            function getAvailableTimeSlots(date, location, userId = null) {
                return generateTimeSlots(date, location, userId, originalAppointmentsByEmployee || allAppointmentsByEmployee);
            }
            
            /**
             * Check if a location has specific operating hours configured
             * @param {string} locationName - The location name
             * @param {number} dayOfWeek - Day of week (0=Sunday, 1=Monday, etc.)
             * @returns {boolean} Whether the location has hours configured for that day
             */
            function hasLocationHours(locationName, dayOfWeek) {
                const config = getTimeSlotConfig(locationName);
                return config.operatingHours && config.operatingHours[dayOfWeek];
            }
            
            /**
             * Get the operating hours for a specific location and day
             * @param {string} locationName - The location name
             * @param {number} dayOfWeek - Day of week (0=Sunday, 1=Monday, etc.)
             * @returns {Object|null} Operating hours object or null if not configured
             */
            function getLocationHours(locationName, dayOfWeek) {
                const config = getTimeSlotConfig(locationName);
                return config.operatingHours && config.operatingHours[dayOfWeek] || null;
            }
            
            /**
             * Add a custom time slot for a specific location
             * This allows adding non-standard time slots (e.g., 15-minute intervals)
             * @param {string} locationName - The location name
             * @param {number} dayOfWeek - Day of week (0=Sunday, 1=Monday, etc.)
             * @param {number} hour - Hour (24-hour format)
             * @param {number} minute - Minute
             * @param {boolean} available - Whether the slot is available
             */
            function addCustomTimeSlot(locationName, dayOfWeek, hour, minute, available = true) {
                const config = getTimeSlotConfig(locationName);
                if (!config.customSlots) {
                    config.customSlots = [];
                }
                
                // Remove existing slot if it exists
                config.customSlots = config.customSlots.filter(slot => 
                    !(slot.day === dayOfWeek && slot.hour === hour && slot.minute === minute)
                );
                
                // Add new slot
                config.customSlots.push({
                    day: dayOfWeek,
                    hour: hour,
                    minute: minute,
                    available: available
                });
                
                console.log('Added custom time slot for ' + locationName + ': ' + hour + ':' + minute.toString().padStart(2, '0') + ' on day ' + dayOfWeek);
            }

            function generateTimeSlots(selectedDate, location = null, userId = null, appointmentsByEmployee = null) {
                const dayOfWeek = selectedDate.getDay(); // 0 = Sunday, 1 = Monday, etc.

                // Get exclusion ID if in change mode
                const excludeAppointmentId = window.excludeAppointmentIdForAvailability || null;
                if (excludeAppointmentId) {
                    console.log('Rendering time slots with appointment exclusion:', excludeAppointmentId);
                }

                // Get configuration for the specified location and date
                const config = getTimeSlotConfig(location, selectedDate);
                
                // Check if store is closed
                if (config.isClosed) {
                    console.log('Store is closed on this date:', selectedDate, config.specialLabel || '');
                    return [];
                }
                
                const dayConfig = config.operatingHours[dayOfWeek];
                
                if (!dayConfig) {
                    console.warn('No operating hours configured for day:', dayOfWeek);
                    return [];
                }
                
                const { start: startTime, startMinute = 0, end: endTime, endMinute = 0, lastAppointment } = dayConfig;
                const timeSlots = [];
                
                // Calculate total minutes for start and end times
                const startTotalMinutes = startTime * 60 + startMinute;
                const endTotalMinutes = endTime * 60 + endMinute;
                const lastAppointmentMinutes = lastAppointment.hour * 60 + lastAppointment.minute;
                
                // Generate time slots at 30-minute intervals
                const slotInterval = config.slotInterval || 30;
                
                // Add early slot (before opening) if configured and not using NetSuite hours
                if (config.earlySlotOffset > 0 && startMinute === 0) {
                    const earlyHour = startTime === 11 ? 10 : startTime - 1;
                    const earlyMinute = startTime === 11 ? 30 : config.earlySlotOffset;

                    const availability = isTimeSlotAvailable(selectedDate, earlyHour, earlyMinute, userId, appointmentsByEmployee, excludeAppointmentId);
                    if (availability !== false) {
                        const earlyTime = formatTime(earlyHour, earlyMinute);
                        timeSlots.push({
                            value: formatTimeValue(earlyHour, earlyMinute),
                            display: earlyTime,
                            available: availability === 'occupied' ? 'occupied' : true
                        });
                    }
                }
                
                // Generate regular intervals from opening to last appointment time
                for (let totalMinutes = startTotalMinutes; totalMinutes <= lastAppointmentMinutes; totalMinutes += slotInterval) {
                    const hour = Math.floor(totalMinutes / 60);
                    const minute = totalMinutes % 60;

                    const availability = isTimeSlotAvailable(selectedDate, hour, minute, userId, appointmentsByEmployee, excludeAppointmentId);
                    if (availability !== false) {
                        const time = formatTime(hour, minute);
                        timeSlots.push({
                            value: formatTimeValue(hour, minute),
                            display: time,
                            available: availability === 'occupied' ? 'occupied' : true
                        });
                    }
                }
                
                // Add closing time slot if configured and it's not already included
                if (config.includeClosingSlot && endTotalMinutes > lastAppointmentMinutes) {
                    const availability = isTimeSlotAvailable(selectedDate, endTime, endMinute, userId, appointmentsByEmployee, excludeAppointmentId);
                    if (availability !== false) {
                        const closingTime = formatTime(endTime, endMinute);
                        timeSlots.push({
                            value: formatTimeValue(endTime, endMinute),
                            display: closingTime,
                            available: availability === 'occupied' ? 'occupied' : true
                        });
                    }
                }
                
                // Add custom time slots if configured for this location
                if (config.customSlots) {
                    config.customSlots.forEach(customSlot => {
                        const availability = isTimeSlotAvailable(selectedDate, customSlot.hour, customSlot.minute, userId, appointmentsByEmployee, excludeAppointmentId);
                        if (customSlot.day === dayOfWeek && availability !== false) {
                            const customTime = formatTime(customSlot.hour, customSlot.minute);
                            timeSlots.push({
                                value: formatTimeValue(customSlot.hour, customSlot.minute),
                                display: customTime,
                                available: availability === 'occupied' ? 'occupied' : customSlot.available
                            });
                        }
                    });
                }
                
                // Sort time slots by time value
                timeSlots.sort((a, b) => {
                    const timeA = a.value.split(':').map(Number);
                    const timeB = b.value.split(':').map(Number);
                    return (timeA[0] * 60 + timeA[1]) - (timeB[0] * 60 + timeB[1]);
                });
                
                return timeSlots;
            }
            
            function formatTime(hour, minutes) {
                const period = hour >= 12 ? 'PM' : 'AM';
                const displayHour = hour > 12 ? hour - 12 : (hour === 0 ? 12 : hour);
                const displayMinutes = minutes === 0 ? '00' : minutes.toString();
                return displayHour + ':' + displayMinutes + ' ' + period;
            }
            
            function formatTimeValue(hour, minutes) {
                const hourStr = hour.toString().padStart(2, '0');
                const minutesStr = minutes.toString().padStart(2, '0');
                return hourStr + ':' + minutesStr;
            }
            
            // Track current time slots request to prevent race conditions
            let currentTimeSlotRequest = null;
            
            // Cache for appointments data to avoid repeated requests
            const appointmentsCache = {};
            const APPOINTMENTS_CACHE_DURATION = 5 * 60 * 1000; // 5 minutes
            
            /**
             * Clean up old cache entries to prevent memory buildup
             */
            function cleanupAppointmentsCache() {
                const now = Date.now();
                Object.keys(appointmentsCache).forEach(key => {
                    if (now - appointmentsCache[key].timestamp > APPOINTMENTS_CACHE_DURATION) {
                        delete appointmentsCache[key];
                    }
                });
            }
            
            /**
             * Clear cache entries that might contain stale global data
             */
            function clearStaleGlobalDataCache() {
                const today = new Date();
                Object.keys(appointmentsCache).forEach(dateKey => {
                    const cacheDate = new Date(dateKey);
                    const daysFromToday = Math.floor((cacheDate - today) / (1000 * 60 * 60 * 24));
                    
                    // Clear cache for dates that are outside the "safe" range for global data
                    if (daysFromToday < -1 || daysFromToday > 3) {
                        console.log('Clearing potentially stale cache for', dateKey);
                        delete appointmentsCache[dateKey];
                    }
                });
            }
            
            // Clean up cache every 5 minutes
            setInterval(cleanupAppointmentsCache, APPOINTMENTS_CACHE_DURATION);
            
            // Preloading state management
            let preloadingInProgress = false;
            let preloadingAborted = false;
            
            /**
             * Preemptively cache appointment data for the selected salesperson
             * Loads 60 days into the future with intelligent request spacing
             */
            function preloadSalespersonAppointments(salespersonId) {
                if (preloadingInProgress) {
                    console.log('Preloading already in progress, aborting previous session');
                    preloadingAborted = true;
                }
                
                preloadingInProgress = true;
                preloadingAborted = false;
                
                console.log('Starting preemptive appointment caching for salesperson:', salespersonId);
                
                const today = new Date();
                const datesToPreload = [];
                
                // Generate dates for the next 60 days
                for (let i = 0; i < 60; i++) {
                    const date = new Date(today);
                    date.setDate(today.getDate() + i);
                    const dateStr = (date.getMonth() + 1) + '/' + date.getDate() + '/' + date.getFullYear();
                    
                    // Only preload if not already cached
                    if (!appointmentsCache[dateStr]) {
                        datesToPreload.push({
                            dateStr: dateStr,
                            date: new Date(date)
                        });
                    }
                }
                
                console.log('Preloading ' + datesToPreload.length + ' dates for salesperson ' + salespersonId);
                
                // Preload in batches to avoid overwhelming the server
                let currentIndex = 0;
                const batchSize = 5;
                const batchDelay = 2000; // 2 seconds between batches
                const requestDelay = 200; // 200ms between individual requests in a batch
                
                function preloadNextBatch() {
                    if (preloadingAborted) {
                        console.log('Preloading aborted');
                        preloadingInProgress = false;
                        return;
                    }
                    
                    const batchEnd = Math.min(currentIndex + batchSize, datesToPreload.length);
                    const currentBatch = datesToPreload.slice(currentIndex, batchEnd);
                    
                    if (currentBatch.length === 0) {
                        console.log('Preloading completed successfully');
                        preloadingInProgress = false;
                        return;
                    }
                    
                    console.log('Preloading batch ' + (Math.floor(currentIndex / batchSize) + 1) + ': dates ' + (currentIndex + 1) + '-' + batchEnd);
                    
                    // Process current batch
                    currentBatch.forEach((dateInfo, index) => {
                        setTimeout(() => {
                            if (preloadingAborted) return;
                            
                            getAppointmentsForDate(dateInfo.dateStr).catch(error => {
                                console.log('Preload failed for', dateInfo.dateStr, error);
                            });
                        }, index * requestDelay);
                    });
                    
                    currentIndex = batchEnd;
                    
                    // Schedule next batch
                    if (currentIndex < datesToPreload.length) {
                        setTimeout(preloadNextBatch, batchDelay);
                    } else {
                        console.log('Preloading completed successfully');
                        preloadingInProgress = false;
                    }
                }
                
                // Start preloading after a short delay to not interfere with immediate UI needs
                setTimeout(preloadNextBatch, 1000);
            }
            
            /**
             * Stop any ongoing preloading process
             */
            function stopPreloading() {
                if (preloadingInProgress) {
                    console.log('Stopping preloading process');
                    preloadingAborted = true;
                }
            }
            
            /**
             * Get cache statistics for debugging
             */
            function getCacheStats() {
                const now = Date.now();
                const stats = {
                    totalEntries: Object.keys(appointmentsCache).length,
                    freshEntries: 0,
                    staleEntries: 0,
                    preloadingActive: preloadingInProgress
                };
                
                Object.values(appointmentsCache).forEach(entry => {
                    if (now - entry.timestamp < APPOINTMENTS_CACHE_DURATION) {
                        stats.freshEntries++;
                    } else {
                        stats.staleEntries++;
                    }
                });
                
                return stats;
            }
            
            // Expose cache stats to console for debugging
            window.getAppointmentCacheStats = getCacheStats;
            
            /**
             * Get appointments data for a date range, optimized for batch fetching
             */
            function getAppointmentsForDateRange(startDateStr, endDateStr, employee, stores) {
                // Set default values
                employee = employee || null;
                stores = stores || [];
                
                // Create a cache key for the range request
                var cacheKey = 'range_' + startDateStr + '_' + endDateStr + '_' + (employee || 'all') + '_' + stores.join(',');
                var cached = appointmentsCache[cacheKey];
                if (cached && (Date.now() - cached.timestamp) < APPOINTMENTS_CACHE_DURATION) {
                    console.log('Using cached appointments for date range', startDateStr, 'to', endDateStr);
                    return Promise.resolve(cached.data);
                }
                
                console.log('Fetching fresh appointments data for date range', startDateStr, 'to', endDateStr);
                
                // Prepare the request body
                var requestBody = 'action=getAppointmentsForDateRange&startDate=' + encodeURIComponent(startDateStr) + '&endDate=' + encodeURIComponent(endDateStr);
                
                if (employee) {
                    requestBody += '&employee=' + encodeURIComponent(employee);
                }
                
                if (stores && stores.length > 0) {
                    stores.forEach(function(store) {
                        requestBody += '&stores=' + encodeURIComponent(store);
                    });
                }
                
                return fetch(window.location.href, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/x-www-form-urlencoded'
                    },
                    body: requestBody
                })
                .then(function(response) { return response.json(); })
                .then(function(data) {
                    // Cache the result for future use
                    appointmentsCache[cacheKey] = {
                        data: data,
                        timestamp: Date.now()
                    };
                    
                    // Also cache individual dates from the batch for faster individual lookups
                    if (data.success && data.appointmentsByDate) {
                        Object.keys(data.appointmentsByDate).forEach(function(dateStr) {
                            var singleDateCacheKey = dateStr;
                            if (!appointmentsCache[singleDateCacheKey] || 
                                (Date.now() - appointmentsCache[singleDateCacheKey].timestamp) >= APPOINTMENTS_CACHE_DURATION) {
                                appointmentsCache[singleDateCacheKey] = {
                                    data: {
                                        success: true,
                                        appointments: data.appointments, // Keep the grouped format
                                        date: dateStr,
                                        totalAppointments: data.appointmentsByDate[dateStr].length
                                    },
                                    timestamp: Date.now()
                                };
                            }
                        });
                    }
                    
                    console.log('Cached fresh appointment data for date range', startDateStr, 'to', endDateStr);
                    return data;
                })
                .catch(function(error) {
                    console.error('Error fetching appointments for date range:', error);
                    throw error;
                });
            }

            /**
             * Get appointments data for a specific date, using cache or existing data when possible
             */
            function getAppointmentsForDate(dateStr) {
                // Check cache first
                const cacheKey = dateStr;
                const cached = appointmentsCache[cacheKey];
                if (cached && (Date.now() - cached.timestamp) < APPOINTMENTS_CACHE_DURATION) {
                    console.log('Using cached appointments for', dateStr, '(from batch or individual cache)');
                    return Promise.resolve(cached.data);
                }
                
                // Always fetch fresh data to ensure accuracy
                // This is the most reliable approach for appointment blocking
                console.log('Fetching fresh appointments data for', dateStr);
                return fetch(window.location.href, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/x-www-form-urlencoded'
                    },
                    body: 'action=getAppointmentsForDate&date=' + encodeURIComponent(dateStr)
                })
                .then(response => response.json())
                .then(data => {
                    // Cache the result for future use
                    appointmentsCache[cacheKey] = {
                        data: data,
                        timestamp: Date.now()
                    };
                    console.log('Cached fresh appointment data for', dateStr);
                    return data;
                });
            }
            
            function renderTimeSlots(selectedDate, location = null, userId = null, excludeAppointmentId = null) {
                const timeSlotsContainer = document.getElementById('timeSlots');
                if (!timeSlotsContainer) return;
                
                // Clear existing time slots immediately
                timeSlotsContainer.innerHTML = '';
                
                // Cancel any pending request
                if (currentTimeSlotRequest) {
                    currentTimeSlotRequest.cancelled = true;
                }
                
                // Show loading indicator for client-side requests
                if (typeof search === 'undefined' && location && selectedDate) {
                    timeSlotsContainer.innerHTML = '<div style="text-align: center; padding: 2rem; color: #64748b; font-style: italic;">Loading time slots...</div>';
                }
                
                // Check if we need to fetch store hours from server (client-side)
                const isClientSide = typeof search === 'undefined';
                
                if (isClientSide && location && selectedDate) {
                    // Client-side: fetch store hours and get appointments (using cache when possible)
                    const formatDate = (date) => {
                        return (date.getMonth() + 1) + '/' + date.getDate() + '/' + date.getFullYear();
                    };
                    
                    const dateStr = formatDate(selectedDate);
                    
                    // Create request tracking object
                    const requestTracker = { cancelled: false };
                    currentTimeSlotRequest = requestTracker;
                    
                    // Fetch store hours and get appointments (using optimized caching)
                    Promise.all([
                        // Fetch store hours (still needed for accurate store hours)
                        fetch(window.location.href, {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json'
                            },
                            body: JSON.stringify({
                                action: 'getStoreHours',
                                location: location,
                                startDate: dateStr,
                                endDate: dateStr
                            })
                        }).then(response => response.json()),
                        
                        // Get appointments using optimized caching
                        getAppointmentsForDate(dateStr)
                    ])
                    .then(([storeHoursData, appointmentsData]) => {
                        // Check if this request was cancelled
                        if (requestTracker.cancelled) {
                            console.log('Time slots request was cancelled');
                            return;
                        }
                        
                        console.log('Store hours fetch response:', storeHoursData);
                        console.log('Appointments fetch response:', appointmentsData);
                        console.log('Location requested:', location);
                        console.log('Date requested:', dateStr);
                        
                        // Use appointments data for the selected date if available, otherwise fall back to global data
                        let appointmentsByEmployee = originalAppointmentsByEmployee || allAppointmentsByEmployee;
                        if (appointmentsData && appointmentsData.success && appointmentsData.appointments) {
                            appointmentsByEmployee = appointmentsData.appointments;
                            console.log('Using appointments data for selected date:', appointmentsByEmployee);
                        } else {
                            console.log('Using global appointments data (may not include selected date)');
                        }
                        
                        if (storeHoursData.success && storeHoursData.storeHours && storeHoursData.storeHours.length > 0) {
                            const storeHours = storeHoursData.storeHours[0]; // Get the first (and only) result
                            
                            console.log('Using NetSuite store hours:', storeHours);
                            
                            // Check if store is closed and show appropriate message
                            if (storeHours.status === 'Closed' || storeHours.status === 'closed' || storeHours.status === 'CLOSED' || storeHours.isClosed === true) {
                                timeSlotsContainer.innerHTML = '<div style="text-align: center; padding: 3rem 2rem; color: #991b1b; font-weight: 600; background: #fee2e2; border: 2px solid #fca5a5; border-radius: 8px; margin: 0.5rem;">' +
                                    '<div style="font-size: 1.25rem; margin-bottom: 0.5rem;">🚫 Store Closed</div>' +
                                    '<div style="font-size: 0.875rem; font-weight: 400;">' + (storeHours.specialLabel || 'No appointments available on this date') + '</div>' +
                                '</div>';
                                return;
                            }
                            
                            // Generate time slots with store hours data and appointments for the selected date
                            const timeSlots = generateTimeSlotsWithStoreHours(selectedDate, storeHours, userId, appointmentsByEmployee, excludeAppointmentId);
                            renderTimeSlotsUI(timeSlots, timeSlotsContainer);
                        } else {
                            console.warn('No NetSuite store hours found for location:', location, 'on date:', dateStr);
                            console.log('Full response data:', storeHoursData);
                            console.log('Expected location name in NetSuite:', location);
                            console.log('Falling back to hardcoded config');
                            
                            // Fallback to hardcoded configuration with appointments for the selected date
                            const timeSlots = generateTimeSlots(selectedDate, location, userId, appointmentsByEmployee);
                            renderTimeSlotsUI(timeSlots, timeSlotsContainer);
                        }
                    })
                    .catch(error => {
                        // Check if this request was cancelled
                        if (requestTracker.cancelled) {
                            console.log('Time slots request was cancelled');
                            return;
                        }
                        
                        console.error('Error fetching store hours or appointments for time slots:', error);
                        // Fallback to hardcoded configuration with global appointments
                        const timeSlots = generateTimeSlots(selectedDate, location, userId, originalAppointmentsByEmployee || allAppointmentsByEmployee);
                        renderTimeSlotsUI(timeSlots, timeSlotsContainer);
                    });
                } else {
                    // Server-side or no location/date: use existing logic
                    const timeSlots = generateTimeSlots(selectedDate, location, userId, originalAppointmentsByEmployee || allAppointmentsByEmployee);
                    renderTimeSlotsUI(timeSlots, timeSlotsContainer);
                }
            }
            
            /**
             * Generate time slots using store hours data from NetSuite
             * @param {Date} selectedDate - The selected date
             * @param {Object} storeHours - Store hours object from NetSuite
             * @param {string} userId - User ID
             * @param {Object} appointmentsByEmployee - Appointments data
             * @returns {Array} Array of time slot objects
             */
            function generateTimeSlotsWithStoreHours(selectedDate, storeHours, userId = null, appointmentsByEmployee = null, excludeAppointmentId = null) {
                // Get exclusion ID if in change mode (check global if not provided as parameter)
                if (!excludeAppointmentId) {
                    excludeAppointmentId = window.excludeAppointmentIdForAvailability || null;
                }
                if (excludeAppointmentId) {
                    console.log('Rendering NetSuite time slots with appointment exclusion:', excludeAppointmentId);
                }

                // Check if store is closed - NetSuite Custom List: Closed = ID 2
                if (storeHours.status === '2' || storeHours.status === 2 || storeHours.isClosed === true) {
                    console.log('Store is closed on this date:', selectedDate, storeHours.specialLabel || 'Store Closed');
                    console.log('Store hours status:', storeHours.status, 'isClosed flag:', storeHours.isClosed);
                    return [];
                }
                
                // Parse opening and closing times
                const openTime = parseNetSuiteTime(storeHours.openTime);
                const closeTime = parseNetSuiteTime(storeHours.closeTime);
                
                if (!openTime || !closeTime) {
                    console.warn('Could not parse store hours:', storeHours.openTime, storeHours.closeTime);
                    return [];
                }
                
                console.log('NetSuite store hours parsed:', {
                    openTime: openTime,
                    closeTime: closeTime,
                    originalOpen: storeHours.openTime,
                    originalClose: storeHours.closeTime
                });
                
                const timeSlots = [];
                const slotInterval = 30; // 30-minute intervals
                
                // Calculate total minutes for start and end times
                const startTotalMinutes = openTime.hour * 60 + openTime.minute;
                const endTotalMinutes = closeTime.hour * 60 + closeTime.minute;
                
                // Make closing time inclusive - appointments can be scheduled up to closing time
                const lastAppointmentMinutes = endTotalMinutes;
                
                console.log('Time slot generation:', {
                    startTotalMinutes: startTotalMinutes,
                    endTotalMinutes: endTotalMinutes,
                    lastAppointmentMinutes: lastAppointmentMinutes,
                    startTime: openTime.hour + ':' + openTime.minute.toString().padStart(2, '0')
                });
                
                // Generate time slots starting exactly at the opening time from NetSuite
                for (let totalMinutes = startTotalMinutes; totalMinutes <= lastAppointmentMinutes; totalMinutes += slotInterval) {
                    const hour = Math.floor(totalMinutes / 60);
                    const minute = totalMinutes % 60;

                    const availability = isTimeSlotAvailable(selectedDate, hour, minute, userId, appointmentsByEmployee, excludeAppointmentId);
                    if (availability !== false) {
                        const time = formatTime(hour, minute);
                        timeSlots.push({
                            value: formatTimeValue(hour, minute),
                            display: time,
                            available: availability === 'occupied' ? 'occupied' : true
                        });

                        console.log('Added time slot:', time, 'from NetSuite hours');
                    }
                }
                
                // Sort time slots by time value
                timeSlots.sort((a, b) => {
                    const timeA = a.value.split(':').map(Number);
                    const timeB = b.value.split(':').map(Number);
                    return (timeA[0] * 60 + timeA[1]) - (timeB[0] * 60 + timeB[1]);
                });
                
                console.log('Final time slots from NetSuite:', timeSlots.map(slot => slot.display));
                
                return timeSlots;
            }
            
            /**
             * Render time slots UI elements
             * @param {Array} timeSlots - Array of time slot objects
             * @param {HTMLElement} container - Container element
             */
            function renderTimeSlotsUI(timeSlots, container) {
                // Always clear the container first to prevent stacking
                container.innerHTML = '';
                
                // Create and append time slot buttons
                timeSlots.forEach(slot => {
                    const button = document.createElement('button');
                    button.type = 'button';
                    button.className = 'time-slot';
                    button.dataset.time = slot.value;
                    button.textContent = slot.display;
                    
                    // Handle different availability states
                    if (slot.available === false) {
                        button.disabled = true;
                        button.title = 'This time slot is not available';
                    } else if (slot.available === 'occupied') {
                        button.classList.add('occupied');
                        button.disabled = true;
                        button.title = 'This time slot is unavailable - there is an existing appointment';
                        console.log('Added occupied class to:', slot.display);
                    }
                    
                    container.appendChild(button);
                });
                
                // Re-initialize event listeners for the new time slots
                initializeTimeSlots();

                // Update duration blocking if time and duration are selected
                updateDurationBlocking();

                // If Scheduled Day Off is selected, mark all slots as day-off-occupied
                if (selectedEventType === '10' || window.selectedEventType === '10') {
                    markAllTimeSlotsOccupied();
                }
            }

