            function parseDurationInput(input) {
                console.log('parseDurationInput called with:', input, 'type:', typeof input);
                
                if (!input || typeof input !== 'string') {
                    console.log('parseDurationInput: returning null - invalid input');
                    return null;
                }
                
                const value = input.trim().toLowerCase();
                console.log('parseDurationInput: cleaned value:', value);
                console.log('parseDurationInput: value length:', value.length);
                console.log('parseDurationInput: value char codes:', Array.from(value).map(c => c.charCodeAt(0)));
                
                // Handle direct minute values (e.g., "60", "90")
                const directMinutesTest = /^\d+$/.test(value);
                console.log('parseDurationInput: testing direct minutes regex on "' + value + '":', directMinutesTest);
                console.log('parseDurationInput: regex test with manual check:', value.match(/^\d+$/));
                
                // Try alternative approach - check if all characters are digits
                const isAllDigits = value.split('').every(c => c >= '0' && c <= '9');
                console.log('parseDurationInput: manual digit check:', isAllDigits);
                
                if (directMinutesTest || isAllDigits) {
                    const minutes = parseInt(value);
                    console.log('parseDurationInput: direct minutes match, parsed:', minutes);
                    const result = minutes > 0 ? minutes : null;
                    console.log('parseDurationInput: returning result:', result);
                    return result;
                }
                
                // Handle hour formats (e.g., "1h", "1.5h", "2h") - must have 'h' suffix
                const hourMatch = value.match(/^(\d+(?:\.\d+)?)h$/);
                if (hourMatch) {
                    const hours = parseFloat(hourMatch[1]);
                    const result = hours > 0 ? Math.round(hours * 60) : null;
                    console.log('parseDurationInput: hour format match, hours:', hours, 'result:', result);
                    return result;
                }
                
                // Handle hour:minute formats (e.g., "1:30", "2:15")
                const timeMatch = value.match(/^(\d+):(\d{2})$/);
                if (timeMatch) {
                    const hours = parseInt(timeMatch[1]);
                    const minutes = parseInt(timeMatch[2]);
                    if (minutes >= 0 && minutes < 60) {
                        console.log('parseDurationInput: time format match, returning:', hours * 60 + minutes);
                        return hours * 60 + minutes;
                    }
                }
                
                console.log('parseDurationInput: no match found, returning null for input:', input);
                return null;
            }

