            function initializeAppointmentTextarea() {
                const textarea = document.getElementById('appointmentTitle');
                if (textarea) {
                    const maxHeight = 155; // 155px
                    
                    // Function to auto-resize textarea
                    function autoResize() {
                        // Reset height to auto to get the actual scroll height
                        textarea.style.height = 'auto';
                        
                        // Calculate the new height
                        const newHeight = Math.min(textarea.scrollHeight, maxHeight);
                        textarea.style.height = newHeight + 'px';
                        
                        // If content exceeds max height, ensure scrollbar is visible
                        if (textarea.scrollHeight > maxHeight) {
                            textarea.style.overflowY = 'auto';
                        } else {
                            textarea.style.overflowY = 'hidden';
                        }
                    }
                    
                    // Add event listeners
                    textarea.addEventListener('input', autoResize);
                    textarea.addEventListener('paste', function() {
                        // Use setTimeout to ensure the paste content is processed
                        setTimeout(autoResize, 0);
                    });
                    
                    // Initial resize in case there's existing content
                    autoResize();
                    
                    console.log('Appointment textarea auto-resize with scrollbar initialized');
                }
            }

