            function updateQuickActionLinks(customerId) {
                // Note: cabinetBuild (216) and counterBuild (214) are separate scripts, not this script
                // They use their own script IDs which should be consistent across environments
                const baseUrls = {
                    cabinetBuild: '${baseUrl}.app.netsuite.com/app/site/hosting/scriptlet.nl?script=216&deploy=1&compid=${companyId}',
                    counterBuild: '${baseUrl}.app.netsuite.com/app/site/hosting/scriptlet.nl?script=214&deploy=1&compid=${companyId}',
                    productEstimate: '${baseUrl}.app.netsuite.com/app/accounting/transactions/estimate.nl?compid=${companyId}',
                    lightBuild: '${baseUrl}.app.netsuite.com/app/common/custom/custrecordentry.nl?rectype=289&compid=${companyId}'
                };
                
                const cabinetBuildBtn = document.getElementById('cabinetBuildBtn');
                const counterBuildBtn = document.getElementById('counterBuildBtn');
                const productEstimateBtn = document.getElementById('productEstimateBtn');
                const lightBuildBtn = document.getElementById('lightBuildBtn');
                const measuringEventBtn = document.getElementById('measuringEventBtn');

                if (customerId) {
                    // Update button click handlers with customer ID
                    if (cabinetBuildBtn) {
                        cabinetBuildBtn.onclick = function() {
                            window.open(baseUrls.cabinetBuild + '&customer=' + customerId, '_blank');
                        };
                    }
                    if (counterBuildBtn) {
                        counterBuildBtn.onclick = function() {
                            window.open(baseUrls.counterBuild + '&customer=' + customerId, '_blank');
                        };
                    }
                    if (productEstimateBtn) {
                        productEstimateBtn.onclick = function() {
                            window.open(baseUrls.productEstimate + '&customer=' + customerId, '_blank');
                        };
                    }
                    if (lightBuildBtn) {
                        lightBuildBtn.onclick = function() {
                            window.open(baseUrls.lightBuild + '&customer=' + customerId, '_blank');
                        };
                    }
                    if (measuringEventBtn) {
                        measuringEventBtn.onclick = async function() {
                            try {
                                // First check if customer has valid billing ZIP
                                const checkUrl = new URL(window.location.href);
                                checkUrl.searchParams.set('action', 'checkCustomerBillingZip');
                                checkUrl.searchParams.set('customerId', customerId);

                                const checkResponse = await fetch(checkUrl.toString(), {
                                    method: 'POST',
                                    headers: {
                                        'Content-Type': 'application/x-www-form-urlencoded'
                                    }
                                });

                                const checkResult = await checkResponse.json();

                                if (!checkResult.success) {
                                    alert('Error validating customer address: ' + (checkResult.error || 'Unknown error'));
                                    return;
                                }

                                if (!checkResult.hasValidZip) {
                                    alert('Customer does not have a valid billing address. Please ensure there is a complete billing address before creating a Measuring Event.');
                                    return;
                                }

                                // Get the measuring event URL from server
                                const urlRequestUrl = new URL(window.location.href);
                                urlRequestUrl.searchParams.set('action', 'getMeasuringEventUrl');
                                urlRequestUrl.searchParams.set('customerId', customerId);

                                const urlResponse = await fetch(urlRequestUrl.toString(), {
                                    method: 'POST',
                                    headers: {
                                        'Content-Type': 'application/x-www-form-urlencoded'
                                    }
                                });

                                const urlResult = await urlResponse.json();

                                if (urlResult.success && urlResult.url) {
                                    window.open(urlResult.url, '_blank');
                                } else {
                                    alert('Error opening measuring event: ' + (urlResult.error || 'Unknown error'));
                                }
                            } catch (error) {
                                console.error('Error creating measuring event:', error);
                                alert('An error occurred while creating the measuring event.');
                            }
                        };
                    }
                } else {
                    // Reset button click handlers
                    if (cabinetBuildBtn) cabinetBuildBtn.onclick = null;
                    if (counterBuildBtn) counterBuildBtn.onclick = null;
                    if (productEstimateBtn) productEstimateBtn.onclick = null;
                    if (lightBuildBtn) lightBuildBtn.onclick = null;
                    if (measuringEventBtn) measuringEventBtn.onclick = null;
                }
            }
            
            function updateAppointmentModalEventType() {
                console.log('=== UPDATE APPOINTMENT MODAL EVENT TYPE ===');
                console.log('selectedEventType:', selectedEventType);
                console.log('typeof selectedEventType:', typeof selectedEventType);
                console.log('window.selectedEventType:', window.selectedEventType);
                console.log('window.selectedOrderEstimate:', window.selectedOrderEstimate);

                // Use window.selectedEventType as fallback if local variable is null
                const eventTypeToUse = selectedEventType || window.selectedEventType;
                console.log('eventTypeToUse (fallback logic):', eventTypeToUse);

                const eventTypeDisplay = document.getElementById('selectedEventTypeDisplay');
                console.log('selectedEventTypeDisplay element found:', !!eventTypeDisplay);

                if (eventTypeDisplay) {
                    console.log('Current eventTypeDisplay.textContent:', eventTypeDisplay.textContent);
                } else {
                    console.log('ERROR: selectedEventTypeDisplay element not found in DOM');

                    // Let's check if the modal is properly rendered
                    const modal = document.getElementById('addAppointmentModal');
                    console.log('addAppointmentModal found:', !!modal);
                    if (modal) {
                        console.log('Modal display style:', modal.style.display);
                        const modalBody = modal.querySelector('.modal-body');
                        console.log('Modal body found:', !!modalBody);
                    }
                    return;
                }

                if (eventTypeToUse) {
                    console.log('Processing eventTypeToUse:', eventTypeToUse);

                    // Map event type ID to name
                    const eventTypeNames = {
                        '1': 'Sold Order',
                        '4': 'Unsold - VIP',
                        '12': 'Non Customer Event',
                        '13': 'Unsold - Kitchen',
                        '14': 'Unsold - Bath',
                        '15': 'Unsold - Client Service Kitchen',
                        '16': 'Unsold - Client Service Bath',
                        '17': 'Unsold - Other'
                    };

                    let displayText = eventTypeNames[eventTypeToUse];
                    console.log('Mapped event type name:', displayText);

                    if (!displayText) {
                        displayText = 'Unknown Event Type (ID: ' + eventTypeToUse + ')';
                        console.log('Unknown event type, using fallback:', displayText);
                    }

                    // Add selected order/estimate ID if available
                    if (window.selectedOrderEstimate && window.selectedOrderEstimate.tranid) {
                        displayText += ' - #' + window.selectedOrderEstimate.tranid;
                        console.log('Added order/estimate ID, final text:', displayText);
                    }

                    console.log('Setting eventTypeDisplay.textContent to:', displayText);
                    eventTypeDisplay.textContent = displayText;
                    console.log('After setting, eventTypeDisplay.textContent is:', eventTypeDisplay.textContent);
                } else {
                    console.log('No selectedEventType, setting default text');
                    eventTypeDisplay.textContent = 'No event type selected';
                    console.log('Set default text, eventTypeDisplay.textContent is:', eventTypeDisplay.textContent);
                }

                console.log('=== END UPDATE APPOINTMENT MODAL EVENT TYPE ===');
            }

            function loadCustomerOrdersEstimates() {
                if (!selectedCustomer || !selectedEventType) return;
                
                const loadingElement = document.getElementById('ordersEstimatesLoading');
                const listElement = document.getElementById('ordersEstimatesList');
                const emptyElement = document.getElementById('ordersEstimatesEmpty');
                const titleElement = document.getElementById('ordersEstimatesTitle');
                
                // Show loading state
                if (loadingElement) loadingElement.style.display = 'block';
                if (listElement) listElement.style.display = 'none';
                if (emptyElement) emptyElement.style.display = 'none';
                
                // Update title based on event type
                const isSoldOrder = selectedEventType === '1';
                if (titleElement) {
                    titleElement.textContent = isSoldOrder ? 'Customer Sales Orders' : 'Customer Estimates';
                }
                
                // Fetch data from server
                const currentUrl = new URL(window.location.href);
                currentUrl.searchParams.set('action', 'getCustomerOrdersEstimates');
                
                fetch(currentUrl.toString(), {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({
                        customerId: selectedCustomer.id,
                        recordType: isSoldOrder ? 'salesorder' : 'estimate'
                    })
                })
                .then(response => response.json())
                .then(data => {
                    // Hide loading
                    if (loadingElement) loadingElement.style.display = 'none';
                    
                    if (data.success && data.records && data.records.length > 0) {
                        displayOrdersEstimates(data.records, isSoldOrder);
                    } else {
                        // Show empty message
                        if (emptyElement) {
                            emptyElement.textContent = isSoldOrder ? 
                                'No sales orders found for this customer.' : 
                                'No estimates found for this customer.';
                            emptyElement.style.display = 'block';
                        }
                    }
                })
                .catch(error => {
                    console.error('Error loading customer records:', error);
                    // Hide loading and show empty message
                    if (loadingElement) loadingElement.style.display = 'none';
                    if (emptyElement) {
                        emptyElement.textContent = 'Error loading customer records. Please try again.';
                        emptyElement.style.display = 'block';
                    }
                });
            }
            
            // Track the last loaded record type to avoid unnecessary reloads
            let lastLoadedRecordType = null;
            let lastLoadedCustomerId = null;
            let lastLoadedIsClientService = null;
            
            function loadCustomerOrdersEstimatesInEventModal() {
                if (!selectedCustomer || !selectedEventType) {
                    console.log('Cannot load orders/estimates:', {
                        hasCustomer: !!selectedCustomer,
                        hasEventType: !!selectedEventType,
                        customer: selectedCustomer,
                        eventType: selectedEventType
                    });
                    return;
                }

                // In special modes with restricted transactions, we still need to display the specific transaction
                // Only skip loading additional transactions from the server, but still show the transaction section
                // The logic below handles displaying the specific transaction for these modes
                
                const loadingDiv = document.getElementById('eventTypeOrdersEstimatesLoading');
                const listDiv = document.getElementById('eventTypeOrdersEstimatesList');
                const sectionDiv = document.getElementById('eventTypeOrdersEstimatesSection');
                const titleDiv = document.getElementById('eventTypeOrdersEstimatesTitle');
                
                if (!loadingDiv || !listDiv || !sectionDiv) {
                    console.log('Missing DOM elements for orders/estimates');
                    return;
                }

                // Special Mode: Skip fetching and display the specific transaction
                if (isSpecialMode && !modeConfig.allowAllTransactions && modeConfig.recordData) {
                    const recordData = modeConfig.recordData;
                    const modeDisplayName = getModeDisplayName(currentMode, recordData);
                    console.log(currentMode.toUpperCase() + ' Mode: Displaying ' + modeDisplayName + ' as the transaction instead of fetching orders/estimates');

                    // Show the section and set title
                    sectionDiv.style.display = 'block';
                    if (titleDiv) {
                        titleDiv.textContent = modeDisplayName;
                    }

                    // Hide loading and the default order table
                    loadingDiv.style.display = 'none';
                    const defaultOrderTable = document.querySelector('.order-table-container');
                    if (defaultOrderTable) {
                        defaultOrderTable.style.display = 'none';
                    }

                    // Check if Client Service event type is selected (15 = Client Service Kitchen, 16 = Client Service Bath)
                    const isClientServiceEventType = selectedEventType === '15' || selectedEventType === '16';
                    console.log('Special Mode - Event type:', selectedEventType, 'isClientService:', isClientServiceEventType);

                    // Remove any existing special mode table
                    const existingSpecialTable = sectionDiv.querySelector('.special-mode-table-container');
                    if (existingSpecialTable) {
                        existingSpecialTable.remove();
                    }

                    // Create table HTML with a dedicated container
                    const tableHtml =
                        '<div class="special-mode-table-container">' +
                            '<table class="orders-estimates-table">' +
                                '<thead>' +
                                    '<tr>' +
                                        '<th>Record Type</th>' +
                                        '<th>ID</th>' +
                                        '<th>Title</th>' +
                                        '<th>Customer</th>' +
                                        (isClientServiceEventType ? '<th>Referred Customer</th>' : '') +
                                    '</tr>' +
                                '</thead>' +
                                '<tbody>' +
                                    '<tr class="order-estimate-row clickable-row" data-transaction-id="' + recordData.id + '" data-record-type="' + recordData.recordType + '" style="cursor: pointer;">' +
                                        '<td>' + getRecordTypeBadge(currentMode, recordData) + '</td>' +
                                        '<td class="record-id">' + recordData.id + '</td>' +
                                        '<td class="record-title">' + (recordData.title || modeDisplayName) + '</td>' +
                                        '<td class="customer-name">' + recordData.customer.displayName + '</td>' +
                                        (isClientServiceEventType ? '<td class="crd-end-user">' + (recordData.crdenduser || '-') + '</td>' : '') +
                                    '</tr>' +
                                '</tbody>' +
                            '</table>' +
                        '</div>';

                    // Insert the new table into the results container
                    const resultsContainer = sectionDiv.querySelector('.orders-estimates-results-container');
                    if (resultsContainer) {
                        resultsContainer.insertAdjacentHTML('beforeend', tableHtml);
                    }

                    // Add the same click handlers as normal transactions
                    const transactionRow = sectionDiv.querySelector('.order-estimate-row');
                    if (transactionRow) {
                        const listContainer = transactionRow.closest('tbody');

                        // Add click handler with same logic as normal transactions
                        transactionRow.addEventListener('click', function() {
                            const isCurrentlySelected = this.classList.contains('selected');
                            if (isCurrentlySelected) {
                                // Unselect: Remove selection from this item
                                this.classList.remove('selected');
                                // Remove selection indicator
                                const existingIndicator = this.querySelector('.selection-indicator');
                                if (existingIndicator) {
                                    existingIndicator.remove();
                                }
                                // Clear selected record
                                window.selectedOrderEstimate = null;
                                // Disable next button
                                const nextBtn = document.getElementById('nextToAppointmentSchedulingBtn');
                                if (nextBtn) {
                                    nextBtn.disabled = true;
                                }
                                console.log('Unselected RFQ');
                            } else {
                                // Select: Remove selected class from all items and remove any existing selection indicators
                                listContainer.querySelectorAll('.order-estimate-row').forEach(item => {
                                    item.classList.remove('selected');
                                    // Remove any existing selection indicators
                                    const existingIndicator = item.querySelector('.selection-indicator');
                                    if (existingIndicator) {
                                        existingIndicator.remove();
                                    }
                                });
                                // Add selected class to clicked item
                                this.classList.add('selected');
                                // Add green checkmark emoji to the first cell (Order # column)
                                const firstCell = this.querySelector('td:first-child');
                                if (firstCell) {
                                    const indicator = document.createElement('span');
                                    indicator.className = 'selection-indicator';
                                    indicator.style.cssText = 'color: #065f46; font-weight: 600; margin-left: 0.5rem; font-size: 0.875rem;';
                                    indicator.textContent = '✅';
                                    firstCell.appendChild(indicator);
                                }
                                // Store selected record for later use
                                window.selectedOrderEstimate = {
                                    id: recordData.id,
                                    tranid: recordData.tranid || recordData.id,
                                    type: recordData.recordType,
                                    amount: recordData.amount || 0,
                                    status: recordData.status || (currentMode.toUpperCase() + ' RECORD'),
                                    trandate: recordData.trandate || null,
                                    jobid: null,
                                    crdenduser: recordData.crdenduser || null
                                };
                                // Enable next button
                                const nextBtn = document.getElementById('nextToAppointmentSchedulingBtn');
                                if (nextBtn) {
                                    nextBtn.disabled = false;
                                    nextBtn.style.display = 'inline-flex';
                                }
                                console.log('Selected ' + currentMode.toUpperCase() + ':', recordData);
                            }
                        });

                        // Auto-select the transaction
                        setTimeout(() => {
                            transactionRow.click();
                        }, 100);
                    }

                    return; // Skip the rest of the function
                }

                // Determine record type based on event type
                const recordType = selectedEventType === '1' ? 'salesorder' : 'estimate';
                const customerId = selectedCustomer.id || selectedCustomer.entityId;
                
                // For unsold event types (estimates), only show open estimates
                let statusFilter = null;
                if (recordType === 'estimate') {
                    // NetSuite estimate status values for "open" estimates
                    // Based on NetSuite standard estimate statuses, "Open" is "Estimate:A"
                    // Using NetSuite internal status format for proper filtering
                    statusFilter = ['Estimate:A']; // Open status for estimates
                    
                    console.log('Applying Open status filter for estimates:', statusFilter);
                }
                
                // Check if we need to reload data
                // Also reload when switching between Client Service and non-Client Service event types
                const isClientServiceEventType = selectedEventType === '15' || selectedEventType === '16';
                const needsReload = lastLoadedRecordType !== recordType || lastLoadedCustomerId !== customerId || lastLoadedIsClientService !== isClientServiceEventType;

                // Always show section and update title
                sectionDiv.style.display = 'block';
                
                // Update title based on event type
                if (titleDiv) {
                    if (selectedEventType === '1') {
                        titleDiv.textContent = 'Customer Sales Orders';
                    } else {
                        titleDiv.textContent = 'Customer Estimates';
                    }
                }
                
                // If we don't need to reload, just return (keep existing data)
                if (!needsReload) {
                    console.log('Skipping reload - same record type:', recordType);
                    return;
                }
                
                // Show loading state and clear existing data
                loadingDiv.style.display = 'block';
                listDiv.innerHTML = '';
                
                console.log('Loading new record type:', recordType, 'Previous:', lastLoadedRecordType);
                const requestData = {
                    customerId: customerId,
                    recordType: recordType,
                    statusFilter: statusFilter
                };
                
                console.log('Loading orders/estimates with request data:', {
                    requestData: requestData,
                    selectedCustomer: selectedCustomer,
                    eventType: selectedEventType,
                    statusFilter: statusFilter
                });
                
                const requestBody = {
                    action: 'getCustomerOrdersEstimates',
                    ...requestData
                };
                
                console.log('Sending request:', {
                    url: window.location.href,
                    method: 'POST',
                    body: requestBody
                });
                
                fetch(window.location.href, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(requestBody)
                })
                .then(response => response.json())
                .then(data => {
                    loadingDiv.style.display = 'none';
                    
                    console.log('Orders/Estimates response:', {
                        success: data.success,
                        recordCount: data.records ? data.records.length : 0,
                        records: data.records,
                        error: data.error
                    });
                    
                    if (data.success && data.records && data.records.length > 0) {
                        displayOrdersEstimatesSearchList(data.records, listDiv, customerId);
                        // Update tracking variables on successful load
                        lastLoadedRecordType = recordType;
                        lastLoadedCustomerId = customerId;
                        lastLoadedIsClientService = isClientServiceEventType;
                    } else {
                        const message = data.error || 'No ' + (recordType === 'salesorder' ? 'sales orders' : 'estimates') + ' found for this customer.';
                        listDiv.innerHTML = '<div class="orders-estimates-no-records">' + message + '</div>';
                        // Update tracking variables even for empty results (successful request)
                        if (data.success) {
                            lastLoadedRecordType = recordType;
                            lastLoadedCustomerId = customerId;
                            lastLoadedIsClientService = isClientServiceEventType;
                        }
                    }
                })
                .catch(error => {
                    console.error('Error loading orders/estimates:', error);
                    loadingDiv.style.display = 'none';
                    listDiv.innerHTML = '<div class="orders-estimates-no-records">Error loading records. Please try again.</div>';
                });
            }
            
            function displayOrdersEstimatesSearchList(records, listContainer, selectedCustomerId) {
                if (!listContainer || !records) return;

                listContainer.innerHTML = '';

                // Filter records based on event type for Client Service
                // Event types 15 (Unsold - Client Service Kitchen) and 16 (Unsold - Client Service Bath)
                // should only show records WITH a CRD Client Service value
                // Other event types should only show records WITHOUT a CRD Client Service value
                const isClientServiceEventType = selectedEventType === '15' || selectedEventType === '16';

                const filteredRecords = records.filter(record => {
                    const hasCrdClientService = record.crdcourtesyservice || record.crdcourtesyserviceid;

                    if (isClientServiceEventType) {
                        // Client Service event types: only show records WITH CRD Client Service
                        return hasCrdClientService;
                    } else {
                        // Non-Client Service event types: only show records WITHOUT CRD Client Service
                        return !hasCrdClientService;
                    }
                });

                console.log('Filtering records for event type ' + selectedEventType + ' (isClientService: ' + isClientServiceEventType + '): ' + records.length + ' -> ' + filteredRecords.length);

                // Show message if no records match the filter
                if (filteredRecords.length === 0 && records.length > 0) {
                    const message = isClientServiceEventType
                        ? 'No Client Service estimates found for this customer.'
                        : 'No estimates found for this customer.';
                    listContainer.innerHTML = '<tr><td colspan="7" class="orders-estimates-no-records" style="text-align: center; padding: 1rem; color: #6b7280;">' + message + '</td></tr>';
                    return;
                }

                filteredRecords.forEach(record => {
                    const itemRow = document.createElement('tr');
                    itemRow.className = 'order-estimate-search-item';
                    itemRow.dataset.recordId = record.id;
                    itemRow.dataset.recordType = record.type || 'unknown';
                    
                    // Format status class
                    const statusClass = (record.status || 'unknown').toLowerCase().replace(/\s+/g, '-');
                    
                    // Determine CRD Client Service value:
                    // If selected customer is the main entity, show referred_by_customer name
                    // If selected customer is the referred_by_customer, show the entity name
                    // Strip leading customer number (e.g., "145816 Gibscrd" -> "Gibscrd")
                    function stripCustomerNumber(name) {
                        if (!name) return '';
                        // Remove leading numbers and space (e.g., "145816 Name" -> "Name")
                        return name.replace(/^\\d+\\s+/, '');
                    }

                    let crdCourtesyServiceDisplay = '-';
                    let crdCustomerId = null;
                    if (selectedCustomerId && record.entityid && String(record.entityid) === String(selectedCustomerId)) {
                        // Selected customer is the main entity, show referred_by_customer
                        if (record.crdcourtesyservice) {
                            const displayName = stripCustomerNumber(record.crdcourtesyservice);
                            crdCustomerId = record.crdcourtesyserviceid;
                            crdCourtesyServiceDisplay = escapeForJS(displayName);
                        }
                    } else if (record.entityname) {
                        // Selected customer is the referred_by_customer, show entity name
                        const displayName = stripCustomerNumber(record.entityname);
                        crdCustomerId = record.entityid;
                        crdCourtesyServiceDisplay = escapeForJS(displayName);
                    }

                    // Build hyperlink if we have a customer ID
                    let crdCourtesyServiceHtml = '-';
                    if (crdCourtesyServiceDisplay && crdCourtesyServiceDisplay !== '-' && crdCustomerId) {
                        crdCourtesyServiceHtml = '<a href="/app/common/entity/custjob.nl?id=' + crdCustomerId + '" target="_blank" style="color: #2563eb; text-decoration: none;" onclick="event.stopPropagation();">' + crdCourtesyServiceDisplay + '</a>';
                    } else if (crdCourtesyServiceDisplay && crdCourtesyServiceDisplay !== '-') {
                        crdCourtesyServiceHtml = crdCourtesyServiceDisplay;
                    }
                    
                    // Build NetSuite URL for the transaction
                    const transactionType = (record.type || '').toLowerCase();
                    let transactionUrl = '';
                    if (transactionType === 'estimate') {
                        transactionUrl = '/app/accounting/transactions/estimate.nl?id=' + record.id;
                    } else if (transactionType === 'salesorder') {
                        transactionUrl = '/app/accounting/transactions/salesord.nl?id=' + record.id;
                    }

                    // Build Order # as hyperlink to transaction
                    let orderNumberHtml = escapeForJS(record.tranid || record.id);
                    if (transactionUrl) {
                        orderNumberHtml = '<a href="' + transactionUrl + '" target="_blank" style="color: #2563eb; text-decoration: none;" onclick="event.stopPropagation();">' + escapeForJS(record.tranid || record.id) + '</a>';
                    }

                    itemRow.innerHTML =
                        '<td class="order-estimate-search-number">' + orderNumberHtml + '</td>' +
                        '<td class="order-estimate-date">' + formatDate(record.trandate) + '</td>' +
                        '<td><span class="order-estimate-search-status ' + statusClass + '">' + escapeForJS(record.status || 'Unknown') + '</span></td>' +
                        '<td class="order-estimate-jobid">' + (record.jobid ? escapeForJS(record.jobid) : '-') + '</td>' +
                        '<td class="order-estimate-crduser">' + (record.crdenduser ? escapeForJS(record.crdenduser) : '-') + '</td>' +
                        '<td class="order-estimate-crdcourtesy">' + crdCourtesyServiceHtml + '</td>' +
                        '<td class="order-estimate-search-amount" style="text-align: right;">$' + formatCurrency(record.amount || 0) + '</td>';
                    
                    // Add click handler for selection with unselect capability
                    itemRow.addEventListener('click', function() {
                        const isCurrentlySelected = this.classList.contains('selected');

                        if (isCurrentlySelected) {
                            // Unselect: Remove selection from this item
                            this.classList.remove('selected');

                            // Remove selection indicator
                            const existingIndicator = this.querySelector('.selection-indicator');
                            if (existingIndicator) {
                                existingIndicator.remove();
                            }

                            // Clear selected record
                            window.selectedOrderEstimate = null;

                            // Disable next button
                            const nextBtn = document.getElementById('nextToAppointmentSchedulingBtn');
                            if (nextBtn) {
                                nextBtn.disabled = true;
                            }

                            console.log('Unselected order/estimate');
                        } else {
                            // Select: Remove selected class from all items and remove any existing selection indicators
                            listContainer.querySelectorAll('.order-estimate-search-item').forEach(item => {
                                item.classList.remove('selected');
                                // Remove any existing selection indicators
                                const existingIndicator = item.querySelector('.selection-indicator');
                                if (existingIndicator) {
                                    existingIndicator.remove();
                                }
                            });

                            // Add selected class to clicked item
                            this.classList.add('selected');

                            // Add green checkmark emoji to the first cell (Order # column)
                            const firstCell = this.querySelector('td:first-child');
                            if (firstCell) {
                                const indicator = document.createElement('span');
                                indicator.className = 'selection-indicator';
                                indicator.style.cssText = 'color: #065f46; font-weight: 600; margin-left: 0.5rem; font-size: 0.875rem;';
                                indicator.textContent = '✅';
                                firstCell.appendChild(indicator);
                            }

                            // Store selected record for later use
                            window.selectedOrderEstimate = {
                                id: record.id,
                                tranid: record.tranid || record.id,
                                type: record.type,
                                amount: record.amount || 0,
                                status: record.status,
                                trandate: record.trandate,
                                jobid: record.jobid,
                                crdenduser: record.crdenduser,
                                crdcourtesyservice: record.crdcourtesyservice,
                                crdcourtesyserviceid: record.crdcourtesyserviceid,
                                entityid: record.entityid,
                                entityname: record.entityname
                            };

                            // Enable next button
                            const nextBtn = document.getElementById('nextToAppointmentSchedulingBtn');
                            if (nextBtn) {
                                nextBtn.disabled = false;
                            }

                            console.log('Selected order/estimate:', record);
                        }
                    });
                    
                    listContainer.appendChild(itemRow);
                });
            }
            
            function displayOrdersEstimates(records, isSoldOrder) {
                const listElement = document.getElementById('ordersEstimatesList');
                if (!listElement) return;
                
                // Clear existing content
                listElement.innerHTML = '';
                
                records.forEach(record => {
                    const itemDiv = document.createElement('div');
                    itemDiv.className = 'order-estimate-item';
                    itemDiv.dataset.recordId = record.id;
                    
                    const statusClass = getStatusClass(record.status);
                    
                    itemDiv.innerHTML =
                        '<div class="order-estimate-header">' +
                            '<div class="order-estimate-number">' + escapeForJS(record.tranid || record.id) + '</div>' +
                            '<div class="order-estimate-amount">$' + formatCurrency(record.amount || 0) + '</div>' +
                        '</div>' +
                        '<div class="order-estimate-details">' +
                            '<div class="order-estimate-date">' + formatDate(record.trandate) + '</div>' +
                            '<div class="order-estimate-status ' + statusClass + '">' + escapeForJS(record.status || 'Unknown') + '</div>' +
                        '</div>';
                    
                    // Add click handler for selection with unselect capability
                    itemDiv.addEventListener('click', function() {
                        const isCurrentlySelected = this.classList.contains('selected');

                        if (isCurrentlySelected) {
                            // Unselect: Remove selection from this item
                            this.classList.remove('selected');

                            // Clear selected record
                            window.selectedOrderEstimate = null;

                            // Disable next button
                            const nextBtn = document.getElementById('nextToAppointmentSchedulingBtn');
                            if (nextBtn) {
                                nextBtn.disabled = true;
                            }

                            console.log('Unselected order/estimate');
                        } else {
                            // Select: Remove selection from other items
                            listElement.querySelectorAll('.order-estimate-item').forEach(item => {
                                item.classList.remove('selected');
                            });

                            // Add selection to this item
                            this.classList.add('selected');

                            // Store selected record for later use
                            window.selectedOrderEstimate = {
                                id: record.id,
                                tranid: record.tranid || record.id,
                                type: record.type,
                                amount: record.amount || 0,
                                status: record.status,
                                trandate: record.trandate,
                                jobid: record.jobid,
                                crdenduser: record.crdenduser,
                                crdcourtesyservice: record.crdcourtesyservice,
                                crdcourtesyserviceid: record.crdcourtesyserviceid,
                                entityid: record.entityid,
                                entityname: record.entityname
                            };

                            // Enable next button
                            const nextBtn = document.getElementById('nextToAppointmentSchedulingBtn');
                            if (nextBtn) {
                                nextBtn.disabled = false;
                            }

                            console.log('Selected record:', record);
                        }
                    });
                    
                    listElement.appendChild(itemDiv);
                });
                
                // Show the list
                listElement.style.display = 'block';
            }
            
            function getStatusClass(status) {
                if (!status) return '';
                
                const statusLower = status.toLowerCase();
                
                // Sales Order statuses
                if (statusLower.includes('pending approval')) return 'status-pending-approval';
                if (statusLower.includes('pending fulfillment')) return 'status-pending-fulfillment';
                if (statusLower.includes('billed')) return 'status-billed';
                if (statusLower.includes('closed')) return 'status-closed';
                
                // Estimate statuses
                if (statusLower.includes('open')) return 'status-open';
                if (statusLower.includes('sent')) return 'status-sent';
                if (statusLower.includes('expired')) return 'status-expired';
                if (statusLower.includes('closed')) return 'status-closed';
                
                return 'status-open'; // default
            }
            
            function formatCurrency(amount) {
                if (!amount) return '0.00';
                return parseFloat(amount).toLocaleString('en-US', {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2
                });
            }
            
            function formatDate(dateStr) {
                if (!dateStr) return '';
                try {
                    const date = new Date(dateStr);
                    return date.toLocaleDateString('en-US', {
                        year: 'numeric',
                        month: 'short',
                        day: 'numeric'
                    });
                } catch (e) {
                    return dateStr;
                }
            }

            function validateAppointmentForm() {
                const createButton = document.getElementById('createAppointmentBtn');
                if (createButton) {
                    // Get duration selection
                    const durationInput = document.getElementById('appointmentDuration');
                    const selectedDuration = durationInput ? parseDurationInput(durationInput.value) : null;

                    // Check if selected time slot is occupied (skip for Scheduled Day Off)
                    const selectedTimeSlot = document.querySelector('.time-slot.selected');
                    const isOccupiedSlot = selectedEventType !== '10' && selectedTimeSlot && selectedTimeSlot.classList.contains('occupied');

                    // Check if there are any duration conflicts (skip for Scheduled Day Off)
                    const hasConflicts = selectedEventType !== '10' && document.querySelectorAll('.time-slot.occupied.duration-conflict').length > 0;

                    // For Scheduled Day Off (type 10), skip time slot requirement
                    const timeRequirementMet = selectedEventType === '10' || selectedTime;

                    // Enable create button only if all required fields are selected AND time slot is not occupied AND no conflicts exist
                    if (appointmentModalSelectedDate && timeRequirementMet && selectedStore && selectedEventType && selectedDuration && !isOccupiedSlot && !hasConflicts) {
                        createButton.disabled = false;
                        createButton.style.opacity = '1';
                        createButton.title = 'Create appointment';
                    } else {
                        createButton.disabled = true;
                        createButton.style.opacity = '0.5';

                        if (isOccupiedSlot) {
                            createButton.title = 'Cannot create appointment - selected time slot is occupied';
                        } else if (hasConflicts) {
                            createButton.title = 'Cannot create appointment - selected duration overlaps with existing appointment';
                        } else {
                            createButton.title = 'Please fill in all required fields';
                        }
                    }
                }
            }

            // Flag to prevent duplicate appointment creation from rapid button clicks
            let isCreatingAppointment = false;

            /**
             * Pre-populates all appointment fields from duplicateAppointmentData (except date/time).
             *
             * This function is called when opening the Add Appointment Modal in duplicate mode.
             * It handles:
             * - Customer pre-selection
             * - Event type auto-selection (dynamic lookup)
             * - Transaction pre-population and restriction
             * - Salesperson pre-selection
             * - Store location auto-selection
             * - Duration and details pre-filling
             * - Graceful degradation if original data no longer available
             */
            function prePopulateAppointmentFields() {
                // Detect which mode we're in
                const isChangeMode = changeAppointmentData !== null;
                const isDuplicateMode = duplicateAppointmentData !== null;
                const sourceData = isChangeMode ? changeAppointmentData : duplicateAppointmentData;

                console.log('Pre-populating appointment fields in ' + (isChangeMode ? 'CHANGE' : 'duplicate') + ' mode');

                if (!sourceData) {
                    console.error('No appointment data found for pre-population');
                    return;
                }

                try {
                    // 1. Pre-populate Customer
                    if (sourceData.customerId && sourceData.customerName) {
                        selectedCustomer = {
                            id: sourceData.customerId,
                            name: sourceData.customerName,
                            displayName: sourceData.customerName,
                            email: sourceData.customerEmail || '',
                            phone: sourceData.customerPhone || '',
                            defaultaddress: sourceData.customerAddress || ''
                        };

                        // Update customer info display
                        updateSelectedCustomerInfo(selectedCustomer);
                        console.log('Customer pre-populated:', selectedCustomer.name);
                    }

                    // 2. Pre-select Event Type (dynamic lookup from event type name)
                    if (sourceData.eventTypeName) {
                        // Find event type ID by matching name
                        // This requires looking up event type buttons or using stored event type mapping

                        // Strategy 1: Try to find event type button by name
                        const eventTypeButtons = document.querySelectorAll('.event-type-btn:not(.disabled)');
                        let foundEventType = false;

                        for (let i = 0; i < eventTypeButtons.length; i++) {
                            const button = eventTypeButtons[i];
                            const buttonText = button.textContent.trim();

                            // Match event type name (exact or partial match)
                            if (buttonText === sourceData.eventTypeName ||
                                buttonText.includes(sourceData.eventTypeName) ||
                                sourceData.eventTypeName.includes(buttonText)) {

                                const eventTypeId = button.getAttribute('data-event-type');
                                if (eventTypeId) {
                                    selectedEventType = eventTypeId;
                                    updateAppointmentModalEventType();
                                    foundEventType = true;
                                    console.log('Event type pre-selected:', sourceData.eventTypeName, '(ID:' + eventTypeId + ')');
                                    break;
                                }
                            }
                        }

                        if (!foundEventType) {
                            console.warn('Event type "' + sourceData.eventTypeName + '" from original appointment no longer available');
                            // Fall back to manual selection - user will need to choose event type
                        }
                    }

                    // 3. Pre-populate Transaction (if exists)
                    if (sourceData.transactionId && sourceData.transactionType) {
                        // Validate transaction still exists
                        // For now, assume it exists and pre-populate
                        // Production code should call validateTransaction() here

                        window.selectedOrderEstimate = {
                            id: sourceData.transactionId,
                            tranid: sourceData.transactionText || sourceData.transactionId,
                            type: sourceData.transactionType,
                            total: 0,  // Unknown, not critical for duplicate
                            status: 'EXISTING TRANSACTION'
                        };

                        // Set transaction restriction
                        // This prevents user from changing the transaction
                        // (can be overridden by clicking "Edit Transaction" button if needed)
                        const restrictedTransactionId = sourceData.transactionId;

                        // Update transaction display in modal
                        const transactionDisplay = document.getElementById('selectedOrderEstimateInfo');
                        if (transactionDisplay) {
                            transactionDisplay.textContent = sourceData.transactionText;
                        }

                        console.log('Transaction pre-populated:', sourceData.transactionText);
                    }

                    // 4. Pre-select Salesperson
                    if (sourceData.salespersonName) {
                        // CRITICAL: Update global variables so all salesperson-dependent logic uses the correct ID
                        // This affects time slot blocking, appointment caching, and appointment creation
                        selectedSalespersonId = sourceData.salespersonId;
                        selectedSalespersonName = sourceData.salespersonName;

                        // Update salesperson display
                        const salespersonDisplay = document.getElementById('selectedSalespersonDisplay');
                        if (salespersonDisplay) {
                            salespersonDisplay.textContent = sourceData.salespersonName;

                            // Store salesperson ID in data attribute for form submission
                            if (sourceData.salespersonId) {
                                salespersonDisplay.setAttribute('data-user-id', sourceData.salespersonId);
                                salespersonDisplay.dataset.userId = sourceData.salespersonId;
                                console.log('Salesperson ID stored:', sourceData.salespersonId);
                            }
                        }

                        // Clear appointment cache since it was loaded for the wrong salesperson (current user)
                        console.log('Clearing appointment cache for salesperson change in ' + (isChangeMode ? 'change' : 'duplicate') + ' mode');
                        Object.keys(appointmentsCache).forEach(key => {
                            delete appointmentsCache[key];
                        });

                        // Restart preemptive caching for the correct salesperson
                        if (sourceData.salespersonId) {
                            console.log('Restarting preemptive caching for correct salesperson:', sourceData.salespersonId);
                            preloadSalespersonAppointments(sourceData.salespersonId);
                        }

                        console.log('Owner/Salesperson pre-selected:', sourceData.salespersonName, 'ID:', sourceData.salespersonId);
                    }

                    // 5. Pre-select Store Location
                    if (sourceData.storeLocation) {
                        // Find store location button by matching text
                        // Note: Store buttons use 'data-location-id' attribute (not 'data-store-location')
                        const storeButtons = document.querySelectorAll('.store-location-btn');
                        let foundStore = false;

                        for (let i = 0; i < storeButtons.length; i++) {
                            const button = storeButtons[i];
                            const buttonText = button.textContent.trim();

                            if (buttonText === sourceData.storeLocation) {
                                // Trigger button click to select store
                                // This will automatically call renderTimeSlots() with the updated selectedSalespersonId
                                button.click();
                                foundStore = true;
                                console.log('Store location pre-selected:', sourceData.storeLocation);
                                console.log('Time slots will be rendered with correct salesperson ID:', selectedSalespersonId);
                                break;
                            }
                        }

                        if (!foundStore) {
                            console.warn('Store location "' + sourceData.storeLocation + '" from original appointment no longer available');
                        }
                    }

                    // 6. Pre-fill Duration
                    if (sourceData.duration) {
                        const durationInput = document.getElementById('appointmentDuration');
                        if (durationInput) {
                            durationInput.value = sourceData.duration;
                            console.log('Duration pre-filled:', sourceData.duration + ' mins');
                        }
                    }

                    // 7. Pre-fill Appointment Details
                    console.log('Attempting to pre-fill appointment details:', sourceData.appointmentDetails);
                    const detailsTextarea = document.getElementById('appointmentTitle');
                    if (detailsTextarea) {
                        if (sourceData.appointmentDetails) {
                            detailsTextarea.value = sourceData.appointmentDetails;
                            console.log('Appointment details pre-filled:', sourceData.appointmentDetails);
                        } else {
                            console.log('No appointment details to pre-fill (value is empty or null)');
                        }
                    } else {
                        console.error('appointmentTitle textarea element not found');
                    }

                    // 8. Pre-populate Date and Time (smart defaulting for duplicate, exact for change)
                    if (sourceData.originalDate) {
                        console.log('Attempting to pre-populate date and time from:', sourceData.originalDate, sourceData.originalTime);

                        // Parse the original date (e.g., "Oct 15, 2025")
                        const originalDate = new Date(sourceData.originalDate);
                        const today = new Date();
                        today.setHours(0, 0, 0, 0);  // Set to start of day for comparison

                        // In change mode, use exact original date; in duplicate mode, use today if past
                        const dateToUse = isChangeMode ? originalDate : (originalDate < today ? new Date() : originalDate);

                        console.log('Original date:', originalDate, 'Today:', today, 'Using date:', dateToUse);

                        // Set the appointment date by calling selectAppointmentDate
                        // This will render time slots automatically
                        selectAppointmentDate(dateToUse);

                        // Pre-populate time after a delay to ensure time slots are rendered
                        if (sourceData.originalTime) {
                            setTimeout(function() {
                                // Extract start time from the time range (e.g., "1:30 pm - 2:30 pm" -> "1:30 pm")
                                const timeStr = sourceData.originalTime.split('-')[0].trim();
                                console.log('Attempting to select time slot:', timeStr);

                                // Find and click the matching time slot button
                                const timeSlots = document.querySelectorAll('.time-slot');
                                let foundTime = false;

                                for (let i = 0; i < timeSlots.length; i++) {
                                    const slot = timeSlots[i];
                                    const slotText = slot.textContent.trim().toUpperCase();
                                    const targetTime = timeStr.toUpperCase();

                                    // Match time slot (e.g., "1:30 PM" matches "1:30 pm")
                                    // In change mode, allow occupied slots (they're for the same appointment)
                                    if (slotText === targetTime && (!slot.disabled || (isChangeMode && slot.classList.contains('occupied')))) {
                                        slot.click();
                                        foundTime = true;
                                        console.log('Time slot pre-selected:', timeStr, isChangeMode ? '(change mode - original slot available)' : '');
                                        break;
                                    }
                                }

                                if (!foundTime) {
                                    console.warn('Time slot "' + timeStr + '" from original appointment not found or unavailable');
                                }
                            }, 500);  // Wait 500ms for time slots to render
                        }

                        console.log('Date and time pre-population initiated (mode: ' + (isChangeMode ? 'CHANGE' : 'duplicate') + ')');
                    } else {
                        console.log('No original date found, skipping date/time pre-population');
                    }

                } catch (error) {
                    console.error('Error pre-populating appointment fields:', error);
                    alert('Error loading duplicate appointment data. You can still create the appointment manually.');
                }
            }

            // Enhanced modal open function
            function openAddAppointmentModal() {
                console.log('Opening appointment modal with enhanced initialization');

                // Clear potentially stale cached data when opening modal
                clearStaleGlobalDataCache();

                // Clear all appointment cache to ensure fresh data for time slot blocking
                Object.keys(appointmentsCache).forEach(key => {
                    delete appointmentsCache[key];
                });
                console.log('Cleared appointment cache for modal opening');

                // Check for duplicate or change mode
                const isDuplicateMode = duplicateAppointmentData !== null;
                const isChangeMode = changeAppointmentData !== null;

                if (isChangeMode) {
                    console.log('Opening Add Appointment Modal in CHANGE mode', changeAppointmentData);
                    // Set exclusion ID for time slot rendering
                    window.excludeAppointmentIdForAvailability = changeAppointmentData.appointmentId;
                } else if (isDuplicateMode) {
                    console.log('Opening Add Appointment Modal in duplicate mode', duplicateAppointmentData);
                }

                const modal = document.getElementById('addAppointmentModal');
                if (modal) {
                    modal.style.display = 'block';

                    // Add appropriate background class based on mode
                    const urlParams = new URLSearchParams(window.location.search);
                    const hasUrlParams = urlParams.has('customerid') || urlParams.has('estimateid') || urlParams.has('salesorderid') || urlParams.has('taskid');

                    if (hasUrlParams) {
                        modal.classList.add('url-parameter-mode');
                        modal.classList.remove('customer-search-only');
                    } else if (typeof customerSearchOnly !== 'undefined' && customerSearchOnly) {
                        modal.classList.add('customer-search-only');
                        modal.classList.remove('url-parameter-mode');
                    } else {
                        modal.classList.remove('customer-search-only', 'url-parameter-mode');
                    }

                    // Reset selections (but preserve selectedEventType and selectedCustomer from previous modals)
                    selectedTime = null;
                    // Don't reset selectedStore - let initializeStoreLocations handle the default
                    // Don't reset selectedEventType here - it should carry over from event type modal

                    // In RFQ mode, ensure customer data is preserved
                    if (isSpecialMode && modeConfig.recordData && modeConfig.recordData.customer && !selectedCustomer) {
                        console.log(currentMode.toUpperCase() + ' Mode: Restoring customer data in openAddAppointmentModal');
                        selectedCustomer = modeConfig.recordData.customer;
                    }

                    // Update customer display if we have a selected customer (important for RFQ mode)
                    if (selectedCustomer) {
                        console.log('Updating customer display in appointment modal:', selectedCustomer);
                        updateSelectedCustomerInfo(selectedCustomer);
                    } else {
                        console.log('WARNING: No selectedCustomer found in openAddAppointmentModal');
                    }

                    // For regular workflow (with customer), ensure inline buttons are hidden and text display is shown
                    if (selectedCustomer) {
                        hideNonCustomerEventTypeButtons();
                    }
                    // Note: For non-customer workflow, showNonCustomerEventTypeButtons() is called after openAddAppointmentModal()

                    // Initialize default salesperson if not already set
                    if (!selectedSalespersonId) {
                        const salespersonDisplay = document.getElementById('selectedSalespersonDisplay');
                        selectedSalespersonId = salespersonDisplay ? salespersonDisplay.getAttribute('data-user-id') : null;
                        selectedSalespersonName = '${currentUserName}';

                        // Set the data attribute for the display element
                        const selectedSalespersonElement = document.getElementById('selectedSalespersonDisplay');
                        if (selectedSalespersonElement) {
                            selectedSalespersonElement.dataset.userId = selectedSalespersonId;
                        }
                    }

                    // Reset duration selection
                    const durationInput = document.getElementById('appointmentDuration');
                    if (durationInput) {
                        durationInput.value = '60'; // Default to 1 hour
                    }

                    // Set current date to today and select it
                    const today = new Date();
                    appointmentModalCurrentDate = new Date(today);
                    appointmentModalSelectedDate = new Date(today);

                    console.log('Setting today as selected date:', appointmentModalSelectedDate);

                    // Render calendar with today selected
                    renderCalendar();

                    // Initialize time slots for today with selected location and current salesperson
                    const selectedStoreName = getStoreNameById(selectedStore);
                    renderTimeSlots(appointmentModalSelectedDate, selectedStoreName, selectedSalespersonId);
                    
                    // Reset the form (but preserve store location default)
                    resetAppointmentForm();
                    
                    // Initialize store locations with default selection
                    console.log('Initializing store locations with user location:', userLocation);
                    initializeStoreLocations();
                    
                    // Initialize auto-growing textarea
                    initializeAppointmentTextarea();
                    
                    // Start preemptive caching for the selected salesperson
                    const selectedSalespersonElement = document.querySelector('#selectedSalespersonDisplay');
                    const currentSalespersonId = selectedSalespersonElement ? selectedSalespersonElement.dataset.userId : null;
                    
                    if (currentSalespersonId) {
                        console.log('Starting preemptive caching for salesperson:', currentSalespersonId);
                        preloadSalespersonAppointments(currentSalespersonId);
                    } else {
                        console.log('No salesperson ID found, skipping preemptive caching');
                    }

                    // Pre-populate fields if in duplicate or change mode
                    if (isDuplicateMode || isChangeMode) {
                        // Delay pre-population to ensure modal is fully rendered
                        setTimeout(function() {
                            prePopulateAppointmentFields();
                        }, 200);
                    }

                    console.log('Appointment modal initialization complete');
                }
            }

            // Create appointment from modal
            function createAppointmentFromModal() {
                // Prevent duplicate submissions from rapid clicks
                if (isCreatingAppointment) {
                    console.log('Appointment creation already in progress, ignoring duplicate click');
                    return;
                }

                // Validate required fields (skip time check for Scheduled Day Off)
                if (!appointmentModalSelectedDate || !selectedStore || !selectedEventType) {
                    alert('Please select a date, store location, and event type.');
                    return;
                }
                if (selectedEventType !== '10' && !selectedTime) {
                    alert('Please select a time slot.');
                    return;
                }

                // For Scheduled Day Off, default to 8:30 AM start time
                var effectiveTime = selectedTime;
                if (selectedEventType === '10' && !selectedTime) {
                    effectiveTime = '08:30';
                }

                // Customer is required for all event types except "Non Customer Event" (type 12) and "Scheduled Day Off" (type 10)
                if (selectedEventType !== '12' && selectedEventType !== '10' && !selectedCustomer) {
                    alert('No customer selected. Please go back and select a customer.');
                    return;
                }

                // Get and validate duration
                const durationInput = document.getElementById('appointmentDuration');
                const selectedDuration = parseDurationInput(durationInput.value);

                if (!selectedDuration) {
                    alert('Please select an appointment duration.');
                    return;
                }

                // Get appointment title from form input
                const titleInput = document.getElementById('appointmentTitle');
                const appointmentTitle = titleInput ? titleInput.value.trim() : '';

                // Create default title if none provided
                var finalTitle;
                if (appointmentTitle) {
                    finalTitle = appointmentTitle;
                } else if (selectedEventType === '12') {
                    finalTitle = 'Non Customer Event';
                } else if (selectedEventType === '10') {
                    finalTitle = 'Scheduled Day Off';
                } else {
                    finalTitle = selectedCustomer ? (selectedCustomer.displayName || selectedCustomer.name) + ' - Appointment' : 'Appointment';
                }

                // Format date for NetSuite
                const formattedDate = formatDateForNetSuite(appointmentModalSelectedDate);

                // Calculate end time based on selected duration
                const endTime = calculateEndTime(effectiveTime, selectedDuration);
                
                console.log('Creating appointment:', {
                    date: formattedDate,
                    startTime: effectiveTime,
                    endTime: endTime,
                    duration: selectedDuration + ' minutes',
                    store: selectedStore,
                    eventType: selectedEventType,
                    title: finalTitle,
                    customer: selectedCustomer
                });

                // Set flag to prevent duplicate submissions
                isCreatingAppointment = true;

                // Disable the create button to prevent double-submission
                const createButton = document.getElementById('createAppointmentBtn');
                if (createButton) {
                    createButton.disabled = true;
                    createButton.textContent = 'Creating...';
                    createButton.style.pointerEvents = 'none';
                }

                // Show modal-specific loading overlay
                const loadingOverlay = document.getElementById('appointmentModalLoadingOverlay');
                if (loadingOverlay) {
                    loadingOverlay.style.display = 'flex';
                }

                // For Client Service appointments (event types 15 and 16), we need to use the estimate's entity
                // as the customer so the transaction can be linked. The end customer is stored separately for SMS.
                const isClientServiceEventType = selectedEventType === '15' || selectedEventType === '16';
                let eventCustomerId = selectedCustomer ? selectedCustomer.id : '';
                let eventCustomerName = selectedCustomer ? (selectedCustomer.displayName || selectedCustomer.name) : '';
                let endCustomerId = ''; // For SMS - the actual end customer
                let endCustomerName = '';

                // For Client Service, use the estimate's entity as the event customer
                if (isClientServiceEventType && window.selectedOrderEstimate && window.selectedOrderEstimate.entityid) {
                    console.log('Client Service appointment - using estimate entity as customer');
                    endCustomerId = selectedCustomer ? selectedCustomer.id : ''; // Store end customer for SMS
                    endCustomerName = selectedCustomer ? (selectedCustomer.displayName || selectedCustomer.name) : '';
                    eventCustomerId = window.selectedOrderEstimate.entityid; // Use CRD contractor
                    eventCustomerName = window.selectedOrderEstimate.entityname || eventCustomerId;
                    console.log('Client Service - eventCustomerId (CRD):', eventCustomerId, 'endCustomerId:', endCustomerId);
                }

                // Build request data
                const fields = {
                    'title': finalTitle,
                    'appointmentDate': formattedDate,
                    'startTime': effectiveTime,
                    'endTime': endTime,
                    'duration': selectedDuration,
                    'storeLocation': selectedStore,
                    'eventType': selectedEventType,
                    'customerId': eventCustomerId,
                    'customerName': eventCustomerName,
                    'salespersonId': selectedSalespersonId || (document.getElementById('selectedSalespersonDisplay') ? document.getElementById('selectedSalespersonDisplay').getAttribute('data-user-id') : null),
                    'salespersonName': selectedSalespersonName || '${currentUserName}'
                };

                // For Client Service, add the end customer info for SMS notifications
                if (isClientServiceEventType && endCustomerId) {
                    fields['endCustomerId'] = endCustomerId;
                    fields['endCustomerName'] = endCustomerName;
                    console.log('Client Service - added endCustomerId for SMS:', endCustomerId);
                }

                // Add transaction ID if a sales order or estimate is selected
                console.log('DEBUG - window.selectedOrderEstimate at form submission:', window.selectedOrderEstimate);
                if (window.selectedOrderEstimate && window.selectedOrderEstimate.id) {
                    fields['transactionId'] = window.selectedOrderEstimate.id;
                    console.log('DEBUG - Added transactionId to fields:', window.selectedOrderEstimate.id);
                } else {
                    console.log('DEBUG - No transaction selected, window.selectedOrderEstimate is:', window.selectedOrderEstimate);
                }

                // Add originalAppointmentId and originalAppointmentDateTime if this is a change appointment workflow
                if (changeAppointmentData !== null && changeAppointmentData.appointmentId) {
                    fields['originalAppointmentId'] = changeAppointmentData.appointmentId;
                    // Include original date/time for cross-reference display
                    if (changeAppointmentData.originalDate) {
                        fields['originalAppointmentDate'] = changeAppointmentData.originalDate;
                    }
                    if (changeAppointmentData.originalTime) {
                        fields['originalAppointmentTime'] = changeAppointmentData.originalTime;
                    }
                    console.log('Change appointment mode - adding originalAppointmentId:', changeAppointmentData.appointmentId, 'date:', changeAppointmentData.originalDate, 'time:', changeAppointmentData.originalTime);
                }

                // Add taskId if this is created from a task
                var taskIdValue = (modeConfig && modeConfig.mode === 'task' && modeConfig.recordData && modeConfig.recordData.taskId) ? modeConfig.recordData.taskId : (new URLSearchParams(window.location.search).get('taskid') || null);
                if (taskIdValue) {
                    fields['taskId'] = taskIdValue;
                    console.log('Task mode - adding taskId:', taskIdValue);
                }

                // Convert fields to URL-encoded string for form submission
                const formData = new URLSearchParams(fields);

                // Use fetch to submit the appointment creation
                fetch(window.location.href, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/x-www-form-urlencoded'
                    },
                    body: formData.toString()
                })
                .then(response => response.text())
                .then(html => {
                    // Parse the response to check for success
                    const parser = new DOMParser();
                    const doc = parser.parseFromString(html, 'text/html');
                    const successMessage = doc.querySelector('.success-message');

                    if (successMessage) {
                        console.log('Appointment created successfully');

                        // If this was a change operation, trigger post-creation workflows
                        if (changeAppointmentData !== null && changeAppointmentData.appointmentId) {
                            const originalEventId = changeAppointmentData.appointmentId;
                            console.log('Triggering post-creation workflows for change appointment');

                            // 1. Add cross-reference to original appointment and mark as rescheduled (async, don't wait)
                            addCrossReferenceToOriginal(originalEventId, formattedDate, selectedTime);

                            // 2. Clean up change mode data
                            changeAppointmentData = null;
                            window.excludeAppointmentIdForAvailability = null;
                        }

                        // Close modal and redirect to clean URL without workflow parameters
                        closeAddAppointmentModal();

                        // Remove workflow parameters from URL before reload
                        const urlParams = new URLSearchParams(window.location.search);
                        const workflowParams = ['customerid', 'estimateid', 'salesorderid', 'rfqid'];
                        let hasWorkflowParams = false;

                        workflowParams.forEach(param => {
                            if (urlParams.has(param)) {
                                urlParams.delete(param);
                                hasWorkflowParams = true;
                            }
                        });

                        if (hasWorkflowParams) {
                            // Redirect to clean URL (this will reload the page without workflow parameters)
                            const newUrl = window.location.protocol + '//' + window.location.host + window.location.pathname +
                                          (urlParams.toString() ? '?' + urlParams.toString() : '');
                            window.location.href = newUrl;
                        } else {
                            // No workflow params present, just reload normally
                            window.location.reload();
                        }
                    } else {
                        // Check for error message
                        const errorMessage = doc.querySelector('.error-message');
                        const errorText = errorMessage ? errorMessage.textContent : 'Failed to create appointment';
                        throw new Error(errorText);
                    }
                })
                .catch(error => {
                    console.error('Error creating appointment:', error);
                    alert('Error creating appointment: ' + error.message);

                    // Re-enable the button
                    if (createButton) {
                        createButton.disabled = false;
                        createButton.textContent = 'Create Appointment';
                        createButton.style.pointerEvents = '';
                    }

                    // Hide loading overlay
                    if (loadingOverlay) {
                        loadingOverlay.style.display = 'none';
                    }

                    // Reset flag
                    isCreatingAppointment = false;
                });
            }

            // Async function to decline original appointment attendees (change appointment workflow)
            function declineOriginalAppointmentAsync(originalEventId) {
                console.log('Declining original appointment:', originalEventId);

                const formData = new URLSearchParams({
                    action: 'declineAppointmentAttendees',
                    appointmentId: originalEventId
                });

                fetch(window.location.href, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/x-www-form-urlencoded'
                    },
                    body: formData.toString()
                })
                .then(response => response.json())
                .then(data => {
                    if (data.success) {
                        console.log('Original appointment declined successfully:', data);
                    } else {
                        console.error('Failed to decline original appointment:', data.error);
                    }
                })
                .catch(error => {
                    console.error('Error declining original appointment:', error);
                });
            }

            // Async function to add cross-reference to original appointment (change appointment workflow)
            function addCrossReferenceToOriginal(originalEventId, newDate, newTime) {
                console.log('Adding cross-reference to original appointment:', originalEventId);

                // Convert 24-hour time (e.g., "17:30") to 12-hour format (e.g., "5:30 PM")
                function formatTimeTo12Hour(time24) {
                    if (!time24 || !time24.includes(':')) return time24;
                    const parts = time24.split(':');
                    let hours = parseInt(parts[0], 10);
                    const minutes = parts[1];
                    const ampm = hours >= 12 ? 'PM' : 'AM';
                    hours = hours % 12 || 12;
                    return hours + ':' + minutes + ' ' + ampm;
                }

                const formattedTime = formatTimeTo12Hour(newTime);
                const crossReferenceText = '--- RESCHEDULED TO: ' + newDate + ' at ' + formattedTime + ' ---';

                const formData = new URLSearchParams({
                    action: 'updateEventMessage',
                    appointmentId: originalEventId,
                    message: crossReferenceText
                });

                fetch(window.location.href, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/x-www-form-urlencoded'
                    },
                    body: formData.toString()
                })
                .then(response => response.json())
                .then(data => {
                    if (data.success) {
                        console.log('Cross-reference added to original appointment successfully:', data);
                    } else {
                        console.error('Failed to add cross-reference to original appointment:', data.error);
                    }
                })
                .catch(error => {
                    console.error('Error adding cross-reference to original appointment:', error);
                });
            }

            function calculateEndTime(startTime, durationMinutes = 60) {
                // Parse the start time (format: "HH:MM")
                const timeParts = startTime.split(':');
                const hours = parseInt(timeParts[0]);
                const minutes = parseInt(timeParts[1]);
                
                // Convert start time to total minutes
                const totalStartMinutes = hours * 60 + minutes;
                
                // Add duration to get end time in minutes
                const totalEndMinutes = totalStartMinutes + durationMinutes;
                
                // Convert back to hours and minutes
                let endHours = Math.floor(totalEndMinutes / 60);
                let endMinutes = totalEndMinutes % 60;
                
                // Handle 24-hour overflow
                if (endHours >= 24) {
                    endHours = endHours - 24;
                }
                
                // Format back to HH:MM
                const formattedEndHours = endHours.toString().padStart(2, '0');
                const formattedEndMinutes = endMinutes.toString().padStart(2, '0');
                
                return formattedEndHours + ':' + formattedEndMinutes;
            }

            function formatDateForNetSuite(date) {
                const month = (date.getMonth() + 1).toString().padStart(2, '0');
                const day = date.getDate().toString().padStart(2, '0');
                const year = date.getFullYear();
                return month + '/' + day + '/' + year;
            }

            // Column sorting functionality
            let currentSortColumn = 'date';  // Default to date column
            let currentSortDirection = 'asc'; // Default to ascending (earliest first)

            // Helper function to create a proper DateTime from date and time strings
            function createDateTime(dateStr, timeStr) {
                try {
                    if (!dateStr || dateStr === undefined || dateStr === null) return new Date(0);
                    
                    // Create base date
                    let baseDate = new Date(dateStr);
                    if (isNaN(baseDate.getTime())) {
                        return new Date(0);
                    }

                    // If no time provided, use the date as-is
                    if (!timeStr || timeStr === undefined || timeStr === null) return baseDate;

                    // Parse time and set on the base date
                    const timeComponents = parseTimeToComponents(timeStr);
                    if (timeComponents && timeComponents.hours !== undefined && timeComponents.minutes !== undefined) {
                        baseDate.setHours(timeComponents.hours, timeComponents.minutes, 0, 0);
                    }

                    return baseDate;
                } catch (error) {
                    console.log('createDateTime error:', error, 'dateStr:', dateStr, 'timeStr:', timeStr);
                    return new Date(0);
                }
            }

            // Helper function to parse time strings and return hour/minute components
            function parseTimeToComponents(timeStr) {
                try {
                    if (!timeStr || timeStr === undefined || timeStr === null) return null;

                    // Ensure timeStr can be safely converted to string
                    if (typeof timeStr === 'object' && timeStr !== null && !String(timeStr)) {
                        return null;
                    }

                    let timeToProcess = String(timeStr).trim();
                    // Handle NetSuite time format which might be like "1:00 PM" or "10:00 AM"
                    const timeRegex = /^(\d{1,2}):(\d{2})\s*(AM|PM)?$/i;
                    const match = timeToProcess.match(timeRegex);
                    
                    if (match) {
                        let hours = parseInt(match[1]);
                        const minutes = parseInt(match[2]);
                        const ampm = match[3] ? match[3].toUpperCase() : null;
                        
                        // Convert to 24-hour format if AM/PM is specified
                        if (ampm) {
                            if (ampm === 'PM' && hours !== 12) {
                                hours += 12;
                            } else if (ampm === 'AM' && hours === 12) {
                                hours = 0;
                            }
                        }
                        
                        return { hours, minutes };
                    }

                    // Try direct parsing with Date for complex formats
                    const testDate = new Date('1970-01-01 ' + timeToProcess);
                    if (!isNaN(testDate.getTime())) {
                        return { 
                            hours: testDate.getHours(), 
                            minutes: testDate.getMinutes() 
                        };
                    }

                    return null;
                } catch (error) {
                    return null;
                }
            }

            function sortTable(column) {
                // Determine sort direction
                if (currentSortColumn === column) {
                    currentSortDirection = currentSortDirection === 'asc' ? 'desc' : 'asc';
                } else {
                    currentSortColumn = column;
                    currentSortDirection = 'asc';
                }

                // Update visual indicators
                updateSortIndicators(column, currentSortDirection);

                // Sort the appointments
                const sortedAppointments = [...allAppointments].sort((a, b) => {
                    let valueA, valueB;

                    switch (column) {
                        case 'date':
                            // Combine date and time for proper datetime sorting
                            valueA = createDateTime(a.startDate, a.startTime);
                            valueB = createDateTime(b.startDate, b.startTime);
                            break;

                        case 'store':
                            valueA = (a.storeLocation || 'N/A').toLowerCase();
                            valueB = (b.storeLocation || 'N/A').toLowerCase();
                            break;

                        case 'salesperson':
                            valueA = (a.employeeName || 'N/A').toLowerCase();
                            valueB = (b.employeeName || 'N/A').toLowerCase();
                            break;

                        case 'customer':
                            valueA = (a.title || 'Untitled').toLowerCase();
                            valueB = (b.title || 'Untitled').toLowerCase();
                            break;

                        case 'eventType':
                            valueA = (a.eventType || 'N/A').toLowerCase();
                            valueB = (b.eventType || 'N/A').toLowerCase();
                            break;

                        case 'outcome':
                            // Sort by outcome priority: Sale > Estimate > Pending
                            const getOutcomePriority = (eventType) => {
                                if (eventType && eventType.toLowerCase().includes('sale')) return 3;
                                if (eventType && eventType.toLowerCase().includes('estimate')) return 2;
                                return 1; // Pending
                            };
                            valueA = getOutcomePriority(a.eventType);
                            valueB = getOutcomePriority(b.eventType);
                            break;

                        case 'probability':
                            // Sort by probability rating (1-5), unrated appointments (null/0) go to bottom
                            valueA = a.probability || 0;
                            valueB = b.probability || 0;

                            // Handle unrated appointments - always sort to bottom
                            if (valueA === 0 && valueB !== 0) return 1;  // A to bottom
                            if (valueB === 0 && valueA !== 0) return -1; // B to bottom
                            if (valueA === 0 && valueB === 0) return 0;  // Both unrated, maintain order
                            break;

                        default:
                            return 0;
                    }

                    // Compare values based on type
                    let comparison = 0;
                    if (valueA instanceof Date && valueB instanceof Date) {
                        comparison = valueA.getTime() - valueB.getTime();
                    } else if (typeof valueA === 'number' && typeof valueB === 'number') {
                        comparison = valueA - valueB;
                    } else {
                        comparison = valueA < valueB ? -1 : (valueA > valueB ? 1 : 0);
                    }

                    return currentSortDirection === 'asc' ? comparison : -comparison;
                });

                // Re-render the table with sorted data
                renderAppointmentsTable(sortedAppointments);
            }

            function updateSortIndicators(activeColumn, direction) {
                // Reset all indicators
                const allIndicators = document.querySelectorAll('.sort-indicator');
                const allHeaders = document.querySelectorAll('.sortable-header');
                
                allIndicators.forEach(indicator => {
                    indicator.textContent = '↕';
                    indicator.className = 'sort-indicator';
                });

                allHeaders.forEach(header => {
                    header.classList.remove('active');
                });

                // Set active indicator
                const activeIndicator = document.getElementById('sort-' + activeColumn);
                const activeHeader = document.querySelector('[data-sort="' + activeColumn + '"]');
                
                if (activeIndicator) {
                    activeIndicator.textContent = direction === 'asc' ? '↑' : '↓';
                    activeIndicator.className = 'sort-indicator ' + direction;
                }

                if (activeHeader) {
                    activeHeader.classList.add('active');
                }
            }

            // Function to handle RFQ transaction selection
            function selectTransactionForAppointment(transactionId, recordType, element) {
                console.log('Selecting transaction:', transactionId, recordType);

                // Clear previous selections
                const allRows = document.querySelectorAll('.order-estimate-row');
                allRows.forEach(row => row.classList.remove('selected'));

                // Select this row
                if (element.tagName === 'TR') {
                    element.classList.add('selected');
                } else {
                    // If element is button, find parent row
                    const row = element.closest('.order-estimate-row');
                    if (row) row.classList.add('selected');
                }

                // Store the selected transaction
                window.selectedOrderEstimate = {
                    id: transactionId,
                    type: recordType,
                    displayName: recordType.toUpperCase() + ' #' + transactionId
                };

                // Update UI to show selection
                const nextButton = document.querySelector('#eventTypeModal .btn-next');
                if (nextButton) {
                    nextButton.disabled = false;
                    nextButton.style.opacity = '1';
                    nextButton.style.cursor = 'pointer';
                }

                console.log('Transaction selected:', window.selectedOrderEstimate);
            }

            // Event ID Direct Access: Auto-open Appointment Details Modal
            document.addEventListener('DOMContentLoaded', function() {
                // Check if eventid parameter was provided
                if (typeof hasEventId !== 'undefined' && hasEventId === true) {
                    console.log('Event ID mode detected');

                    // Check for error first
                    if (typeof eventIdError !== 'undefined' && eventIdError) {
                        console.error('Event ID error:', eventIdError);
                        // Display error message to user
                        setTimeout(function() {
                            alert('Error loading appointment: ' + eventIdError);
                        }, 500);
                        return;
                    }

                    // Check if appointmentData exists
                    if (typeof appointmentData !== 'undefined' && appointmentData) {
                        console.log('Appointment data found, auto-opening modal:', appointmentData);

                        // Wait for DOM to be fully ready, then open modal
                        setTimeout(function() {
                            try {
                                // Extract all fields from appointmentData
                                const id = appointmentData.id || '';
                                const title = appointmentData.title || 'Untitled';
                                const date = appointmentData.startDate || '';
                                const startTime = appointmentData.startTime || 'N/A';
                                const endTime = appointmentData.endTime || 'N/A';
                                const store = appointmentData.store || 'N/A';
                                const salesperson = appointmentData.salesperson || 'N/A';
                                const organizer = appointmentData.organizer || 'N/A';
                                const organizerId = appointmentData.organizerId || '';
                                const eventType = appointmentData.eventType || 'N/A';
                                const status = appointmentData.status || 'N/A';
                                const response = appointmentData.response || 'N/A';
                                const outcome = appointmentData.outcome || 'N/A';
                                const createdDate = appointmentData.createdDate || '';
                                const owner = appointmentData.owner || 'N/A';
                                const ownerId = appointmentData.ownerId || '';
                                const markDone = appointmentData.markDone || 'No';
                                const message = appointmentData.message || '';
                                const interimNote = appointmentData.interimNote || '';
                                const company = appointmentData.company || '';
                                const companyText = appointmentData.companyText || '';
                                const contact = appointmentData.contact || '';
                                const contactText = appointmentData.contactText || '';
                                const transaction = appointmentData.transaction || '';
                                const transactionText = appointmentData.transactionText || '';
                                const supportCase = appointmentData.supportCase || '';
                                const supportCaseText = appointmentData.supportCaseText || '';
                                const customerType = appointmentData.customerType || 'N/A';
                                const rescheduled = appointmentData.rescheduled || false;

                                // Call the existing showAppointmentDetails function
                                console.log('Calling showAppointmentDetails with event ID:', id);
                                showAppointmentDetails(
                                    id, title, date, startTime, endTime,
                                    store, salesperson, organizer, organizerId,
                                    eventType, status, response, outcome,
                                    createdDate, owner, ownerId, markDone,
                                    message, interimNote,
                                    company, companyText, contact, contactText,
                                    transaction, transactionText,
                                    supportCase, supportCaseText, customerType,
                                    rescheduled
                                );

                                console.log('Appointment Details modal should now be open');
                            } catch (error) {
                                console.error('Error opening appointment modal:', error);
                                alert('Error displaying appointment details. Please check the console for details.');
                            }
                        }, 500);
                    }
                }
            });


