            // Helper function to determine city from ZIP code for NYC boroughs
            function getCityFromZipCode(zipCode) {
                const zip = zipCode.toString();

                // Brooklyn ZIP codes (11201-11256)
                if (zip >= '11201' && zip <= '11256') {
                    return 'Brooklyn';
                }

                // Queens ZIP codes (11004-11109, 11354-11697)
                if ((zip >= '11004' && zip <= '11109') || (zip >= '11354' && zip <= '11697')) {
                    return 'Queens';
                }

                // Manhattan ZIP codes (10001-10282)
                if (zip >= '10001' && zip <= '10282') {
                    return 'New York';
                }

                // Bronx ZIP codes (10451-10475)
                if (zip >= '10451' && zip <= '10475') {
                    return 'Bronx';
                }

                // Staten Island ZIP codes (10301-10314)
                if (zip >= '10301' && zip <= '10314') {
                    return 'Staten Island';
                }

                return '';
            }

            // Populate new customer form fields from Google Place (legacy API)
            function populateNewCustomerAddress(place) {
                const addressComponents = place.address_components || [];
                
                let streetNumber = '';
                let streetName = '';
                let city = '';
                let state = '';
                let zipCode = '';
                
                // Parse address components
                addressComponents.forEach(component => {
                    const types = component.types;

                    if (types.includes('street_number')) {
                        streetNumber = component.long_name;
                    } else if (types.includes('route')) {
                        streetName = component.long_name;
                    } else if (types.includes('locality')) {
                        city = component.long_name;
                    } else if (types.includes('sublocality_level_1') || types.includes('sublocality')) {
                        // For NYC boroughs like Brooklyn, Queens, Manhattan, Bronx, Staten Island
                        if (!city) {
                            city = component.long_name;
                        }
                    } else if (types.includes('administrative_area_level_3')) {
                        // Sometimes boroughs are returned as administrative_area_level_3
                        if (!city) {
                            city = component.long_name;
                        }
                    } else if (types.includes('administrative_area_level_1')) {
                        state = component.short_name;
                    } else if (types.includes('postal_code')) {
                        zipCode = component.long_name;
                    }
                });

                // Fallback: If no city was found, try to determine it from ZIP code for NYC boroughs
                if (!city && zipCode) {
                    city = getCityFromZipCode(zipCode);
                }

                // Populate form fields
                const address1Field = document.getElementById('newCustomerAddress1');
                const cityField = document.getElementById('newCustomerCity');
                const stateField = document.getElementById('newCustomerState');
                const zipField = document.getElementById('newCustomerZip');
                
                if (address1Field) {
                    const fullStreetAddress = streetNumber && streetName ? 
                        streetNumber + ' ' + streetName : 
                        (streetName || place.formatted_address.split(',')[0]);
                    address1Field.value = fullStreetAddress;
                }
                
                if (cityField) cityField.value = city;
                if (stateField) stateField.value = state;
                if (zipField) zipField.value = zipCode;

                // Set verification flag - address is verified by Google Places
                window.primaryAddressVerified = true;
                window.primaryAddressPlaceholder = false;

                // Show success message
                const successElement = document.getElementById('newCustomerAddress1-success');
                if (successElement) {
                    successElement.textContent = '✓ Address verified';
                    successElement.style.display = 'block';
                }

                // Update address field border color to green
                if (address1Field) {
                    address1Field.style.borderColor = '#059669';
                }

                // Remove readonly from city/state/zip fields so disabled state shows proper styling
                // They remain readonly unless placeholder checkbox is used or API fallback mode
                if (cityField) cityField.removeAttribute('readonly');
                if (stateField) stateField.removeAttribute('readonly');
                if (zipField) zipField.removeAttribute('readonly');

                // Make them disabled instead (preventing manual editing but allowing proper styling)
                if (cityField) cityField.disabled = true;
                if (stateField) stateField.disabled = true;
                if (zipField) zipField.disabled = true;

                console.log('Address populated from Google Place:', {
                    street: streetNumber + ' ' + streetName,
                    city,
                    state,
                    zip: zipCode
                });
            }

