    /**
     * Format date for display
     */
    function formatDate(dateString) {
        try {
            if (typeof dateString === 'string' && dateString.includes('/')) {
                const parts = dateString.split('/');
                if (parts.length === 3) {
                    const month = parseInt(parts[0]) - 1;
                    const day = parseInt(parts[1]);
                    const year = parseInt(parts[2]);
                    const date = new Date(year, month, day);
                    if (!isNaN(date.getTime())) {
                        return date.toLocaleDateString('en-US', {
                            weekday: 'long',
                            year: 'numeric',
                            month: 'long',
                            day: 'numeric'
                        });
                    }
                }
            }

            const date = new Date(dateString);
            if (!isNaN(date.getTime())) {
                return date.toLocaleDateString('en-US', {
                    weekday: 'long',
                    year: 'numeric',
                    month: 'long',
                    day: 'numeric'
                });
            }

            return new Date().toLocaleDateString('en-US', {
                weekday: 'long',
                year: 'numeric',
                month: 'long',
                day: 'numeric'
            });
        } catch (error) {
            log.error('Error formatting date', { dateString, error: error.message });
            return new Date().toLocaleDateString('en-US', {
                weekday: 'long',
                year: 'numeric',
                month: 'long',
                day: 'numeric'
            });
        }
    }

    /**
     * Get count of employees with appointments
     */
    function getEmployeesWithAppointments(appointmentsByEmployee) {
        return Object.values(appointmentsByEmployee).filter((appointments) => appointments.length > 0).length;
    }

    /**
     * Get total count of appointments (excludes cancelled appointments)
     */
    function getTotalAppointments(appointmentsByEmployee) {
        return Object.values(appointmentsByEmployee).reduce((total, appointments) => {
            const activeAppointments = appointments.filter((appt) => appt.rescheduled !== true && appt.rescheduled !== 'T' && appt.status !== 'CANCELLED');
            return total + activeAppointments.length;
        }, 0);
    }

    /**
     * Generate appointment count display text
     */
    function getAppointmentCountText(filteredAppointmentsByEmployee, originalAppointmentsByEmployee) {
        const filteredCount = getTotalAppointments(filteredAppointmentsByEmployee);
        const totalCount = getTotalAppointments(originalAppointmentsByEmployee);

        if (filteredCount < totalCount) {
            return filteredCount + ' of ' + totalCount + ' appointments';
        } else {
            return filteredCount + ' appointments';
        }
    }

    /**
     * Server-side JavaScript string escaping function
     */
    function escapeForJS(text) {
        if (!text || typeof text !== 'string') {
            return text || '';
        }

        // Strip HTML tags and escape for JavaScript
        let sanitized = text.replace(/<[^>]*>/g, '');

        // Escape for JavaScript string safety
        sanitized = sanitized
            .replace(/'/g, '') // Remove single quotes
            .replace(/"/g, '') // Remove double quotes
            .replace(/\\/g, '') // Remove backslashes
            .replace(/\n/g, ' ') // Replace newlines with spaces
            .replace(/\r/g, ' ') // Replace carriage returns with spaces
            .replace(/\t/g, ' ') // Replace tabs with spaces
            .replace(/\x00/g, '') // Remove null characters
            .trim();

        return sanitized;
    }

    /**
     * Generate modern appointments table HTML
     */
    function generateModernAppointmentsTable(appointmentsByEmployee, employees, SHOW_PROBABILITY_COLUMN, SHOW_INTERIM_COLUMN) {
        const allAppointments = [];
        Object.values(appointmentsByEmployee).forEach((appointments) => {
            appointments.forEach((appt) => {
                const employee = employees.find((emp) => emp.id === appt.organizer);
                if (employee) {
                    const owner = employees.find((emp) => emp.id === appt.owner);
                    allAppointments.push({
                        ...appt,
                        employeeName: employee.name,
                        employeeTitle: employee.title,
                        ownerName: owner ? owner.name : 'N/A'
                    });
                }
            });
        });

        // Sort by date+time (ascending - earliest first)
        allAppointments.sort((a, b) => {
            // Parse dates properly
            const dateA = new Date(a.startDate);
            const dateB = new Date(b.startDate);

            // If dates are different, sort by date
            if (dateA.getTime() !== dateB.getTime()) {
                return dateA.getTime() - dateB.getTime();
            }

            // If dates are the same, sort by time
            const timeA = a.startTime || '';
            const timeB = b.startTime || '';
            return timeA.localeCompare(timeB);
        });

        if (allAppointments.length === 0) {
            return '<div class="no-appointments">No appointments scheduled for today</div>';
        }

        return allAppointments
            .map((appt) => {
                const startTime = formatTimeForDisplay(appt.startTime);
                const endTime = formatTimeForDisplay(appt.endTime);
                const date = formatDate(appt.startDate);

                let outcomeBadge = '';
                let outcomeClass = 'badge-pending';
                let outcomeText = '';

                if (appt.eventType && appt.eventType.toLowerCase().includes('sale')) {
                    outcomeBadge = '✓';
                    outcomeClass = 'badge-sale';
                    outcomeText = 'Sale';
                } else if (appt.eventType && appt.eventType.toLowerCase().includes('estimate')) {
                    outcomeBadge = '📄';
                    outcomeClass = 'badge-estimate';
                    outcomeText = 'Estimate';
                }

                // Add cancelled class if appointment is rescheduled or cancelled
                const cancelledClass = appt.rescheduled === true || appt.rescheduled === 'T' || appt.status === 'CANCELLED' ? ' cancelled' : '';

                // Build appointment row HTML with direct parameter passing (all 29 parameters)
                let rowHTML = '<div class="appointment-row' + cancelledClass + '" onclick="showAppointmentDetails(' + appt.id + ', ' + '&quot;' + escapeForJS(appt.title || 'Untitled') + '&quot;, ' + '&quot;' + formatDateForTable(date) + '&quot;, ' + '&quot;' + startTime + '&quot;, ' + '&quot;' + (appt.endTime || 'N/A') + '&quot;, ' + '&quot;' + escapeForJS(appt.storeLocation || 'N/A') + '&quot;, ' + '&quot;' + escapeForJS(appt.employeeName || 'N/A') + '&quot;, ' + '&quot;' + escapeForJS(appt.employeeName || 'N/A') + '&quot;, ' + (appt.owner ? '&quot;' + appt.owner + '&quot;' : 'null') + ', ' + '&quot;' + escapeForJS(appt.eventType || 'N/A') + '&quot;, ' + '&quot;' + (appt.status || 'N/A') + '&quot;, ' + '&quot;' + (appt.response || 'N/A') + '&quot;, ' + '&quot;' + outcomeText + '&quot;, ' + '&quot;' + (appt.createdDate || 'N/A') + '&quot;, ' + '&quot;' + escapeForJS(appt.ownerName || 'N/A') + '&quot;, ' + (appt.owner ? '&quot;' + appt.owner + '&quot;' : 'null') + ', ' + '&quot;' + (appt.markDone || 'N/A') + '&quot;, ' + '&quot;' + escapeForJS(appt.message || '') + '&quot;, ' + '&quot;' + escapeForJS(appt.interimNote || '') + '&quot;, ' + '&quot;' + (appt.company || '') + '&quot;, ' + '&quot;' + escapeForJS(appt.companyText || '') + '&quot;, ' + '&quot;' + (appt.contact || '') + '&quot;, ' + '&quot;' + escapeForJS(appt.contactText || '') + '&quot;, ' + '&quot;' + (appt.transaction || '') + '&quot;, ' + '&quot;' + escapeForJS(appt.transactionText || '') + '&quot;, ' + '&quot;' + (appt.supportCase || '') + '&quot;, ' + '&quot;' + escapeForJS(appt.supportCaseText || '') + '&quot;, ' + '&quot;' + escapeForJS(appt.customerCategoryText || '') + '&quot;, ' + (appt.rescheduled ? 'true' : 'false') + ');" style="cursor: pointer;">';

                // Date-time section
                rowHTML += '<div class="date-time">';
                rowHTML += '<div class="time">' + startTime + '</div>';
                rowHTML += '<div class="date">' + formatDateForTable(date) + '</div>';
                rowHTML += '</div>';

                // Store section
                rowHTML += '<div class="store">' + (appt.storeLocation || 'N/A') + '</div>';

                // Salesperson section
                rowHTML += '<div class="salesperson">' + (appt.employeeName || 'N/A') + '</div>';

                // Customer info section
                rowHTML += '<div class="customer-info">';
                rowHTML += '<div class="customer-name">';
                rowHTML += '<span class="appointment-link">' + (appt.title || 'Untitled') + '</span>';
                rowHTML += '</div>';
                rowHTML += '<!-- <div class="customer-email">' + (appt.organizer || 'N/A') + '</div> -->';
                rowHTML += '</div>';

                // Event type section
                rowHTML += '<div class="event-type">' + (appt.eventType || 'N/A') + '</div>';

                // Details info section
                rowHTML += '<div class="details-info">';
                rowHTML += '<div class="detail-primary" style="font-size: 0.875rem; color: #1e293b; white-space: pre-line;">' + (appt.message || '') + '</div>';
                rowHTML += '</div>';

                // Interim note section (conditional)
                if (SHOW_INTERIM_COLUMN) {
                    rowHTML += '<div class="interim-note">';
                    rowHTML += '<div class="detail-primary" style="font-size: 0.875rem; color: #1e293b;">' + (appt.interimNote || 'N/A') + '</div>';
                    rowHTML += '</div>';
                }

                // Sentiment column section (conditional)
                if (SHOW_PROBABILITY_COLUMN) {
                    rowHTML += '<div class="probability-cell" data-appointment-id="' + appt.id + '">';
                    rowHTML += '<div class="probability-rating" data-current-rating="' + (appt.probability || 0) + '">';
                    rowHTML += '<span class="dollar-sign' + (appt.probability && appt.probability >= 1 ? ' active' : '') + '" data-rating="1" onclick="setProbability(' + "'" + appt.id + "'" + ', 1, event)">$</span>';
                    rowHTML += '<span class="dollar-sign' + (appt.probability && appt.probability >= 2 ? ' active' : '') + '" data-rating="2" onclick="setProbability(' + "'" + appt.id + "'" + ', 2, event)">$</span>';
                    rowHTML += '<span class="dollar-sign' + (appt.probability && appt.probability >= 3 ? ' active' : '') + '" data-rating="3" onclick="setProbability(' + "'" + appt.id + "'" + ', 3, event)">$</span>';
                    rowHTML += '<span class="dollar-sign' + (appt.probability && appt.probability >= 4 ? ' active' : '') + '" data-rating="4" onclick="setProbability(' + "'" + appt.id + "'" + ', 4, event)">$</span>';
                    rowHTML += '<span class="dollar-sign' + (appt.probability && appt.probability >= 5 ? ' active' : '') + '" data-rating="5" onclick="setProbability(' + "'" + appt.id + "'" + ', 5, event)">$</span>';
                    // rowHTML += '<span style="font-size: 0.75rem; color: #ef4444; margin-left: 0.5rem; font-weight: 600;" title="Debug: Raw sentiment value">[' + (appt.probability !== null && appt.probability !== undefined ? appt.probability : 'null') + ']</span>';
                    rowHTML += '</div>';
                    rowHTML += '</div>';
                }

                // Close appointment row
                rowHTML += '</div>';

                return rowHTML;
            })
            .join('');
    }

    /**
     * Format time for display
     */
    function formatTimeForDisplay(timeValue) {
        if (!timeValue) return 'N/A';

        try {
            if (typeof timeValue === 'string') {
                if (timeValue.toLowerCase().includes('am') || timeValue.toLowerCase().includes('pm')) {
                    return timeValue.toLowerCase().replace('am', ' AM').replace('pm', ' PM');
                }

                const timeParts = timeValue.split(':');
                if (timeParts.length >= 2) {
                    const hours = parseInt(timeParts[0]);
                    const minutes = parseInt(timeParts[1]);

                    if (!isNaN(hours) && !isNaN(minutes)) {
                        let displayHours = hours;
                        let ampm = 'AM';

                        if (hours === 0) {
                            displayHours = 12;
                            ampm = 'AM';
                        } else if (hours === 12) {
                            displayHours = 12;
                            ampm = 'PM';
                        } else if (hours > 12) {
                            displayHours = hours - 12;
                            ampm = 'PM';
                        } else {
                            ampm = 'AM';
                        }

                        const displayMinutes = minutes < 10 ? '0' + minutes : minutes;
                        return displayHours + ':' + displayMinutes + ' ' + ampm;
                    }
                }
            }

            const time = new Date(timeValue);
            if (!isNaN(time.getTime())) {
                return time.toLocaleTimeString('en-US', {
                    hour: 'numeric',
                    minute: '2-digit',
                    hour12: true
                });
            }

            return 'N/A';
        } catch (error) {
            log.error('Error formatting time', { timeValue, error: error.message });
            return 'N/A';
        }
    }

    /**
     * Get unique store names from all employees and appointments
     */
    function getUniqueStoreNames(appointmentsByEmployee, employees) {
        const storeNames = new Set();

        Object.values(appointmentsByEmployee).forEach((appointments) => {
            appointments.forEach((appt) => {
                if (appt.storeLocation && appt.storeLocation.trim() !== '') {
                    storeNames.add(appt.storeLocation);
                }
            });
        });

        employees.forEach((emp) => {
            if (emp.location && emp.location.trim() !== '') {
                storeNames.add(emp.location);
            }
        });

        return Array.from(storeNames).sort();
    }

    /**
     * Get available locations for dropdown
     */
    function getAvailableLocations() {
        try {
            const locationSearch = search.create({
                type: search.Type.LOCATION,
                filters: [['isinactive', 'is', 'F']],
                columns: ['internalid', 'name']
            });

            const locations = [];
            locationSearch.run().each(function (result) {
                locations.push({
                    id: result.getValue('internalid'),
                    name: result.getValue('name')
                });
                return true;
            });

            return locations;
        } catch (error) {
            log.error('Error getting locations', {
                error: error.message
            });
            return [];
        }
    }

    /**
     * Get available event types for dropdown
     */
    function getEventTypes() {
        try {
            /*             log.debug('Getting event types from customlist_appttype...'); */

            // Try to access the custom list directly using the record module
            let eventTypes = [];

            try {
                // Method 1: Try to access the custom list via custom record type
                // In NetSuite, custom lists are often accessed via custom record types
                /*                 log.debug('Trying to access custom list via custom record type...'); */

                // Try to find the custom list by searching for it
                const listSearch = search.create({
                    type: search.Type.CUSTOM_RECORD_TYPE,
                    filters: [['name', 'is', 'Appointment Type']]
                });

                let foundListId = null;
                listSearch.run().each(function (result) {
                    const listId = result.getValue('internalid');
                    const listName = result.getValue('name');
                    /*                     log.debug('Found custom record type:', { id: listId, name: listName }); */

                    if ((listName && listName.toLowerCase().includes('appointment')) || listName.toLowerCase().includes('appt')) {
                        foundListId = listId;
                        return false; // Stop after finding the first match
                    }
                    return true;
                });

                if (foundListId) {
                    /*                     log.debug('Found appointment type list with ID:', foundListId); */

                    // Now search for items in this custom record type
                    const itemSearch = search.create({
                        type: search.Type.CUSTOM_RECORD_TYPE,
                        id: foundListId
                    });

                    itemSearch.run().each(function (result) {
                        const itemId = result.getValue('internalid');
                        const itemName = result.getValue('name');

                        if (itemId && itemName) {
                            eventTypes.push({
                                id: itemId,
                                name: itemName
                            });
                            /*                             log.debug('Added event type:', { id: itemId, name: itemName }); */
                        }
                        return true;
                    });

                    if (eventTypes.length > 0) {
                        /*                         log.debug('Successfully loaded', eventTypes.length, 'event types from custom record type'); */
                        return eventTypes;
                    }
                }
            } catch (recordError) {
                /*                 log.debug('Custom record type method failed:', recordError.message); */

                // Method 2: Try to find existing calendar events with event types
                try {
                    /*                     log.debug('Trying to extract event types from existing calendar events...'); */

                    // Search for calendar events that have event types set
                    const eventSearch = search.create({
                        type: search.Type.CALENDAR_EVENT,
                        filters: [['custevent_etype', 'isnotempty', ''], 'AND', ['custevent_etype', 'noneof', '@NONE@']],
                        columns: ['custevent_etype']
                    });

                    const uniqueTypes = new Set();
                    let resultCount = 0;
                    eventSearch.run().each(function (result) {
                        resultCount++;
                        if (resultCount > 100) return false; // Limit results

                        const eventType = result.getText('custevent_etype');
                        if (eventType && eventType.trim() !== '' && eventType.trim() !== 'Sales Meeting') {
                            uniqueTypes.add(eventType);
                        }
                        return true;
                    });

                    // Convert to array format
                    eventTypes = Array.from(uniqueTypes).map((type, index) => ({
                        id: (index + 1).toString(),
                        name: type
                    }));

                    if (eventTypes.length > 0) {
                        /*                         log.debug('Successfully extracted', eventTypes.length, 'event types from calendar events'); */
                        return eventTypes;
                    }
                } catch (searchError) {
                    /*                     log.debug('Calendar event search also failed:', searchError.message); */
                }
            }

            // If both methods fail, log the error and return fallback values
            /*             log.debug('Both custom list access methods failed, using fallback values'); */
            return [
                { id: '1', name: 'Sold Order' },
                { id: '4', name: 'Unsold - VIP' },
                { id: '13', name: 'Unsold - Kitchen' },
                { id: '14', name: 'Unsold - Bath' },
                { id: '15', name: 'Unsold - Client Service Kitchen' },
                { id: '16', name: 'Unsold - Client Service Bath' },
                { id: '17', name: 'Unsold - Other' }
            ];
        } catch (error) {
            log.error('Error getting event types', {
                error: error.message,
                stack: error.stack
            });

            // Fallback to common appointment types if everything fails
            return [
                { id: '1', name: 'Sold Order' },
                { id: '4', name: 'Unsold - VIP' },
                { id: '13', name: 'Unsold - Kitchen' },
                { id: '14', name: 'Unsold - Bath' },
                { id: '15', name: 'Unsold - Client Service Kitchen' },
                { id: '16', name: 'Unsold - Client Service Bath' },
                { id: '17', name: 'Unsold - Other' }
            ];
        }
    }

    /**
     * Get specific store locations with predefined IDs
     */
    function getUniqueStoreNamesWithIds(appointmentsByEmployee, employees) {
        // Define the specific store IDs we want to show
        const specificStoreIds = [2, 3, 4, 5, 14, 17];

        try {
            const stores = [];

            // Load each store record to get the name
            specificStoreIds.forEach((storeId) => {
                try {
                    const storeRecord = record.load({
                        type: record.Type.LOCATION,
                        id: storeId
                    });

                    const storeName = storeRecord.getValue('name');
                    if (storeName) {
                        stores.push({
                            id: storeId,
                            name: storeName
                        });
                    }
                } catch (error) {
                    // If we can't load a store, skip it
                    /*                     log.debug('Could not load store', { storeId, error: error.message }); */
                }
            });

            // Sort alphabetically first
            const sortedStores = stores.sort((a, b) => a.name.localeCompare(b.name));

            // Rearrange for 2-column layout to fill columns vertically (A, B, C | D, E, F)
            const reorderedStores = [];
            const halfLength = Math.ceil(sortedStores.length / 2);

            // First half goes to left column positions (0, 2, 4, ...)
            for (let i = 0; i < halfLength; i++) {
                reorderedStores[i * 2] = sortedStores[i];
            }

            // Second half goes to right column positions (1, 3, 5, ...)
            for (let i = 0; i < sortedStores.length - halfLength; i++) {
                reorderedStores[i * 2 + 1] = sortedStores[halfLength + i];
            }

            return reorderedStores;
        } catch (error) {
            log.error('Error loading store locations', { error: error.message });
            return [];
        }
    }

    function getUniqueEventTypes(appointmentsByEmployee) {
        const eventTypeMap = new Map();

        // Iterate through all employees and their appointments
        Object.values(appointmentsByEmployee).forEach((appointments) => {
            appointments.forEach((appointment) => {
                if (appointment.eventTypeId && appointment.eventType && appointment.eventType.trim()) {
                    eventTypeMap.set(appointment.eventTypeId, appointment.eventType.trim());
                }
            });
        });

        // Convert map to array and sort by text
        const eventTypes = Array.from(eventTypeMap.entries()).map(([id, text]) => ({
            id: id,
            text: text
        }));

        return eventTypes.sort((a, b) => a.text.localeCompare(b.text));
    }

    /**
     * Get all possible event types from NetSuite by searching across all calendar events
     * This ensures the filter dropdown shows all available event types, not just those in current appointments
     */
    function getAllEventTypesFromCustomList() {
        try {
            log.debug('getAllEventTypesFromCustomList - Starting search for all event types');

            // Search all calendar events and group by event type to get unique values
            // This is more reliable than trying to query the custom list directly
            const eventSearch = search.create({
                type: search.Type.CALENDAR_EVENT,
                filters: [
                    ['custevent_etype', 'noneof', '@NONE@'] // Exclude empty event types
                ],
                columns: [
                    {
                        name: 'custevent_etype',
                        summary: search.Summary.GROUP
                    }
                ]
            });

            const eventTypes = [];
            let resultCount = 0;

            // Define allowed event type IDs for compact filter list
            const allowedEventTypeIds = ['1', '4', '13', '14', '15', '16', '17'];

            eventSearch.run().each(function (result) {
                const eventTypeId = result.getValue({
                    name: 'custevent_etype',
                    summary: search.Summary.GROUP
                });
                const eventTypeText = result.getText({
                    name: 'custevent_etype',
                    summary: search.Summary.GROUP
                });

                // Only include specific event types:
                // ID 1: Sold Order
                // ID 4: Unsold - VIP
                // ID 13: Unsold - Kitchen
                // ID 14: Unsold - Bath
                // ID 15: Unsold - Client Service Kitchen
                // ID 16: Unsold - Client Service Bath
                // ID 17: Unsold - Other
                // Note: ID 12 (Non Customer & Scheduled Day Off) is handled separately as combined checkbox
                if (eventTypeId && eventTypeText && eventTypeText.trim() !== '' && allowedEventTypeIds.includes(eventTypeId.toString())) {
                    eventTypes.push({
                        id: eventTypeId,
                        text: eventTypeText.trim()
                    });
                }

                resultCount++;
                return true; // Continue iteration
            });

            log.debug('getAllEventTypesFromCustomList - Results', {
                totalEventTypes: eventTypes.length,
                resultCount: resultCount,
                eventTypes: eventTypes
            });

            // Ensure all expected event types are present, even if no events exist yet
            const requiredEventTypes = [
                { id: '1', text: 'Sold Order' },
                { id: '4', text: 'Unsold - VIP' },
                { id: '13', text: 'Unsold - Kitchen' },
                { id: '14', text: 'Unsold - Bath' },
                { id: '15', text: 'Unsold - Client Service Kitchen' },
                { id: '16', text: 'Unsold - Client Service Bath' },
                { id: '17', text: 'Unsold - Other' }
            ];

            // Add any missing required event types
            requiredEventTypes.forEach(function (requiredType) {
                const exists = eventTypes.some(function (existingType) {
                    return existingType.id.toString() === requiredType.id.toString();
                });
                if (!exists) {
                    eventTypes.push(requiredType);
                    log.debug('getAllEventTypesFromCustomList - Added missing required type', requiredType);
                }
            });

            // Sort alphabetically by text
            return eventTypes.sort((a, b) => a.text.localeCompare(b.text));
        } catch (error) {
            log.error('Error in getAllEventTypesFromCustomList', {
                error: error.message,
                stack: error.stack
            });
            // Fallback to required event types if search fails
            return [
                { id: '1', text: 'Sold Order' },
                { id: '4', text: 'Unsold - VIP' },
                { id: '13', text: 'Unsold - Kitchen' },
                { id: '14', text: 'Unsold - Bath' },
                { id: '15', text: 'Unsold - Client Service Kitchen' },
                { id: '16', text: 'Unsold - Client Service Bath' },
                { id: '17', text: 'Unsold - Other' }
            ];
        }
    }

    /**
     * Format date for HTML input (YYYY-MM-DD format)
     */
    function formatDateForHTMLInput(dateString) {
        try {
            if (typeof dateString === 'string' && dateString.includes('/')) {
                // Handle MM/DD/YYYY format from NetSuite
                const parts = dateString.split('/');
                if (parts.length === 3) {
                    const month = parseInt(parts[0]);
                    const day = parseInt(parts[1]);
                    const year = parseInt(parts[2]);

                    if (!isNaN(month) && !isNaN(day) && !isNaN(year)) {
                        // Format as YYYY-MM-DD for HTML input
                        const formattedMonth = month.toString().padStart(2, '0');
                        const formattedDay = day.toString().padStart(2, '0');
                        return year + '-' + formattedMonth + '-' + formattedDay;
                    }
                }
            }

            // Try to parse as a Date object
            const date = new Date(dateString);
            if (!isNaN(date.getTime())) {
                const year = date.getFullYear();
                const month = (date.getMonth() + 1).toString().padStart(2, '0');
                const day = date.getDate().toString().padStart(2, '0');
                return year + '-' + month + '-' + day;
            }

            // Fallback to today's date
            const today = new Date();
            const year = today.getFullYear();
            const month = (today.getMonth() + 1).toString().padStart(2, '0');
            const day = today.getDate().toString().padStart(2, '0');
            return year + '-' + month + '-' + day;
        } catch (error) {
            log.error('Error formatting date for HTML input', { dateString, error: error.message });
            // Fallback to today's date
            const today = new Date();
            const year = today.getFullYear();
            const month = (today.getMonth() + 1).toString().padStart(2, '0');
            const day = today.getDate().toString().padStart(2, '0');
            return year + '-' + month + '-' + day;
        }
    }

    /**
     * Get interim note value from search result - reads ONLY from dedicated field
     * No fallback to message extraction - only shows what's in custevent_event_interim_note
     */
    function getInterimNoteValue(result) {
        try {
            const fieldValue = result.getValue('custevent_event_interim_note');
            return fieldValue || '';
        } catch (fieldError) {
            return '';
        }
    }

    /**
     * Check if all attendees have declined an event
     * @param {string} eventId - The internal ID of the calendar event
     * @returns {boolean} - True if all attendees have declined, false otherwise
     */
    function allAttendeesDeclined(eventId) {
        try {
            // Load the calendar event record
            const eventRecord = record.load({
                type: record.Type.CALENDAR_EVENT,
                id: eventId
            });

            // Try to get attendee list - NetSuite may use different field names
            let attendeeList = null;
            const possibleAttendeeFields = ['attendeelist', 'inviteelist', 'attendees', 'invitees'];

            for (const fieldName of possibleAttendeeFields) {
                try {
                    const lineCount = eventRecord.getLineCount({ sublistId: fieldName });
                    if (lineCount > 0) {
                        attendeeList = fieldName;
                        break;
                    }
                } catch (e) {
                    // Field doesn't exist, try next one
                    continue;
                }
            }

            // If no attendee list found, the event might not have attendees
            if (!attendeeList) {
                /*                 log.debug('No attendee list found for event', { eventId: eventId }); */
                return false; // Don't filter out events without attendees
            }

            const lineCount = eventRecord.getLineCount({ sublistId: attendeeList });

            // If no attendees, don't filter out
            if (lineCount === 0) {
                return false;
            }

            let allDeclined = true;

            // Check each attendee's response
            for (let i = 0; i < lineCount; i++) {
                try {
                    const response = eventRecord.getSublistValue({
                        sublistId: attendeeList,
                        fieldId: 'response',
                        line: i
                    });

                    // If any attendee hasn't declined, keep the appointment
                    if (response !== 'DECLINED' && response !== 'NORESPONSE') {
                        allDeclined = false;
                        break;
                    }
                } catch (e) {
                    // If we can't get response, assume not declined
                    /*                     log.debug('Could not get attendee response', {
                        eventId: eventId,
                        line: i,
                        error: e.message
                    }); */
                    allDeclined = false;
                    break;
                }
            }

            /* 
            log.debug('Attendee response check', {
                eventId: eventId,
                attendeeCount: lineCount,
                allDeclined: allDeclined
            }); */

            return allDeclined;
        } catch (error) {
            log.error('Error checking attendee responses', {
                eventId: eventId,
                error: error.message
            });
            // If there's an error, don't filter out the appointment
            return false;
        }
    }

    /**
     * Save interim note to event record
     */
    function saveInterimNoteToEvent(appointmentId, interimNote) {
        try {
            /*             log.debug('saveInterimNoteToEvent called', {
                appointmentId: appointmentId,
                interimNote: interimNote
            }); */

            // Load the event record
            const eventRecord = record.load({
                type: record.Type.CALENDAR_EVENT,
                id: appointmentId
            });

            // Try to set the interim note field with improved error handling
            let savedToField = false;

            try {
                eventRecord.setValue({
                    fieldId: 'custevent_event_interim_note',
                    value: interimNote
                });

                savedToField = true;
                /*                 log.debug('Successfully saved interim note to dedicated field'); */
            } catch (fieldError) {
                /*                 log.debug('Field custevent_event_interim_note not available, using fallback', {
                    error: fieldError.message
                }); */

                // Fallback: save to the message field with a prefix
                const currentMessage = eventRecord.getValue('message') || '';
                const interimNotePrefix = '[INTERIM NOTE]: ';

                // Remove existing interim note if present
                let newMessage = currentMessage.replace(new RegExp(interimNotePrefix + '.*?(?=\\n|$)', 'g'), '').trim();

                // Add new interim note
                if (interimNote) {
                    newMessage = interimNotePrefix + interimNote + (newMessage ? '\\n' + newMessage : '');
                }

                eventRecord.setValue({
                    fieldId: 'message',
                    value: newMessage
                });

                /* 
                log.debug('Saved interim note to message field as fallback'); */
            }

            // Save the record
            const recordId = eventRecord.save();

            /* 
            log.debug('Event record saved successfully', {
                recordId: recordId
            }); */

            return {
                success: true,
                message: savedToField ? 'Interim note saved to dedicated field successfully' : 'Interim note saved to message field successfully'
            };
        } catch (error) {
            log.error('Error saving interim note to event', {
                error: error.message,
                stack: error.stack,
                appointmentId: appointmentId
            });

            return {
                success: false,
                error: error.message
            };
        }
    }

