    /**
     * Cancel an appointment by marking it as rescheduled and adding cancellation message
     * @param {string|number} appointmentId - The internal ID of the calendar event
     * @returns {Object} - {success: boolean, error: string, message: string}
     */
    function cancelAppointmentEvent(appointmentId) {
        try {
            // Validate input
            if (!appointmentId) {
                return {
                    success: false,
                    error: 'Missing appointmentId'
                };
            }

            // Load the event record
            const eventRecord = record.load({
                type: record.Type.CALENDAR_EVENT,
                id: appointmentId
            });

            // Mark the appointment as rescheduled (cancelled appointments do not block time slots)
            eventRecord.setValue({
                fieldId: 'custevent_rescheduled',
                value: true
            });

            // Get current message and append cancellation text
            const currentMessage = eventRecord.getValue({ fieldId: 'message' }) || '';
            const cancellationText = '\n\n--- APPOINTMENT CANCELLED ---';
            const updatedMessage = currentMessage + cancellationText;

            eventRecord.setValue({
                fieldId: 'message',
                value: updatedMessage
            });

            // Get appointment details for SMS before saving
            const customerId = eventRecord.getValue({ fieldId: 'company' });
            const appointmentDate = eventRecord.getValue({ fieldId: 'startdate' });
            const startTime = eventRecord.getValue({ fieldId: 'starttime' });
            const storeLocationId = eventRecord.getValue({ fieldId: 'custevent_storeloc' });
            const salespersonId = eventRecord.getValue({ fieldId: 'organizer' });

            // Save the event record
            const savedId = eventRecord.save();

            // Log success for audit trail
            log.audit('Appointment Cancelled', {
                appointmentId: appointmentId,
                savedId: savedId,
                userId: runtime.getCurrentUser().id,
                timestamp: new Date().toISOString()
            });

            // Send SMS notification for cancellation (non-blocking)
            if (customerId) {
                try {
                    // Get store name from location ID
                    let storeName = '';
                    if (storeLocationId) {
                        try {
                            const locationLookup = search.lookupFields({
                                type: search.Type.LOCATION,
                                id: storeLocationId,
                                columns: ['name']
                            });
                            storeName = locationLookup.name || '';
                        } catch (locErr) {
                            log.debug('Could not lookup store name for cancelled appointment', locErr.message);
                        }
                    }

                    // Get salesperson name and phone using preferred name fields
                    let salespersonName = '';
                    let salespersonPhone = '';
                    if (salespersonId) {
                        try {
                            const empLookup = search.lookupFields({
                                type: search.Type.EMPLOYEE,
                                id: salespersonId,
                                columns: ['custentity_preferred_name', 'custentity_preferred_first_name', 'custentity_preferred_last_name', 'firstname', 'lastname', 'phone', 'mobilephone']
                            });
                            // Priority 1: Build from preferred first/last name fields
                            const prefFirstName = empLookup.custentity_preferred_first_name || '';
                            const prefLastName = empLookup.custentity_preferred_last_name || '';
                            if (prefFirstName && prefLastName) {
                                salespersonName = (prefFirstName + ' ' + prefLastName).trim();
                            } else if (empLookup.custentity_preferred_name) {
                                // Priority 2: Full preferred name field
                                salespersonName = empLookup.custentity_preferred_name;
                            } else {
                                // Priority 3: Standard name fields
                                const firstName = empLookup.firstname || '';
                                const lastName = empLookup.lastname || '';
                                salespersonName = (firstName + ' ' + lastName).trim() || '';
                            }
                            // Try phone first, then mobilephone
                            salespersonPhone = empLookup.phone || empLookup.mobilephone || '';
                        } catch (empErr) {
                            log.debug('Could not lookup salesperson for cancelled appointment', empErr.message);
                        }
                    }

                    // Format date for SMS
                    let formattedDate = '';
                    if (appointmentDate) {
                        formattedDate = format.format({
                            value: appointmentDate,
                            type: format.Type.DATE
                        });
                    }

                    const smsResult = smsNotification.sendSMS({
                        smsType: smsNotification.SMS_TYPES.CANCEL_APPOINTMENT,
                        customerId: customerId,
                        data: {
                            store: storeName,
                            date: formattedDate,
                            time: formatTimeForDisplay(startTime),
                            salesperson: salespersonName,
                            salespersonPhone: salespersonPhone
                        }
                    });

                    log.audit('SMS notification attempted for cancelled appointment', {
                        appointmentId: appointmentId,
                        smsType: smsNotification.SMS_TYPES.CANCEL_APPOINTMENT,
                        customerId: customerId,
                        success: smsResult.success,
                        error: smsResult.error || null
                    });

                    // Store MessageSid on Calendar Event for audit trail
                    if (smsResult.success && smsResult.twilioSid) {
                        try {
                            record.submitFields({
                                type: record.Type.CALENDAR_EVENT,
                                id: appointmentId,
                                values: {
                                    custevent_last_sms_sid: smsResult.twilioSid
                                }
                            });
                            log.debug('cancelAppointmentEvent', 'Stored MessageSid ' + smsResult.twilioSid + ' on event ' + appointmentId);
                        } catch (sidError) {
                            log.error('cancelAppointmentEvent', 'Failed to store MessageSid on event ' + appointmentId + ': ' + sidError.message);
                        }
                    }
                } catch (smsError) {
                    log.error('SMS send failed for cancelled appointment (non-blocking)', {
                        appointmentId: appointmentId,
                        customerId: customerId,
                        error: smsError.message
                    });
                    // Do NOT throw - cancellation was successful
                }
            }

            return {
                success: true,
                message: 'Appointment cancelled successfully'
            };
        } catch (error) {
            log.error('Error cancelling appointment', {
                appointmentId: appointmentId,
                error: error.message,
                stack: error.stack
            });

            return {
                success: false,
                error: error.message
            };
        }
    }

    /**
     * Save probability rating to event record
     * Uses record.submitFields() for efficient update (10 governance units vs 60+ for load/save)
     * @param {string|number} appointmentId - The internal ID of the calendar event
     * @param {number} probability - Integer 1-5 representing probability rating
     * @returns {Object} - {success: boolean, error: string, message: string, probability: number}
     */
    function saveProbabilityToEvent(appointmentId, probability) {
        try {
            // Validate inputs
            if (!appointmentId) {
                return {
                    success: false,
                    error: 'Missing appointmentId'
                };
            }

            if (typeof probability !== 'number' || probability < 1 || probability > 5) {
                return {
                    success: false,
                    error: 'Invalid probability value: must be 1-5'
                };
            }

            // Use submitFields for efficient update (10 governance units)
            record.submitFields({
                type: record.Type.CALENDAR_EVENT,
                id: appointmentId,
                values: {
                    custevent_probability: probability
                }
            });

            // Log success for audit trail
            log.audit('Probability Saved', {
                appointmentId: appointmentId,
                probability: probability,
                userId: runtime.getCurrentUser().id,
                timestamp: new Date().toISOString()
            });

            return {
                success: true,
                message: 'Probability saved successfully',
                probability: probability
            };
        } catch (error) {
            log.error('Error saving probability', {
                appointmentId: appointmentId,
                probability: probability,
                error: error.message,
                stack: error.stack
            });

            return {
                success: false,
                error: error.message
            };
        }
    }

