    /**
     * Add cross-reference note to the original appointment message field
     * This appends a reschedule notice to the existing message
     * @param {string|number} appointmentId - The internal ID of the calendar event
     * @param {string} crossReferenceText - The text to append to the message
     * @returns {Object} - {success: boolean, error: string, message: string}
     */
    function addCrossReferenceToOriginalAppointment(appointmentId, crossReferenceText) {
        try {
            // Validate inputs
            if (!appointmentId) {
                return {
                    success: false,
                    error: 'Missing appointmentId'
                };
            }

            if (!crossReferenceText) {
                return {
                    success: false,
                    error: 'Missing crossReferenceText'
                };
            }

            // Load the event record to get current message
            const eventRecord = record.load({
                type: record.Type.CALENDAR_EVENT,
                id: appointmentId
            });

            // Get current message
            const currentMessage = eventRecord.getValue({ fieldId: 'message' }) || '';

            // Append cross-reference text
            const updatedMessage = currentMessage + '\n\n' + crossReferenceText;

            // Update the message field and set rescheduled checkbox
            record.submitFields({
                type: record.Type.CALENDAR_EVENT,
                id: appointmentId,
                values: {
                    message: updatedMessage,
                    custevent_rescheduled: true
                }
            });

            // Log success for audit trail
            log.audit('Cross-Reference Added to Original Appointment', {
                appointmentId: appointmentId,
                crossReferenceText: crossReferenceText,
                userId: runtime.getCurrentUser().id,
                timestamp: new Date().toISOString()
            });

            return {
                success: true,
                message: 'Cross-reference added successfully'
            };
        } catch (error) {
            log.error('Error adding cross-reference to original appointment', {
                appointmentId: appointmentId,
                error: error.message,
                stack: error.stack
            });

            return {
                success: false,
                error: error.message
            };
        }
    }

    /**
     * Validate that a transaction exists and is accessible
     */
    function validateTransaction(transactionId, eventType) {
        try {
            if (!transactionId) {
                return false;
            }

            // Dynamically determine the record type (supports Opportunity, Estimate, Sales Order, etc.)
            const recordType = getTransactionType(transactionId);

            if (!recordType) {
                log.error('Unable to determine transaction type for validation', {
                    transactionId: transactionId,
                    eventType: eventType
                });
                return false;
            }

            /*
            log.debug('Validating transaction', {
                transactionId: transactionId,
                recordType: recordType,
                eventType: eventType
            }); */

            // Try to load the record to verify it exists and is accessible
            const transactionRecord = record.load({
                type: recordType,
                id: transactionId
            });

            if (transactionRecord) {
                /*                 log.debug('Transaction validation successful', {
                    transactionId: transactionId,
                    recordType: recordType,
                    transactionType: transactionRecord.type
                }); */
                return true;
            }

            /*
            log.debug('Transaction record loaded but validation failed', {
                transactionId: transactionId,
                recordType: recordType
            }); */
            return false;
        } catch (error) {
            log.error('Transaction validation failed', {
                transactionId: transactionId,
                eventType: eventType,
                error: error.message
            });
            return false;
        }
    }

    /**
     * Update transaction record's custbody_showroomappt field with appointment ID
     * @param {string} transactionId - The NetSuite transaction ID
     * @param {string} appointmentId - The NetSuite calendar event ID
     */
    function updateTransactionShowroomAppointment(transactionId, appointmentId) {
        try {
            /*             log.debug('Updating transaction with appointment reference', {
                transactionId: transactionId,
                appointmentId: appointmentId
            }); */

            // First, determine the transaction type
            const transactionType = getTransactionType(transactionId);
            if (!transactionType) {
                throw new Error('Unable to determine transaction type for ID: ' + transactionId);
            }

            /*
            log.debug('Transaction type determined', {
                transactionId: transactionId,
                transactionType: transactionType
            }); */

            // Use submitFields to update without triggering User Events (more efficient and safer)
            // This prevents unintended status changes from User Events that might fire on full record.save()
            record.submitFields({
                type: transactionType,
                id: transactionId,
                values: {
                    custbody_showroomappt: appointmentId
                },
                options: {
                    enableSourcing: false,
                    ignoreMandatoryFields: true
                }
            });

            log.debug('Updated transaction showroom appointment field via submitFields', {
                transactionId: transactionId,
                appointmentId: appointmentId,
                transactionType: transactionType
            });

            return {
                success: true,
                transactionId: transactionId
            };
        } catch (error) {
            log.error('Error updating transaction showroom appointment field', {
                transactionId: transactionId,
                appointmentId: appointmentId,
                error: error.message,
                stack: error.stack
            });
            throw error;
        }
    }

    /**
     * Updates the appointment date field on an estimate record
     * @param {string} transactionId - The NetSuite transaction ID
     * @param {Date} appointmentDate - The appointment date to set
     * @returns {Object} Result object with success status
     */
    function updateEstimateAppointmentDate(transactionId, appointmentDate) {
        try {
            if (!appointmentDate) {
                log.debug('No appointment date provided for estimate update', {
                    transactionId: transactionId
                });
                return {
                    success: false,
                    error: 'No appointment date provided'
                };
            }

            // First, determine the transaction type
            const transactionType = getTransactionType(transactionId);
            if (!transactionType) {
                throw new Error('Unable to determine transaction type for ID: ' + transactionId);
            }

            // Only update if transaction is an estimate
            if (transactionType !== record.Type.ESTIMATE) {
                log.debug('Transaction is not an estimate, skipping appointment date update', {
                    transactionId: transactionId,
                    transactionType: transactionType
                });
                return {
                    success: true,
                    skipped: true,
                    reason: 'Not an estimate transaction'
                };
            }

            log.debug('Updating estimate with appointment date', {
                transactionId: transactionId,
                appointmentDate: appointmentDate
            });

            // Load the estimate record
            const estimateRecord = record.load({
                type: record.Type.ESTIMATE,
                id: transactionId
            });

            // Set the appointment date field
            estimateRecord.setValue({
                fieldId: 'custbody_appointmentdate',
                value: appointmentDate
            });

            // Save the estimate record
            const updatedTransactionId = estimateRecord.save();

            log.audit('Successfully updated estimate with appointment date', {
                transactionId: updatedTransactionId,
                appointmentDate: appointmentDate
            });

            return {
                success: true,
                transactionId: updatedTransactionId
            };
        } catch (error) {
            log.error('Error updating estimate appointment date field', {
                transactionId: transactionId,
                appointmentDate: appointmentDate,
                error: error.message,
                stack: error.stack
            });
            // Don't throw - return error object to allow appointment creation to continue
            return {
                success: false,
                error: error.message
            };
        }
    }

    /**
     * Checks if an opportunity's status should be updated based on current status
     * @param {string} transactionId - The NetSuite transaction ID
     * @returns {Object} Result object with shouldUpdate flag and current status
     */
    function checkOpportunityStatusForUpdate(transactionId) {
        try {
            // First, determine the transaction type
            const transactionType = getTransactionType(transactionId);
            if (!transactionType) {
                throw new Error('Unable to determine transaction type for ID: ' + transactionId);
            }

            // Only check if transaction is an opportunity
            if (transactionType !== record.Type.OPPORTUNITY) {
                return {
                    success: true,
                    isOpportunity: false,
                    shouldUpdate: false,
                    reason: 'Not an opportunity transaction'
                };
            }

            // Load the opportunity record to check current status
            const opportunityRecord = record.load({
                type: record.Type.OPPORTUNITY,
                id: transactionId,
                isDynamic: false
            });

            // Get the current opportunity status
            const currentStatusRaw = opportunityRecord.getValue({
                fieldId: 'entitystatus'
            });
            const currentStatus = String(currentStatusRaw);
            const currentStatusText = opportunityRecord.getText({
                fieldId: 'entitystatus'
            });

            // Define allowed statuses that can be updated
            const STATUS_NEW = '18';
            const STATUS_ATTEMPTING_CONTACT = '26';
            const allowedStatuses = [STATUS_NEW, STATUS_ATTEMPTING_CONTACT];

            const shouldUpdate = allowedStatuses.includes(currentStatus);

            log.debug('Pre-check: Opportunity status before any updates', {
                transactionId: transactionId,
                currentStatus: currentStatus,
                currentStatusText: currentStatusText,
                shouldUpdate: shouldUpdate
            });

            return {
                success: true,
                isOpportunity: true,
                shouldUpdate: shouldUpdate,
                currentStatus: currentStatus,
                currentStatusText: currentStatusText
            };
        } catch (error) {
            log.error('Error checking opportunity status', {
                transactionId: transactionId,
                error: error.message
            });
            return {
                success: false,
                error: error.message,
                shouldUpdate: false
            };
        }
    }

    /**
     * Updates the opportunity status and follow-up date when an appointment is created
     * @param {string} transactionId - The NetSuite transaction ID
     * @param {Date} appointmentDate - The appointment date
     * @param {boolean} shouldUpdateStatus - Whether to update the status (determined before other automations run)
     * @returns {Object} Result object with success status
     */
    function updateOpportunityOnAppointment(transactionId, appointmentDate, shouldUpdateStatus) {
        try {
            if (!appointmentDate) {
                log.debug('No appointment date provided for opportunity update', {
                    transactionId: transactionId
                });
                return {
                    success: false,
                    error: 'No appointment date provided'
                };
            }

            // First, determine the transaction type
            const transactionType = getTransactionType(transactionId);
            if (!transactionType) {
                throw new Error('Unable to determine transaction type for ID: ' + transactionId);
            }

            // Only update if transaction is an opportunity
            if (transactionType !== record.Type.OPPORTUNITY) {
                log.debug('Transaction is not an opportunity, skipping status and follow-up update', {
                    transactionId: transactionId,
                    transactionType: transactionType
                });
                return {
                    success: true,
                    skipped: true,
                    reason: 'Not an opportunity transaction'
                };
            }

            log.debug('Updating opportunity with status and follow-up date', {
                transactionId: transactionId,
                appointmentDate: appointmentDate,
                shouldUpdateStatus: shouldUpdateStatus
            });

            // Load the opportunity record
            const opportunityRecord = record.load({
                type: record.Type.OPPORTUNITY,
                id: transactionId
            });

            // Get the current opportunity status for logging
            const currentStatusRaw = opportunityRecord.getValue({
                fieldId: 'entitystatus'
            });
            const currentStatus = String(currentStatusRaw);
            const currentStatusText = opportunityRecord.getText({
                fieldId: 'entitystatus'
            });

            log.debug('Current opportunity status at update time', {
                transactionId: transactionId,
                currentStatusRaw: currentStatusRaw,
                currentStatusRawType: typeof currentStatusRaw,
                currentStatus: currentStatus,
                currentStatusText: currentStatusText,
                shouldUpdateStatus: shouldUpdateStatus,
                note: shouldUpdateStatus ? 'Will update status' : 'Status protected - another automation may have already changed it'
            });

            // Define status IDs for opportunity workflow
            const STATUS_APPOINTMENT_SCHEDULED = '23'; // "Appointment Scheduled" - appointment set

            // Use the shouldUpdateStatus flag that was determined BEFORE other automations ran
            // This prevents the issue where a User Event or Workflow changes the status before we get here
            if (shouldUpdateStatus) {
                // Set the opportunity status to "Appointment Scheduled" (entitystatus ID: 23)
                opportunityRecord.setValue({
                    fieldId: 'entitystatus',
                    value: STATUS_APPOINTMENT_SCHEDULED
                });

                log.audit('Updated opportunity status to Appointment Scheduled', {
                    transactionId: transactionId,
                    previousStatusBeforeAutomations: 'New or Attempting Contact (based on pre-check)',
                    currentStatusAtUpdateTime: currentStatusText,
                    newStatus: STATUS_APPOINTMENT_SCHEDULED
                });
            } else {
                log.audit('PROTECTED: Skipped status update - opportunity was in advanced stage', {
                    transactionId: transactionId,
                    currentStatusAtUpdateTime: currentStatus,
                    currentStatusTextAtUpdateTime: currentStatusText,
                    shouldUpdateStatus: shouldUpdateStatus,
                    reason: 'Opportunity was in an advanced stage (Proposal, Purchasing, Closed Won, etc.) when appointment creation started'
                });
            }

            // Calculate follow-up date (day after appointment)
            const followUpDate = new Date(appointmentDate);
            followUpDate.setDate(followUpDate.getDate() + 1);

            // Set the follow-up date field
            opportunityRecord.setValue({
                fieldId: 'custbody_opp_followup_date',
                value: followUpDate
            });

            // Save the opportunity record
            const updatedTransactionId = opportunityRecord.save();

            log.audit('Successfully updated opportunity with follow-up date', {
                transactionId: updatedTransactionId,
                statusUpdated: shouldUpdateStatus,
                previousStatus: currentStatus,
                appointmentDate: appointmentDate,
                followUpDate: followUpDate
            });

            return {
                success: true,
                transactionId: updatedTransactionId,
                followUpDate: followUpDate
            };
        } catch (error) {
            log.error('Error updating opportunity status and follow-up date', {
                transactionId: transactionId,
                appointmentDate: appointmentDate,
                error: error.message,
                stack: error.stack
            });
            // Don't throw - return error object to allow appointment creation to continue
            return {
                success: false,
                error: error.message
            };
        }
    }

    /**
     * Helper function to determine transaction type from transaction ID
     * @param {string} transactionId - The NetSuite transaction ID
     * @returns {string} The NetSuite record type
     */
    function getTransactionType(transactionId) {
        try {
            // Try to load as different transaction types to determine the correct type
            const typesToTry = [record.Type.SALES_ORDER, record.Type.ESTIMATE, record.Type.INVOICE, record.Type.CASH_SALE, record.Type.OPPORTUNITY];

            for (let i = 0; i < typesToTry.length; i++) {
                try {
                    const testRecord = record.load({
                        type: typesToTry[i],
                        id: transactionId
                    });

                    if (testRecord) {
                        /*                         log.debug('Transaction type identified', {
                            transactionId: transactionId,
                            type: typesToTry[i]
                        }); */
                        return typesToTry[i];
                    }
                } catch (e) {
                    // Continue to next type
                    continue;
                }
            }

            log.error('Unable to determine transaction type', {
                transactionId: transactionId,
                typesAttempted: typesToTry
            });
            return null;
        } catch (error) {
            log.error('Error in getTransactionType', {
                transactionId: transactionId,
                error: error.message
            });
            return null;
        }
    }

    /**
     * Create a new appointment for the current user
     */
    function createAppointment(parameters) {
        try {
            const currentUser = runtime.getCurrentUser();

            // Parse the date and time
            const appointmentDate = parameters.appointmentDate;
            const startTime = parameters.startTime;
            const endTime = parameters.endTime || '';
            const title = parameters.title || 'New Appointment';
            const storeLocation = parameters.storeLocation;
            const eventType = parameters.eventType || '';
            const transactionId = parameters.transactionId;
            const customerId = parameters.customerId;
            const customerName = parameters.customerName;
            const salespersonId = parameters.salespersonId;
            const salespersonName = parameters.salespersonName;
            const taskId = parameters.taskId || parameters.taskid;
            // For Client Service appointments, endCustomerId is the actual customer for SMS
            // customerId will be the CRD contractor (for transaction linking)
            const endCustomerId = parameters.endCustomerId || '';
            const endCustomerName = parameters.endCustomerName || '';
            const isClientServiceEventType = eventType === '15' || eventType === '16';

            // DEBUG: Log transaction ID received from client
            log.audit('createAppointment - transactionId received', {
                transactionId: transactionId,
                customerId: customerId,
                endCustomerId: endCustomerId,
                eventType: eventType,
                isClientServiceEventType: isClientServiceEventType,
                hasTransactionId: !!transactionId
            });

            if (!appointmentDate || !startTime) {
                return {
                    success: false,
                    error: 'Date and start time are required'
                };
            }

            // Create the calendar event record
            const eventRecord = record.create({
                type: record.Type.CALENDAR_EVENT
            });

            // Set basic fields - create a descriptive title for the calendar event
            // For Client Service appointments, use endCustomerName (the referred customer) for the title
            const titleCustomerName = isClientServiceEventType && endCustomerName ? endCustomerName : customerName;
            let appointmentTitle = title;
            if (titleCustomerName) {
                // Clean customer name by removing any trailing "- 1" or similar suffixes
                let cleanCustomerName = titleCustomerName.trim();

                // Log the original customer name for debugging
                log.debug('Original customerName for title', cleanCustomerName);

                // Remove various patterns like "- 1", " - 1", "-1", etc.
                if (cleanCustomerName.match(/\s*-\s*\d+$/)) {
                    const originalName = cleanCustomerName;
                    cleanCustomerName = cleanCustomerName.replace(/\s*-\s*\d+$/, '');
                    log.debug('Cleaned customerName (trailing suffix)', {
                        original: originalName,
                        cleaned: cleanCustomerName
                    });
                }

                // Remove leading number prefix pattern like "147846 " or "36661 "
                // This occurs when companyText from NetSuite includes the customer number
                if (cleanCustomerName.match(/^\d+\s+/)) {
                    const originalName = cleanCustomerName;
                    cleanCustomerName = cleanCustomerName.replace(/^\d+\s+/, '');
                    log.debug('Cleaned customerName (leading number prefix)', {
                        original: originalName,
                        cleaned: cleanCustomerName
                    });
                }

                // Use only the customer name as the title
                appointmentTitle = cleanCustomerName;
            } else if (title.endsWith(' - Appointment')) {
                // Use the title as-is if it already follows the pattern
                appointmentTitle = title;
            } else {
                // For custom titles, keep them but ensure they don't contain long notes
                if (title.length > 50) {
                    appointmentTitle = titleCustomerName || 'Customer';
                } else {
                    appointmentTitle = title;
                }
            }

            eventRecord.setValue('title', appointmentTitle);
            // Use selected salesperson or fallback to current user
            const appointmentOwner = salespersonId || currentUser.id;
            eventRecord.setValue('organizer', appointmentOwner);
            eventRecord.setValue('owner', appointmentOwner);

            // Set customer field BEFORE transaction (required for transaction linking)
            if (customerId) {
                try {
                    eventRecord.setValue('company', customerId);
                    /*                     log.debug('Customer linked to appointment', {
                        customerId: customerId,
                        customerName: customerName,
                        appointmentTitle: title
                    }); */
                } catch (e) {
                    log.error('Error linking customer to appointment', {
                        customerId: customerId,
                        customerName: customerName,
                        error: e.message
                    });
                }
            }

            // Set date and time
            const parsedDate = parseAppointmentDate(appointmentDate);
            if (parsedDate) {
                eventRecord.setValue('startdate', parsedDate);
                eventRecord.setValue('enddate', parsedDate);
            }

            if (startTime) {
                const convertedStartTime = convertTimeForNetSuite(startTime, parsedDate);
                eventRecord.setValue('starttime', convertedStartTime);
            }

            if (endTime) {
                const convertedEndTime = convertTimeForNetSuite(endTime, parsedDate);
                eventRecord.setValue('endtime', convertedEndTime);
            }

            // Set custom fields if they exist
            if (storeLocation) {
                try {
                    eventRecord.setValue('custevent_storeloc', storeLocation);
                } catch (e) {
                    /*                     log.debug('Store location field not found or invalid', e.message); */
                }
            }

            if (eventType) {
                try {
                    eventRecord.setValue('custevent_etype', eventType);
                } catch (e) {
                    /*                     log.debug('Event type field not found or invalid', e.message); */
                }
            }

            // Link to transaction (sales order or estimate) if provided
            // Link to transaction if provided
            // Note: For Client Service appointments, customerId is the CRD contractor (estimate's entity)
            // This allows the transaction field to be set correctly
            let transactionFieldSet = false;
            if (transactionId) {
                log.audit('createAppointment - attempting to link transaction', {
                    transactionId: transactionId,
                    eventType: eventType,
                    customerId: customerId,
                    isClientService: isClientServiceEventType
                });
                try {
                    eventRecord.setValue('transaction', transactionId);
                    transactionFieldSet = true;
                    log.audit('createAppointment - transaction field set successfully', {
                        transactionId: transactionId
                    });
                } catch (fieldError) {
                    log.error('Failed to set transaction field on calendar event', {
                        transactionId: transactionId,
                        fieldError: fieldError.message
                    });
                }
            }

            // Set the message field with the appointment details/notes
            // The original title parameter contains the user-entered appointment notes/description
            let appointmentMessage = '';
            if (title && title !== 'New Appointment' && !title.endsWith(' - Appointment')) {
                appointmentMessage = title;
            }

            // If this is a change appointment workflow, add cross-reference to original
            const originalAppointmentId = parameters.originalAppointmentId;
            if (originalAppointmentId) {
                // Build cross-reference text with original date/time if available
                const originalDateRaw = parameters.originalAppointmentDate || '';
                const originalTimeRaw = parameters.originalAppointmentTime || '';

                // Helper to parse date like "Feb 12, 2026" or "February 12, 2026" to MM/DD/YYYY
                function formatDateToMMDDYYYY(dateStr) {
                    if (!dateStr) return '';
                    const months = {
                        'jan': '01', 'january': '01',
                        'feb': '02', 'february': '02',
                        'mar': '03', 'march': '03',
                        'apr': '04', 'april': '04',
                        'may': '05',
                        'jun': '06', 'june': '06',
                        'jul': '07', 'july': '07',
                        'aug': '08', 'august': '08',
                        'sep': '09', 'september': '09',
                        'oct': '10', 'october': '10',
                        'nov': '11', 'november': '11',
                        'dec': '12', 'december': '12'
                    };
                    // Try to match "Mon DD, YYYY" or "Month DD, YYYY" format
                    const match = dateStr.match(/([a-zA-Z]+)\s+(\d{1,2}),?\s+(\d{4})/);
                    if (match) {
                        const monthName = match[1].toLowerCase();
                        const day = match[2].padStart(2, '0');
                        const year = match[3];
                        const month = months[monthName] || months[monthName.substring(0, 3)];
                        if (month) {
                            return month + '/' + day + '/' + year;
                        }
                    }
                    // If already in MM/DD/YYYY format, return as-is
                    if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(dateStr)) {
                        return dateStr;
                    }
                    return dateStr;
                }

                // Helper to extract start time and format to h:mm AM/PM
                function formatTimeToStandard(timeStr) {
                    if (!timeStr) return '';
                    // Handle time range like "6:30 pm - 7:30 pm" - extract just the start time
                    const rangeMatch = timeStr.match(/^([^-]+)/);
                    const startTime = rangeMatch ? rangeMatch[1].trim() : timeStr.trim();

                    // Parse time and format consistently
                    const timeMatch = startTime.match(/(\d{1,2}):(\d{2})\s*(am|pm)?/i);
                    if (timeMatch) {
                        let hours = parseInt(timeMatch[1], 10);
                        const minutes = timeMatch[2];
                        let ampm = (timeMatch[3] || '').toUpperCase();

                        // If no AM/PM provided, assume based on hour
                        if (!ampm) {
                            ampm = hours >= 12 ? 'PM' : 'AM';
                            if (hours > 12) hours = hours - 12;
                            if (hours === 0) hours = 12;
                        }

                        return hours + ':' + minutes + ' ' + ampm;
                    }
                    return startTime;
                }

                const originalDate = formatDateToMMDDYYYY(originalDateRaw);
                const originalTime = formatTimeToStandard(originalTimeRaw);

                let crossReferenceText;
                if (originalDate && originalTime) {
                    crossReferenceText = '--- RESCHEDULED FROM ' + originalDate + ' at ' + originalTime + ' ---';
                } else if (originalDate) {
                    crossReferenceText = '--- RESCHEDULED FROM ' + originalDate + ' ---';
                } else {
                    // Fallback to appointment ID if date/time not available
                    crossReferenceText = '--- RESCHEDULED FROM APPOINTMENT #' + originalAppointmentId + ' ---';
                }
                if (appointmentMessage) {
                    appointmentMessage = appointmentMessage + '\n\n' + crossReferenceText;
                } else {
                    appointmentMessage = crossReferenceText;
                }
                /* log.audit('Change appointment mode detected', {
                    originalAppointmentId: originalAppointmentId,
                    newAppointmentTitle: appointmentTitle
                }); */
            }

            // Set the message field
            if (appointmentMessage) {
                try {
                    eventRecord.setValue('message', appointmentMessage);
                    /*                     log.debug('Message field set for appointment', {
                        originalTitle: title,
                        appointmentTitle: appointmentTitle,
                        eventId: eventRecord.id || 'new',
                        hasOriginalAppointmentId: !!originalAppointmentId
                    }); */
                } catch (e) {
                    /*                     log.debug('Message field not available or error setting message', e.message); */
                }
            }

            // Set status to confirmed
            eventRecord.setValue('status', 'CONFIRMED');

            // Set response to accepted for the organizer
            eventRecord.setValue('response', 'ACCEPTED');

            // PRE-CHECK: Determine if opportunity status should be updated BEFORE calendar event save
            // This must happen BEFORE eventRecord.save() to read the ORIGINAL opportunity status
            // before any User Events or Workflows on the calendar event can potentially modify it
            let shouldUpdateOpportunityStatus = false;
            const preCheckTimestamp = new Date().toISOString();
            if (transactionId && parsedDate) {
                try {
                    const statusCheckResult = checkOpportunityStatusForUpdate(transactionId);
                    if (statusCheckResult.success && statusCheckResult.isOpportunity) {
                        shouldUpdateOpportunityStatus = statusCheckResult.shouldUpdate;
                        /* log.audit('Pre-check completed BEFORE calendar event save', {
                            timestamp: preCheckTimestamp,
                            transactionId: transactionId,
                            shouldUpdateStatus: shouldUpdateOpportunityStatus,
                            currentStatus: statusCheckResult.currentStatus,
                            currentStatusText: statusCheckResult.currentStatusText,
                            reason: shouldUpdateOpportunityStatus ? 'Opportunity in early stage (New or Attempting Contact)' : 'Opportunity in advanced stage - will be PROTECTED from status regression'
                        }); */
                    }
                } catch (statusCheckError) {
                    log.error('Error in pre-check for opportunity status', {
                        timestamp: preCheckTimestamp,
                        transactionId: transactionId,
                        error: statusCheckError.message
                    });
                    // If pre-check fails, default to not updating status (safer)
                    shouldUpdateOpportunityStatus = false;
                }
            }

            // Save the calendar event record AFTER pre-check completes
            // This ensures shouldUpdateOpportunityStatus flag is set based on ORIGINAL opportunity status
            let eventId;
            try {
                eventId = eventRecord.save();
            } catch (saveError) {
                // If save failed and we set a transaction field, retry without it
                // The transaction field may have sourcing restrictions that reject certain transaction types
                if (transactionFieldSet && saveError.message && saveError.message.indexOf('transaction') !== -1) {
                    log.error('Calendar event save failed due to transaction field - retrying without it', {
                        transactionId: transactionId,
                        originalError: saveError.message
                    });
                    // Clear the transaction field and retry
                    eventRecord.setValue('transaction', '');
                    eventId = eventRecord.save();
                    /* log.audit('Calendar event saved successfully after clearing transaction field', {
                        transactionId: transactionId,
                        note: 'Transaction link will be maintained via custbody_showroomappt instead'
                    }); */
                } else {
                    // Re-throw if not a transaction field issue
                    throw saveError;
                }
            }
            const eventSaveTimestamp = new Date().toISOString();
            log.debug('Calendar event saved', {
                eventId: eventId,
                timestamp: eventSaveTimestamp,
                preCheckCompleted: preCheckTimestamp,
                millisecondsBetween: new Date(eventSaveTimestamp).getTime() - new Date(preCheckTimestamp).getTime()
            });

            // Verify transaction field was saved (for debugging)
            if (transactionId && eventId) {
                try {
                    const savedEvent = record.load({
                        type: record.Type.CALENDAR_EVENT,
                        id: eventId
                    });
                    const savedTransactionId = savedEvent.getValue('transaction');
                    log.audit('createAppointment - verifying transaction field after save', {
                        eventId: eventId,
                        expectedTransactionId: transactionId,
                        actualTransactionId: savedTransactionId,
                        fieldWasSaved: savedTransactionId == transactionId,
                        customerId: customerId,
                        isClientService: isClientServiceEventType
                    });
                } catch (verifyError) {
                    log.error('createAppointment - error verifying transaction field', {
                        eventId: eventId,
                        transactionId: transactionId,
                        error: verifyError.message
                    });
                }
            }

            // Update transaction record's custbody_showroomappt field if transactionId is provided
            if (transactionId && eventId) {
                try {
                    updateTransactionShowroomAppointment(transactionId, eventId);
                    /*                     log.audit('Transaction updated with appointment reference', {
                        transactionId: transactionId,
                        appointmentId: eventId
                    }); */
                } catch (updateError) {
                    log.error('Failed to update transaction with appointment reference', {
                        transactionId: transactionId,
                        appointmentId: eventId,
                        error: updateError.message
                    });
                    // Don't fail the appointment creation if transaction update fails
                }

                // Update estimate's appointment date field if transaction is an estimate
                if (parsedDate) {
                    try {
                        const dateUpdateResult = updateEstimateAppointmentDate(transactionId, parsedDate);
                        if (dateUpdateResult.success && !dateUpdateResult.skipped) {
                            /* log.audit('Estimate updated with appointment date', {
                                transactionId: transactionId,
                                appointmentDate: parsedDate
                            }); */
                        }
                    } catch (dateUpdateError) {
                        log.error('Failed to update estimate with appointment date', {
                            transactionId: transactionId,
                            appointmentDate: parsedDate,
                            error: dateUpdateError.message
                        });
                        // Don't fail the appointment creation if date update fails
                    }
                }

                // Update opportunity status and follow-up date if transaction is an opportunity
                // Pass the shouldUpdateStatus flag that was determined BEFORE other automations ran
                if (parsedDate) {
                    try {
                        const oppUpdateResult = updateOpportunityOnAppointment(transactionId, parsedDate, shouldUpdateOpportunityStatus);
                        if (oppUpdateResult.success && !oppUpdateResult.skipped) {
                            /* log.audit('Opportunity updated with status and follow-up date', {
                                transactionId: transactionId,
                                statusWasUpdated: shouldUpdateOpportunityStatus,
                                appointmentDate: parsedDate,
                                followUpDate: oppUpdateResult.followUpDate
                            }); */
                        }
                    } catch (oppUpdateError) {
                        log.error('Failed to update opportunity', {
                            transactionId: transactionId,
                            error: oppUpdateError.message
                        });
                        // Don't fail the appointment creation if opportunity update fails
                    }
                }
            }

            // For Client Service appointments, update the attendee to be the end customer (not the CRD contractor)
            // The company field is set to CRD contractor for transaction linking, but we want the end customer as attendee
            if (isClientServiceEventType && endCustomerId && eventId) {
                try {
                    log.audit('Client Service - updating attendee to end customer', {
                        eventId: eventId,
                        endCustomerId: endCustomerId,
                        crdContractorId: customerId
                    });

                    const eventForAttendees = record.load({
                        type: record.Type.CALENDAR_EVENT,
                        id: eventId
                    });

                    // Get the attendee sublist
                    const attendeeSublistId = 'attendee';
                    const lineCount = eventForAttendees.getLineCount({ sublistId: attendeeSublistId });

                    log.audit('Client Service - current attendees before modification', {
                        lineCount: lineCount,
                        crdContractorId: customerId,
                        crdContractorIdType: typeof customerId
                    });

                    // Remove existing customer attendees (the CRD contractor that was auto-added)
                    // Work backwards to avoid index shifting issues
                    for (let i = lineCount - 1; i >= 0; i--) {
                        const attendeeId = eventForAttendees.getSublistValue({
                            sublistId: attendeeSublistId,
                            fieldId: 'attendee',
                            line: i
                        });

                        log.audit('Client Service - checking attendee for removal', {
                            line: i,
                            attendeeId: attendeeId,
                            attendeeIdType: typeof attendeeId,
                            crdContractorId: customerId,
                            matches: String(attendeeId) === String(customerId)
                        });

                        // Remove if it's the CRD contractor (compare as strings to handle type differences)
                        if (String(attendeeId) === String(customerId)) {
                            eventForAttendees.removeLine({
                                sublistId: attendeeSublistId,
                                line: i
                            });
                            log.audit('Client Service - removed CRD contractor from attendees', {
                                removedAttendeeId: attendeeId,
                                line: i
                            });
                        }
                    }

                    // Add the end customer as attendee
                    const newLineCount = eventForAttendees.getLineCount({ sublistId: attendeeSublistId });
                    eventForAttendees.insertLine({
                        sublistId: attendeeSublistId,
                        line: newLineCount
                    });
                    eventForAttendees.setSublistValue({
                        sublistId: attendeeSublistId,
                        fieldId: 'attendee',
                        line: newLineCount,
                        value: endCustomerId
                    });

                    eventForAttendees.save();
                    log.audit('Client Service - added end customer as attendee', {
                        eventId: eventId,
                        endCustomerId: endCustomerId,
                        finalAttendeeCount: newLineCount + 1
                    });
                } catch (attendeeError) {
                    log.error('Client Service - error updating attendees', {
                        eventId: eventId,
                        endCustomerId: endCustomerId,
                        error: attendeeError.message,
                        stack: attendeeError.stack
                    });
                    // Don't fail appointment creation if attendee update fails
                }
            }

            /*
            log.audit('Appointment created successfully', {
                eventId: eventId,
                userId: currentUser.id,
                title: title,
                date: appointmentDate,
                startTime: startTime,
                customerId: customerId,
                customerName: customerName,
                transactionId: transactionId,
                transactionLinked: transactionId ? 'attempted' : 'none',
                transactionUpdated: transactionId && eventId ? 'attempted' : 'none'
            }); */

            // Send SMS notification (non-blocking)
            // Type 10 = Create Appointment, Type 12 = Change Appointment (reschedule)
            // For Client Service appointments, use endCustomerId (the actual customer) instead of customerId (the CRD contractor)
            const smsCustomerId = isClientServiceEventType && endCustomerId ? endCustomerId : customerId;
            const smsCustomerName = isClientServiceEventType && endCustomerName ? endCustomerName : customerName;

            if (smsCustomerId) {
                try {
                    const smsType = originalAppointmentId ? smsNotification.SMS_TYPES.CHANGE_APPOINTMENT : smsNotification.SMS_TYPES.CREATE_APPOINTMENT;

                    // Get store name from location ID
                    let storeName = '';
                    if (storeLocation) {
                        try {
                            const locationLookup = search.lookupFields({
                                type: search.Type.LOCATION,
                                id: storeLocation,
                                columns: ['name']
                            });
                            storeName = locationLookup.name || '';
                        } catch (locErr) {
                            log.debug('Could not lookup store name', locErr.message);
                        }
                    }

                    // Get salesperson name and phone from employee record for consistency
                    const smsSalespersonName = salespersonId ? smsNotification.getSalespersonName(salespersonId) : salespersonName;
                    const smsSalespersonPhone = salespersonId ? smsNotification.getSalespersonPhone(salespersonId) : null;

                    // Format time for SMS
                    let smsTime = formatTimeForDisplay(startTime);

                    // For Cabinet Direct, convert time to customer's local timezone
                    const isCabinetDirect = smsNotification.isCabinetDirect(storeName);
                    if (isCabinetDirect && smsCustomerId) {
                        log.audit('Timezone conversion - Starting', {
                            customerId: smsCustomerId,
                            storeName: storeName,
                            originalTime: smsTime,
                            appointmentDate: appointmentDate
                        });

                        const customerTimezone = smsNotification.getCustomerTimezone(smsCustomerId, new Date(appointmentDate));

                        log.audit('Timezone conversion - Customer timezone result', {
                            customerId: smsCustomerId,
                            success: customerTimezone.success,
                            timezoneId: customerTimezone.timezoneId || null,
                            offsetMinutes: customerTimezone.offsetMinutes,
                            error: customerTimezone.error || null
                        });

                        if (customerTimezone.success && customerTimezone.offsetMinutes !== undefined) {
                            const convertedTime = smsNotification.convertTimeToCustomerTimezone(smsTime, appointmentDate, customerTimezone.offsetMinutes, customerTimezone.timezoneId);
                            log.audit('Timezone conversion - Time converted', {
                                originalTime: smsTime,
                                convertedTime: convertedTime,
                                timezoneId: customerTimezone.timezoneId
                            });
                            smsTime = convertedTime;
                        } else {
                            log.audit('Timezone conversion - Skipped (no timezone data)', {
                                customerId: smsCustomerId,
                                reason: customerTimezone.error || 'Unknown'
                            });
                        }
                    }

                    const smsResult = smsNotification.sendSMS({
                        smsType: smsType,
                        customerId: smsCustomerId,
                        data: {
                            store: storeName,
                            date: appointmentDate,
                            time: smsTime,
                            salesperson: smsSalespersonName || '',
                            salespersonPhone: smsSalespersonPhone || '',
                            customerName: smsCustomerName || ''
                        }
                    });

                    log.audit('SMS notification attempted for appointment', {
                        eventId: eventId,
                        smsType: smsType,
                        smsTypeName: originalAppointmentId ? 'CHANGE_APPOINTMENT' : 'CREATE_APPOINTMENT',
                        isCabinetDirect: isCabinetDirect,
                        timeUsed: smsTime,
                        isClientService: isClientServiceEventType,
                        smsCustomerId: smsCustomerId,
                        eventCustomerId: customerId,
                        success: smsResult.success,
                        error: smsResult.error || null
                    });

                    // Store MessageSid on Calendar Event for accurate inbound SMS tracking
                    if (smsResult.success && smsResult.twilioSid) {
                        try {
                            record.submitFields({
                                type: record.Type.CALENDAR_EVENT,
                                id: eventId,
                                values: {
                                    custevent_last_sms_sid: smsResult.twilioSid
                                }
                            });
                            log.debug('createAppointment', 'Stored MessageSid ' + smsResult.twilioSid + ' on event ' + eventId);
                        } catch (sidError) {
                            log.error('createAppointment', 'Failed to store MessageSid on event ' + eventId + ': ' + sidError.message);
                        }
                    }
                } catch (smsError) {
                    log.error('SMS send failed (non-blocking)', {
                        eventId: eventId,
                        customerId: customerId,
                        error: smsError.message
                    });
                    // Do NOT throw - appointment was created successfully
                }
            }

            return {
                success: true,
                eventId: eventId
            };
        } catch (error) {
            log.error('Error in createAppointment', {
                error: error.message,
                stack: error.stack,
                parameters: parameters
            });

            return {
                success: false,
                error: error.message
            };
        }
    }

    /**
     * Convert HTML time format (HH:MM) to NetSuite time format
     */
    function convertTimeForNetSuite(timeString, baseDate) {
        try {
            if (!timeString) return null;

            // Parse the time string (HH:MM format)
            const timeParts = timeString.split(':');
            if (timeParts.length !== 2) return null;

            const hours = parseInt(timeParts[0]);
            const minutes = parseInt(timeParts[1]);

            if (isNaN(hours) || isNaN(minutes)) return null;

            // Create a Date object with the time
            const timeDate = baseDate ? new Date(baseDate) : new Date();
            timeDate.setHours(hours);
            timeDate.setMinutes(minutes);
            timeDate.setSeconds(0);
            timeDate.setMilliseconds(0);

            return timeDate;
        } catch (error) {
            log.error('Error converting time for NetSuite', {
                timeString: timeString,
                error: error.message
            });
            return null;
        }
    }

    /**
     * Parse appointment date string to Date object
     */
    function parseAppointmentDate(dateString) {
        try {
            if (!dateString) return null;

            // Handle YYYY-MM-DD format (HTML date input)
            if (dateString.includes('-')) {
                const parts = dateString.split('-');
                if (parts.length === 3) {
                    const year = parseInt(parts[0]);
                    const month = parseInt(parts[1]) - 1; // Month is 0-indexed
                    const day = parseInt(parts[2]);
                    return new Date(year, month, day);
                }
            }

            // Handle MM/DD/YYYY format
            if (dateString.includes('/')) {
                const parts = dateString.split('/');
                if (parts.length === 3) {
                    const month = parseInt(parts[0]) - 1; // Month is 0-indexed
                    const day = parseInt(parts[1]);
                    const year = parseInt(parts[2]);
                    return new Date(year, month, day);
                }
            }

            // Try standard parsing
            const date = new Date(dateString);
            if (!isNaN(date.getTime())) {
                return date;
            }

            return null;
        } catch (error) {
            log.error('Error parsing appointment date', {
                dateString: dateString,
                error: error.message
            });
            return null;
        }
    }

    /**
     * Format date for HTML input (YYYY-MM-DD format)
     */
    function formatDateForHTMLInput(dateString) {
        try {
            if (typeof dateString === 'string' && dateString.includes('/')) {
                // Handle MM/DD/YYYY format from NetSuite
                const parts = dateString.split('/');
                if (parts.length === 3) {
                    const month = parseInt(parts[0]);
                    const day = parseInt(parts[1]);
                    const year = parseInt(parts[2]);

                    if (!isNaN(month) && !isNaN(day) && !isNaN(year)) {
                        // Format as YYYY-MM-DD for HTML input
                        const formattedMonth = month.toString().padStart(2, '0');
                        const formattedDay = day.toString().padStart(2, '0');
                        return year + '-' + formattedMonth + '-' + formattedDay;
                    }
                }
            }

            // Try to parse as a Date object, but use local timezone to avoid date shifts
            if (typeof dateString === 'string') {
                // If it's a date string, try to parse it safely without timezone issues
                const date = new Date(dateString + 'T12:00:00'); // Add noon time to avoid timezone shifts
                if (!isNaN(date.getTime())) {
                    const year = date.getFullYear();
                    const month = (date.getMonth() + 1).toString().padStart(2, '0');
                    const day = date.getDate().toString().padStart(2, '0');
                    return year + '-' + month + '-' + day;
                }
            }

            // If it's already a Date object, use it directly
            if (dateString instanceof Date && !isNaN(dateString.getTime())) {
                const year = dateString.getFullYear();
                const month = (dateString.getMonth() + 1).toString().padStart(2, '0');
                const day = dateString.getDate().toString().padStart(2, '0');
                return year + '-' + month + '-' + day;
            }

            // Fallback to today's date (use local timezone)
            const today = new Date();
            const year = today.getFullYear();
            const month = (today.getMonth() + 1).toString().padStart(2, '0');
            const day = today.getDate().toString().padStart(2, '0');
            return year + '-' + month + '-' + day;
        } catch (error) {
            log.error('Error formatting date for HTML input', { dateString, error: error.message });
            // Fallback to today's date (use local timezone)
            const today = new Date();
            const year = today.getFullYear();
            const month = (today.getMonth() + 1).toString().padStart(2, '0');
            const day = today.getDate().toString().padStart(2, '0');
            return year + '-' + month + '-' + day;
        }
    }

    /**
     * Format date for table display (MMM DD, YYYY format)
     */
    function formatDateForTable(dateString) {
        try {
            const date = new Date(dateString);
            if (!isNaN(date.getTime())) {
                return date.toLocaleDateString('en-US', {
                    month: 'short',
                    day: 'numeric',
                    year: 'numeric'
                });
            }
            return dateString;
        } catch (error) {
            return dateString;
        }
    }

    /**
     * Get primary details text
     */
    // Helper function to decode HTML entities (server-side version)
    function decodeHtmlEntitiesServer(text) {
        if (!text) return text;
        return text
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&amp;/g, '&')
            .replace(/&quot;/g, '"')
            .replace(/&#39;/g, "'");
    }

    function getDetailsPrimary(appt) {
        // Show the event message as primary detail if available
        if (appt.message && appt.message.trim()) {
            return decodeHtmlEntitiesServer(appt.message.trim());
        }

        // Fallback to existing logic
        if (appt.eventType && appt.eventType.toLowerCase().includes('sale')) {
            return 'SO-2025-004'; // Placeholder for sales order
        } else if (appt.eventType && appt.eventType.toLowerCase().includes('estimate')) {
            return 'EST-2025-047'; // Placeholder for estimate
        }
        return '';
    }

    /**
     * Get secondary details text
     */
    function getDetailsSecondary(appt) {
        // If we have a message, show additional info as secondary
        if (appt.message && appt.message.trim()) {
            if (appt.eventType && appt.eventType.toLowerCase().includes('sale')) {
                return 'Sales Appointment';
            } else if (appt.eventType && appt.eventType.toLowerCase().includes('estimate')) {
                return 'Estimate Appointment';
            }
            return appt.eventType || '';
        }

        // Fallback to existing logic
        if (appt.eventType && appt.eventType.toLowerCase().includes('sale')) {
            return '$890.25'; // Placeholder for amount
        } else if (appt.eventType && appt.eventType.toLowerCase().includes('estimate')) {
            return 'Living room flooring - hardwood installation'; // Placeholder for description
        }
        return '';
    }

